pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 + 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post-residuals that cannot host the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + 0.5 * post_residual as f64;
    }

    // Penalize leaving residual far below typical small-item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins whose post-residual stays near/above mean.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
    }

    // Slight preference for tighter fits as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the lookahead item
    // (or the smallest plausible item) are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        score += 60.0 + (min_useful - post_residual) as f64 * 4.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 20.0 * (item_size as f64 / (post_residual + item_size) as f64);
    }

    // Lookahead synergy: if the next item fits exactly into the post-residual gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 15.0; // next item won't fit here: mild penalty
        }
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; a fresh empty bin candidate gets a surcharge.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: only attractive when current bin residuals are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3 - 0.2 * (open_bins_count as f64);
        if mean_residual < 20.0 {
            score -= 40.0; // existing bins are nearly full; opening is fine
        }
    }

    // Slight preference for bins below the mean residual (fill emptier bins).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit reward.
        score -= 30.0;
    }

    // Favor bins whose residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Open-bins pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.5;
    }

    // Progress-aware tightening: dead space matters more late in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving almost no space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 500.0;
        } else if diff <= 3.0 {
            score -= 250.0 - 50.0 * diff;
        } else {
            // penalize residual that neither fits next item nor is tiny
            score += 0.6 * diff;
        }
        // If next item cannot fit in this bin's post residual, mild penalty
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual)
    // than the mean residual of open bins.
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Penalize large dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small unusable scrap is fine
    } else if post_residual >= 10 && post_residual < 40 {
        score += 0.3 * post_residual as f64; // mid-range waste is worst
    }

    // Early in the stream, allow opening new bins more freely;
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good fit exists.
        score += 120.0 - 80.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        score -= 40.0 * progress;
    }

    // Slight preference for bins with more open bins (spread consolidation).
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (>=1) can
    // use are wasted; small gaps (1..=9) are "dead" since items are >=1 but
    // typically much larger. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as f64) * 4.0;
    }
    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (small post_residual as
    // fraction of capacity).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is truly awful).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bins pressure: many open bins with slack -> prefer consolidating
    // into existing bins rather than fragmenting capacity further.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; filling low-slack bins keeps the fleet tidy.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.15;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 12.0;
        } else {
            // next item cannot use the gap: mild penalty proportional to gap
            score += (post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate logic: an empty bin has residual == capacity. Only
    // attractive when the item is large and no good existing fit exists,
    // or the stream is early and preserving small gaps matters later.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin; cheap when item is big.
        score = 30.0 - 20.0 * fill_fraction;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin leaves room for lookahead item
        }
        // Late in the stream, avoid spawning bins with tiny leftover potential.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && fill_fraction < 0.5 {
            score += 25.0 * (0.8 - progress).abs() * 10.0;
        }
    }

    // Mild preference for filling bins that are already mostly full.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals near multiples of common
    // item sizes (10,20,25,40,50) are more reusable; odd residuals are dead space.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // capacity fraction of the leftover

    // Penalize tiny-but-nonzero leftovers (dead space classes)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Reward residuals that land on harmonic classes (multiples of 10/20/25/50)
    if post_residual % 50 == 0 && post_residual > 0 { score -= 12.0; }
    else if post_residual % 25 == 0 && post_residual > 0 { score -= 8.0; }
    else if post_residual % 10 == 0 && post_residual > 0 { score -= 5.0; }
    else if post_residual % 5 == 0 { score -= 1.0; }
    else { score += 3.0; } // inharmonic leftover

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.1 * (next_item_size as f64);
        } else {
            // leftover too small for next item: penalize more if far off
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty for picking a bad one, favor tightest
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: opening a bin is expensive; only attractive when
    // the item is large relative to capacity or all open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 2.0 };
        let base = 0.55 * cap_f; // default cost of a fresh bin
        let discount = (pressure - 1.0).max(0.0) * 20.0
            + if fitting_bins_count == 0 { 30.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= item_size { 5.0 } else { 0.0 };
        score = base - discount + frac * 10.0;
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about spreading (consolidate into open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
        // prefer bins below mean residual (more filled bins first)
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is close to the item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness).powi(6) * 18.0;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { (post_residual as f64 / 20.0).powi(2) };
        score += dead * 3.0;
    }

    // Lookahead: reward residual that exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // residual too small for next item: mild penalty scaled by wasted fraction
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // last item: fill as fully as possible
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // bins fit poorly (large mean residual dispersion) early in the stream.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        let mut nb = 30.0; // baseline cost of opening a new bin
        nb -= open_bins_count as f64 * 1.5; // spreading load across bins can help
        nb -= waste * 20.0 * (1.0 - progress); // early on, big items justify new bins
        if next_item_size > 0 && next_item_size <= post_residual {
            nb -= 8.0; // fresh bin can host the next item too
        }
        if fitting_bins_count > 0 && tightness < 0.5 {
            nb -= 15.0; // existing fits are bad -> new bin more attractive
        }
        score += nb;
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins
    score += mean_residual * 0.03 * (open_bins_count as f64).ln().max(1.0);

    // Mild time decay of tightness reward late in the stream (consolidation phase)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

