pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is more tolerable if the next item can use it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 12.0; // gap too small for lookahead item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins when pressure is low,
    // reward it when open bins are congested (high mean residual / many bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 45.0 - 25.0 * congestion - 10.0 * progress;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // new bin useful for larger lookahead item
        }
    }

    // Open-bins pressure: mild reward for keeping bins few.
    score += (open_bins_count as f64).sqrt() * 0.5;

    // Prefer filling bins that are already partially used (tighter packing).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // exact chain: bin becomes perfectly reusable
        } else {
            score += diff * 0.8; // penalize mismatch with next item's demand
        }
        // If next item cannot fit after placement, penalize proportionally
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins whose residual is near mean (balanced packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize tiny unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when item barely fits anywhere else
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0; // open bin could still chain, prefer reusing
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

