        } else if post_residual > next_item_size {
            score -= 6.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
        } else {
            score += 4.0; // next item won't fit here; slight penalty for blocking
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when fits are poor or many bins are open.
    if bin_residual == bin_capacity {
        let fit_quality = (item_size as f64) / cap;
        let desperation = (fitting_bins_count as f64).max(1.0).ln() / (open_bins_count as f64 + 1.0).ln().max(1.0);
        score = cap as f64 * 0.9
            - 20.0 * fit_quality          // large items justify fresh bins
            + 10.0 * desperation           // many alternatives -> keep current bins
            - 15.0 * t;                    // late in stream, opening bins is fine
    }

    // Mild global pressure: prefer bins with below-average residual (keep balanced spread).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, smoothly warped by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling of post-residual with progress:
    // dead space penalized more strongly (quadratically) as stream advances.
    score += 60.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress) * cap * 0.01;

    // Cubic interaction: mid-range residuals slightly favored over extremes.
    let mid = (norm_pr - 0.5).abs();
    score += 8.0 * mid * mid * (1.0 + progress);

    // Tight fit reward (small post_residual), amplified by progress.
    if post_residual <= item_size / 2 {
        score -= 6.0 + 10.0 * progress;
    }

    // Last-chance bin: reward using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - diff / cap).max(0.0) * (1.0 + progress);
        // Penalize post_residual that strands next item.
        if next_item_size as f64 > pr && pr > 0.0 {
            score += 4.0 * (1.0 - pr / next_item_size as f64);
        }
    }

    // Prefer filling bins with many open bins (consolidation) early on.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Align with mean residual: bins close to mean are safer choices.
    score += (mean_residual - pr).abs() * 0.05;

    // New-bin candidate: penalize mildly so open bins are preferred unless
    // they leave very poor post-residual (dead space grows with progress).
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress * (1.0 - norm_pr);
        // But if item would leave large dead space in existing bins,
        // new bin becomes attractive: subtract when item is small relative.
        score -= 20.0 * (1.0 - item_size as f64 / cap) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division on C/10 (residual decile).
    let decile = post_residual / 10;
    score -= match decile {
        0 => 30.0,          // perfect / near-perfect fit: heavily reward
        1 => 18.0,          // 10..19 left: still a good harmonic slot
        2 => 8.0,           // 20..29: medium slot
        3 => 2.0,           // 30..39: mild
        4 => -4.0,          // 40..49: half-empty, penalize slightly
        5 => -10.0,         // 50..59: bad dead space
        6 => -14.0,
        7 => -17.0,
        8 => -19.0,
        _ => -21.0,         // huge leftover: strongly penalize
    };

    // Fine harmonic bonus: exact multiples of 10 in post_residual are
    // ideal landing slots for future decile-class items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: does the leftover harmonic class match the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportional to tightness of that fit.
            let lookahead_tightness = (post_residual - next_item_size) as f64;
            score -= 10.0 + 20.0 / (1.0 + lookahead_tightness / 5.0);
            if post_residual - next_item_size <= 5 {
                score -= 15.0; // chain of near-perfect fits
            }
        } else {
            // Next item cannot use the leftover: penalize dead space creation.
            score += 6.0 + 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // would leave a bad harmonic class in every fitting bin.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 45.0;
        // Large items deserve fresh bins (they leave usable 20..90 residue).
        if item_size >= 50 {
            score -= 20.0;
        }
        // If many bins are open with large mean residual, prefer reusing them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for tighter bins among equals (best-fit flavor).
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    // Reward bins whose residual is in the same harmonic class as the item,
    // enabling modular reuse of space.
    if bin_residual % 10 <= item_size % 10 && bin_residual >= item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual > 9 && post_residual < 20 {
        // Medium gaps: mild penalty, still somewhat usable.
        score += 10.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward residual that can still fit a typical item (>= 20 usable).
    if post_residual >= 20 {
        score -= 5.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + (open_bins_count as f64) * 2.0;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= (open_bins_count as f64).min(20.0) * 1.5;
    }

    // Last-chance bin: strongly favor placing here to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Early stream: mild preference for keeping residuals balanced via mean residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64) * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: prefer bins where the item leaves minimal dead space.
    let tight_fit = (post_residual as f64) / bin_capacity as f64;
    score += tight_fit * 20.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as i32;
        if next_fits == 1 {
            // Exact match to next item is extremely desirable (chain packing).
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to wasted potential.
            let overflow = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.5 * overflow;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    // Leaving below-average residual means this bin absorbs more slack -> good.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins as the stream matures; early on allow it for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress;
        // A new bin is justified only if no open bin leaves a decent post-fit state.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 <= mean_residual {
            score -= 25.0;
        }
    }

    // Slight preference to fill bins with many siblings already open (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to hold a typical future item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; mild penalty unless residual is tiny anyway
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Spread pressure: with many open bins, prefer consolidating into low-residual bins.
    score += 0.15 * (open_bins_count as f64).sqrt() * (bin_residual as f64 - mean_residual) * 0.05;

    // Late in the stream, close out bins aggressively: favor exact/near-exact fits.
    if progress > 0.8 {
        score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing else fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            let best_possible = fill_ratio; // fill ratio of this empty bin
            40.0 * (1.0 - best_possible)
        };
        score += 15.0 + desperation;
        // Early stream: opening bins is cheap-ish; late stream: avoid it.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: penalize residual quadratically, modulated by stream progress
    let pr_norm = pr / cap;
    score += 8.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 4.0 * (0.3 + 0.7 * progress);

    // Dead-space penalty: residual too small for typical future items
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 6.0 * dead * dead;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 3.0 * (nx / cap);
        } else {
            score += 2.0 * (nx / cap) * (1.0 - pr_norm);
        }
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 5.0 + 2.0 * openness * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mean-residual deviation coupling
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions define "usable" zones.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residual that no plausible item (1..=100) can pair well with.
    // Items 1..100 -> residual < 1 is perfect; residual in [1, 10) is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes: post_residual mod 10 — small residues divisible into common
    // item-size increments (10,20,...) are reusable by future items.
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        // Residual is a multiple of 10: highly reusable.
        score -= 8.0;
    } else if harmonic >= 7 {
        // Close to next multiple of 10: small filler item can round it down.
        score -= 3.0;
    } else {
        // Awkward middle residue (1..=6): poor future compatibility.
        score += 6.0;
    }

    // Capacity-fraction thresholds: residual in upper half of bin is "healthy".
    let half = cap / 2.0;
    if post > half {
        score -= 5.0;
    } else if post <= cap * 0.2 {
        // Very small residual: likely dead space unless it's zero.
        if post_residual > 0 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item slightly overflows, penalize (near-miss).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // Next item fits: how harmonically? mod-10 alignment bonus.
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 {
                score -= 12.0;
            }
            score -= (rem as f64).min(10.0) * 0.5;
        } else {
            // Next item doesn't fit in this bin after placement: mild penalty,
            // scaled by how close we were (integer-division threshold).
            let over = next_item_size - post_residual;
            if over <= 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 15.0;
    }

    // New-bin candidate: empty bin has post == cap. Opening a new bin is only
    // attractive when the current item is large and all fits would leave big residue.
    if bin_residual == bin_capacity {
        // Slight default preference to reuse existing bins:
        score += 12.0;
        // But if item is huge (> 60), a fresh bin gives clean packing potential.
        if item_size > 60 {
            score -= 20.0;
        }
        // If no open bin can even fit the item, this call wins anyway via others' penalties.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    // Mean-residual coupling: when open bins are loose on average, prefer tight fits
    // to keep the fleet balanced.
    score += (mean_residual - post).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64) / 13.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is "well-used" relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if placing here would create dead space
    // or this bin is already very tight.
    if bin_residual == bin_capacity {
        let dead_space_risk = if post_residual <= 12 && post_residual > 0 { 1.0 } else { 0.0 };
        score = score - 10.0 + 55.0 * dead_space_risk + 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item can exactly use the post residual, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item would be blocked by the resulting residual, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for bins tighter than the mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: later in stream, tighter packing matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item => strong reward.
        if diff == 0.0 {
            score -= 60.0 + 40.0 * progress;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward proportional to closeness.
            score -= (30.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += 10.0 + 20.0 * progress;
        }
    }

    // Relative to mean residual: prefer bins whose post-residual is below average
    // (concentrating waste) and penalize leaving above-average slack.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    if mr > 0.0 {
        score += 0.5 * (post_residual as f64 - mr);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is huge waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual as f64 > mr + 30.0 {
            score += 30.0; // but avoid dumping into a nearly-empty bin wastefully
        }
    }

    // New-bin candidate handling: opening a new bin should only win when it enables
    // a near-perfect fit for the upcoming item or current open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base mild penalty so new bins are used only when clearly better.
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // New bin would leave residual (C - item) that may fit next item well.
            let nr = bin_capacity - item_size;
            if nr == next_item_size {
                score -= 100.0; // reserve fresh bin for perfect next-item fit
            }
        }
        if open_bins_count == 0 {
            score -= 200.0; // no alternative
        }
    }

    // Small bonus for tight fits now (low post residual) scaled by progress.
    score -= 0.1 * (bin_capacity - post_residual) as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // next item cannot fit here; mild penalty scaled by wasted potential
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or when good fits exist.
        score += 20.0 * progress;
        if fitting_bins_count > 0 && post_residual == 0 {
            // perfect fit available elsewhere -> keep new bin closed
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            // large next item: a fresh bin may be valuable
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    } else {
        // Existing bin: reward usage more heavily later in the stream.
        score -= 10.0 * progress;
    }

    // Global residual context: if mean residual is high, avoid leaving this bin fragmented.
    if mean_residual > (item_size as f64) {
        score += 2.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let base = post * (1.0 + progress * (1.0 - progress) * 2.0);

    // Penalize small but nonzero post_residual (dead space), smoothly via polynomial
    let dead = (norm_post * (1.0 - norm_post)).powi(2) * 20.0;

    // Reward tight fits: item_size fraction of bin
    let fit_bonus = (item_size as f64 / cap) * (1.0 + progress);

    // Lookahead: penalize if next item fits poorly into post_residual
    let look = if next_item_size > 0 && (next_item_size as u32) <= post_residual as u32 {
        -((next_item_size as f64 / cap) * 10.0)
    } else if next_item_size > 0 {
        (next_item_size as f64 / cap) * 5.0
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using it
    let last = if fitting_bins_count == 1 { -15.0 } else { 0.0 };

    // Mean residual alignment: prefer bins close to mean residual
    let align = ((bin_residual as f64 - mean_residual).abs() / cap) * 3.0;

    // New-bin candidate: mild penalty so open bins are preferred unless fit is bad
    let new_bin = if bin_residual == bin_capacity { 5.0 + progress * 5.0 } else { 0.0 };

    base + dead - fit_bonus + look + last + align + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post_residual (tight fits).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead space classes".
    // Residue classes near the item-size granularity (10) are reusable; odd/awkward
    // residues (e.g. 1,3,7,9) are penalized since few future items can use them.
    let r = post_residual % 10;
    let residue_penalty = match r {
        0 => -12.0,          // perfectly reusable class
        1 | 9 => 6.0,        // nearly unusable slivers
        2 | 8 => 1.0,
        3 | 7 => 4.0,
        4 | 6 => -1.0,
        _ => 0.0,            // 5: half-class, neutral
    };
    score += residue_penalty;

    // Integer-division thresholds on post_residual: small leftovers (<10) are dead
    // space; large leftovers (>50) mean the bin was underfilled badly.
    if post_residual < 10 {
        score -= 8.0;        // near-perfect packing, reward strongly
    } else if post_residual > 50 {
        score += 5.0;        // wasteful placement into a large bin
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual
    // (harmonic match), strongly reward; if post_residual < next item, penalize
    // proportionally (dead space relative to the known future demand).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 + (post_residual - next_item_size) as f64 / 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 / 4.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: the empty bin should only win when the fit into
    // existing bins is poor (large post_residual) or no good harmonic class exists.
    if bin_residual == bin_capacity {
        // Reward new bin when current fit is loose relative to capacity fractions.
        let fit_fraction = item_size as f64 / bin_capacity as f64;
        if post_residual as f64 > bin_capacity as f64 * 0.5 {
            score -= 10.0;   // item is small; opening a fresh bin keeps big bins flexible
        }
        if fit_fraction > 0.8 {
            score += 8.0;    // large items should go into open bins, not fresh ones
        }
        // Slight default bias against new bins to avoid bin explosion.
        score += 4.0;
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Post-residual that cannot accommodate the next item is dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward bins whose leftover fits the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer consolidation when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins tighter than the mean residual (best-fit coupling).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, allow opening bins more freely; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal: strongly reward post_residual == 0.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward exact match with the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match means the next item can perfectly fill this bin.
        if gap == 0.0 {
            score -= 150.0;
        } else {
            // Penalize small-but-nonzero gaps: dead space the next item can't use.
            score += gap * 0.6;
            // Bonus if the next item still fits (chained packing).
            if next_item_size <= post_residual {
                score -= 25.0;
            }
        }
    }

    // Compare against mean residual: bins with residual far below mean
    // are already "tight"; using them is cheap, so slightly reward.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    } else {
        score += (res - mean_residual) * 0.10;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: it should only win when no open bin offers a
    // decent fit. Give it a moderately high baseline so open bins with
    // good fits (low post_residual, lookahead match) beat it, but bins
    // with large dead space do not.
    if bin_residual == bin_capacity {
        // New bin: score proportional to wasted potential given item size.
        score = (bin_capacity - item_size) as f64 + 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // new bin can also host the next item
        }
    }

    // Late in the stream, residual waste matters more (less time to fill it).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += res * progress * 0.5;

    // Many open bins: prefer consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tightness of fit: fraction of the bin consumed by placing the item
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual small relative to capacity
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 8.0;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 1.5;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 4.0 * (1.0 - progress);
    }
    // If next item almost fits (small gap), mild penalty — creates awkward state
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 2.0 * (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is expensive when other bins fit
    if is_new_bin {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        // Base cost of a fresh bin
        score += 20.0;
        // If few bins fit the item, opening a new bin is more acceptable,
        // especially early in the stream or when open bins are crowded (low mean residual)
        score -= scarcity * 14.0;
        score -= (1.0 - progress) * 6.0;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 8.0; // open bins are nearly full; fresh bin is fine
        }
        // Large items deserve fresh bins to avoid fragmentation
        if fill > 0.6 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (use up crowded space)
    if !is_new_bin {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.05;
        // Mild penalty for spreading across too many bins
        score += open_bins_count as f64 * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual
    let pr = post_residual as f64 / cap;

    // Non-linear polynomial coupling: post_residual interacts with progress
    // Early on, prefer tight fits (low post_residual); late, tolerate slack less
    let progress_coupling = progress * pr * pr * cap * 0.5;
    score += progress_coupling;

    // Quadratic dead-space penalty amplified by item size
    let dead = pr * pr * (item_size as f64 / cap);
    score += dead * cap * 0.3;

    // Smooth fit quality: cubic in item_size relative to capacity
    let fit_quality = (item_size as f64 / cap).powi(3) * cap;
    score -= fit_quality * 0.4;

    // Penalize low post_residual that becomes unusable: smooth sigmoid-like term
    if post_residual > 0 {
        let unusable = 1.0 - (post_residual as f64 / 10.0).tanh();
        score += unusable * cap * 0.2;
    }

    // Last-chance bonus: only one fitting bin -> reward using it
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64) * 0.25;
    }

    // Mean residual deviation: smooth quadratic deviation term
    let dev = post_residual as f64 - mean_residual;
    score += dev * dev * 0.01;

    // New-bin candidate: base penalty scaled by open bins and progress
    if bin_residual == bin_capacity {
        score += cap * (1.0 + 0.05 * open_bins_count as f64) * (0.5 + 0.5 * progress);
        // But if item is large relative to mean residual of open bins, soften
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 0.0 {
            score -= mean_gap * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base tightness reward: strongly favor small post_residual.
    score -= (1.0 - (post_residual as f64) / cap) * 60.0;

    // Harmonic class of post_residual: classify dead space by integer division.
    // Residuals in [0..12] are near-perfect; [13..30] decent; [31..55] awkward; [56..99] fine.
    let post_class = post_residual / 13; // 0..7 harmonic class
    match post_class {
        0 => score -= 45.0,                       // near-perfect fit
        1 => score -= 20.0,                       // good
        2 => score -= 8.0,                        // acceptable
        3 => score += 10.0,                       // awkward dead space
        4 => score += 18.0,
        5 => score += 12.0,
        _ => score -= 5.0,                        // large residual still usable
    }

    // Modulo coupling: post_residual divisible by common item sizes (10,20,25,50)
    // leaves reusable space for future arrivals.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 10.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 8.0; }
    }

    // Exact fit is golden.
    if post_residual == 0 { score -= 100.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 70.0; }
        else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 40.0;
        } else if post_residual < next_item_size {
            // post_residual too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // If next item also fits and post_residual is a multiple of next size
        if next_item_size > 0 && post_residual >= next_item_size
            && post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to keep diversity.
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 2.0;
    }

    // New-bin candidate logic: empty bin should lose unless current bins fit poorly.
    if bin_residual == bin_capacity {
        // Opening a new bin is bad early / when open bins are few and mean residual large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0
            - mean_residual * 0.35
            - (open_bins_count as f64) * 1.5
            - progress * 10.0;
        // If next item is huge, a fresh bin is more attractive.
        if next_item_size >= 60 { score -= 20.0; }
    } else {
        // Reusing an open bin reduces bin count: reward.
        score -= 12.0;
        // Prefer bins with residual below mean (consolidate waste).
        if (bin_residual as f64) < mean_residual { score -= 6.0; }
    }

    // Stream progression: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let min_item = 1.0f64;
        let max_item = 100.0f64;
        // Gap too small for the smallest possible future item is pure dead space.
        if (post_residual as f64) < min_item {
            score += 1000.0;
        }
        // Gap that cannot fit the lookahead item is partially wasted.
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 25.0 * (1.0 - (post_residual as f64) / max_item);
        }
        // Smooth dead-space curvature: small gaps are disproportionately bad.
        let pr = post_residual as f64;
        score += 30.0 * (-pr / 20.0).exp();
    } else {
        // Perfect fit is highly desirable.
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new empty bin candidate gets penalized via its high residual implicitly,
    // but add explicit pressure proportional to open bins).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (consume the tight bins first, keep loose bins flexible).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.3 * dev;
    }

    // Lookahead synergy: if the post residual exactly fits the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is nearly free.
        score -= 60.0 * (-0.08 * diff).exp();
        // If post_residual exactly fits next item, huge reward.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving a residual that can't hold the next item but is too small to be useful.
        if post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 20.0;
    }

    // Dead-space penalty: small unusable leftovers are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild preference for reusing existing bins over opening new ones,
    // scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    // Encourage consolidating into bins with more relative fullness.
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 - p) * 8.0
                 + norm_pr * p * p * 6.0
                 + norm_pr.powi(3) * (p - 0.5) * 10.0;
    score += coupling * cap * 0.05;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 3.0 * p) * 4.0;

    // Penalize dead space below plausible future item sizes
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr > 0.0 && pr < ni {
            score += (ni - pr) * (0.5 + p);
        } else if pr >= ni {
            score -= 2.0 + 3.0 * p;
        }
    } else {
        // last item: strongly prefer exact fill
        score -= (cap - pr) * 0.1;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * p;
    }

    // Mild pressure toward consolidating open bins
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Mean residual alignment bonus
    let dev = (pr - mean_residual).abs();
    score += dev * 0.02 * (1.0 - p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common item
    // granularities are more reusable than "dead" residues.
    let pr = post_residual;
    let mut usable_bonus = 0.0f64;
    for &m in &[10u32, 20, 25, 50] {
        if pr >= m && pr % m == 0 {
            usable_bonus += 6.0 + (pr / m) as f64 * 0.5;
        }
    }
    // Small prime-ish residues (1..=3) are nearly dead space.
    if pr <= 3 && pr > 0 {
        score += 8.0;
    }
    score -= usable_bonus;

    // Exact fit is ideal.
    if pr == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residue; scale by how much slack
            let leftover = pr - next_item_size;
            score -= 6.0 - (leftover as f64) * 0.05;
        } else {
            // next item won't fit here; penalize large post residuals slightly
            score += (pr as f64) * 0.02;
        }
    }

    // New-bin candidate: only prefer opening a new bin when the current item
    // leaves a badly-shaped residue in every existing bin and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        // New bin starts with big residual: attractive if item is big (tight packing)
        score -= (item_size as f64) * 0.3;
        // Early in stream, opening bins is cheaper; late, prefer filling old bins.
        score -= 10.0 * (1.0 - progress);
        // If many bins are open already, discourage proliferation.
        score += open_bins_count as f64 * 0.4;
        // If mean residual across open bins is large, we should use them instead.
        score += mean_residual * 0.15;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(-30.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly worthless.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space: heavy penalty.
            score += 40.0 + (10.0 - pr) * 4.0;
        } else if post_residual <= 20 {
            // Hard-to-fill small gap: moderate penalty.
            score += 12.0;
        } else if post_residual >= 30 && post_residual <= 60 {
            // Mid-range leftovers remain reusable: mild reward.
            score -= 6.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize new-bin candidate.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty scaled by pressure.
        score += 15.0 + bin_pressure * 30.0;
        // Allow new bin only if no tight fit exists anywhere (approximate:
        // if item is large relative to typical residuals, new bin is fine).
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight reward as pressure grows.
        score -= bin_pressure * 5.0;
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item barely misses, the gap is less attractive.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Early stream: be more conservative with opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item leaves only a tiny unusable sliver.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack * 0.15);
    }
    // Next item doesn't fit here: penalize dead space relative to next item.
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap.min(40.0) * 0.8;
    }

    // Penalize creating very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward exact fills.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Compare residual against the mean of open bins: below-mean leftover is good.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual == next_item_size;
        let base = bin_capacity as f64 * 0.75;
        score += if good_fit_exists { -10.0 } else { base };
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64 / bin_capacity as f64);

    // Perfect-fit bonus: leaving nothing behind is extremely valuable.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that is too small for typical future items
    // (fragmentation trap), unless it is exactly zero.
    if post_residual > 0 && post_residual < 15 {
        score += 6.0;
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 6.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: post-residual becomes dead space
            // until something smaller arrives; penalize proportionally.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // so only open a new bin when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (grows mildly with bin count
        // to discourage bin proliferation early).
        score += 20.0 + 0.5 * open_bins_count as f64;
        // But if the item is large, a fresh bin is naturally attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins already fit the item, opening another is wasteful.
        if fitting_bins_count > 2 {
            score += 8.0 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // Global state coupling: prefer placing into bins whose residual is
    // below the mean (i.e., filling the emptiest-relative bins) to keep
    // a pool of usable mid-size residuals.
    let bin_res_f = bin_residual as f64;
    if bin_residual != bin_capacity {
        if bin_res_f < mean_residual {
            score -= 2.5;
        } else {
            score += 1.5 * ((bin_res_f - mean_residual) / bin_capacity as f64);
        }
    }

    // Dynamic time horizon: early in the stream, be conservative with
    // tight fits (keep flexibility); late in the stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Mild penalty for spreading across many bins when few fit options exist.
    if open_bins_count > 0 {
        score += 0.3 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let residual_norm = bin_residual as f64 / bin_capacity as f64;
    let post_norm = post_residual as f64 / bin_capacity as f64;
    let item_norm = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: smooth polynomial coupling of fill ratio with stream progress.
    // Tight fits (small post_residual) get progressively more valuable later in the stream.
    let tightness = 1.0 - post_norm; // 1.0 when bin is exactly filled
    let tight_reward = tightness * tightness * (6.0 + 10.0 * progress);
    score -= tight_reward;

    // Penalize leaving awkward residuals: quadratic blow-up for small-but-unusable
    // post-residuals (too small for typical items), modulated by progress.
    let dead = if post_norm > 0.0 && post_norm < 0.10 {
        (0.10 - post_norm) * (0.10 - post_norm) * 40.0
    } else {
        0.0
    };
    score += dead * (0.5 + progress);

    // Lookahead: if next item fits into the post-residual, reward preserving that space;
    // otherwise penalize blocking the next item.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        if post_residual >= next_item_size {
            score -= 2.0 * (1.0 - (post_norm - next_norm).abs()) * (1.0 + progress);
        } else {
            score += 3.0 * next_norm * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and later in the stream (encourage consolidating into existing bins).
    if bin_residual == bin_capacity {
        let open_factor = (open_bins_count as f64).ln() + 1.0;
        score += 4.0 * open_factor * (0.6 + progress);
        // Allow opening a new bin when existing residuals are large and fragmented.
        score -= (mean_residual / bin_capacity as f64 - post_norm).abs() * 2.0;
    }

    // Mild global pressure: prefer bins whose residual is below the mean (fill emptier
    // space first), via smooth saturating coupling.
    let mean_gap = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score += mean_gap * (1.0 + progress) * 1.5;

    // Smooth non-linear interaction: fill ratio times progress shaping of the base score.
    score -= (residual_norm * residual_norm) * (2.0 + 3.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter of capacity the leftover lives in.
    let quarter = post_residual / (bin_capacity / 4);
    let quarter_bonus = match quarter {
        0 => -12.0, // very tight fit: excellent packing
        1 => -4.0,  // moderate leftover
        2 => 2.0,   // half-empty bin, mediocre
        _ => 6.0,   // nearly empty bin: wasteful placement
    };
    score += quarter_bonus;

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic class via integer division: leftover divisible by common item sizes
    // means the residual remains "usable" for typical future items.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 3.0;
                break;
            }
        }
        // Penalize dead space: residual too small for the smallest plausible item.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Lookahead coupling: can the bin also host the next item after this one?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // chain fit: keep using this bin
        } else if post_residual > 0 {
            score += 5.0; // residual stranded relative to lookahead
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: make it unattractive unless everything else is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if mean residual is tiny (all bins nearly full), opening fresh is fine.
        if mean_residual < 20.0 {
            score -= 35.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Slight preference for bins whose residual is close to the mean (balance).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold typical
    // future items are "dead". Penalize them super-linearly.
    if post_residual > 0 {
        let dead_threshold = 12.0; // smallest useful residual for future items
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
        // Perfect fit: strongly reward zero residual.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward tight fits generally (small relative post residual).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 10.0;

    // Penalize bins whose residual is barely above the item (wasteful placement
    // leaving near-dead space), but only if not a perfect fit.
    let slack = bin_residual as f64 - item_size as f64;
    if slack > 0.0 && slack < 5.0 {
        score += 4.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins and
    // encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or
        // when other bins can still fit the item.
        score += 30.0 + pressure * 5.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // If no existing bin fits, opening a new bin is necessary: soften.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Existing bin: reward being one of few fitting bins (last chance).
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Favor bins below mean residual (hungrier bins get filled first),
        // keeping the residual distribution balanced.
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact 1-step fill
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: strongly reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            // next item can also fit here: excellent chaining
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize by the overshoot
            score += 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny dead space that nothing (min size 1..) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 1 {
            score += 30.0; // discourage abandoning the only fitting bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 1.0; // slight edge for fresh bin when lookahead is large
        }
    }

    // Late in the stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize small unusable residuals (dead space) more than large residuals,
    // since small gaps are hard to fill later.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dead = if pr < 10.0 { 25.0 } else if pr < 20.0 { 12.0 } else { 0.0 };
        score += dead;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it packs
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize bins that would strand the lookahead
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward so we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation into fewer bins.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Time horizon: late in the stream, favor closing bins tightly (avoid leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (pr / bin_capacity as f64);

    // Global state: if mean residual across open bins is high, opening new bins
    // is wasteful; penalize the new-bin candidate (residual == capacity).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 15.0 + 25.0 * pressure + (open_bins_count as f64).sqrt() * 3.0;
        // But early on, new bins are cheap.
        score -= 20.0 * (1.0 - progress);
    }

    // Reward using bins that are already substantially filled (consolidation).
    let pre_fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * pre_fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Tight fit reward: strongly favor small post_residual via non-linear coupling
    score -= (cap - pr) * (pr / cap).powi(3) * 2.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize post_residual that matches next item poorly: if next item fits, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 25.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 10.0 * ((nx - pr) / cap);
        }
    }

    // Late stream: consolidate more aggressively
    score -= 18.0 * progress * (pr / cap) * (pr / cap);

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new bins when good fits exist, scaled by open bin count
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 && pr < 30.0 {
            score += 20.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    score += 0.15 * (pr - mean_residual).abs().sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect, near-perfect, poor fits.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if pr <= 10 {
        // Small dead space: mildly reward.
        score -= 25.0 - pr as f64;
    } else {
        // Classify residual by modulo classes of capacity fractions.
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        if pr % quarter == 0 || pr % 10 == 0 {
            // Residual in a "reusable" harmonic class: moderate penalty only.
            score += 2.0;
        } else if pr < half {
            // Medium odd residual: penalize extra.
            score += 8.0;
        } else {
            // Large residual: bin still very usable, slight penalty.
            score += 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0_f64.min((20 - slack as i32 as i64) as f64).max(-20.0);
            if slack <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this residual at all: penalty scaled by waste.
            let gap = next_item_size - pr;
            if gap <= 10 {
                score += 3.0;
            } else {
                score += 6.0;
            }
        }
    } else {
        // Last item: any residual is pure waste; reward tight fits harder.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: default mild preference unless current bin fits poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 45.0;
        // Opening a new bin is attractive if the item is large and would leave
        // a bad residual class elsewhere, or if next item is huge.
        if item_size >= bin_capacity / 2 && next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        if post_residual == 0 {
            // item == capacity in the new bin: perfect.
            score -= 60.0;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // More open bins -> prefer packing into existing ones.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Slight global preference for reusing bins as open bins accumulate.
        score -= (open_bins_count.min(20) as f64) * 0.3;
        // Favor bins whose residual is below the mean (denser bins).
        score += ((bin_residual as f64) - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 (min item size) are unusable.
    if post_residual < 10 {
        score += 25.0; // creating dead space is worse than a large leftover
    } else if post_residual <= 20 {
        score -= 8.0; // small but still usable gap: mild reward
    }

    // Reward very tight fits (nearly perfect packing).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 && post_residual >= 1 {
        score -= 5.0; // tight, but dead space
    }

    // Lookahead: if the next item can fit into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits (small shortfall), slight penalty for blocking.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
        score += 4.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize relative to how well existing bins fit.
        let pressure = (open_bins_count as f64) * 1.5 + (mean_residual / 10.0);
        // If this is the only fitting bin, opening a new bin is bad.
        if fitting_bins_count <= 1 {
            score += 40.0 + pressure;
        } else {
            score += pressure;
        }
    } else {
        // Existing bin: last-chance bonus to fill a bin about to be abandoned.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Slight preference for bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late in the stream, prioritize closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 2.0;
        if post_residual == next_item_size {
            score -= 400.0; // chain: this bin will be perfectly filled next step
        }
        // Penalize leaving dead space the next item cannot use
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 50.0;

    // Relative to mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves unusable sliver.
    if bin_residual == bin_capacity {
        let sliver = post_residual > 0 && post_residual < 10;
        let lookahead_bad = next_item_size > 0 && next_item_size > post_residual && post_residual > 0;
        if !(sliver || lookahead_bad) {
            score += 300.0;
        } else {
            score -= 50.0;
        }
    }

    // Early in stream: slight preference to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
