pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Non-linear waste penalty: dead space becomes quadratically worse as stream progresses.
    let norm_pr = pr / cap;
    score += 60.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Tight fits rewarded via smooth cubic of fill ratio.
    let fill = (item_size as f64) / cap;
    score -= 25.0 * fill * fill * fill;

    // Last-chance bin bonus (smooth, capped).
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead coupling: favor residual that still fits the next item smoothly.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 12.0 * fits_next * (next_item_size as f64 / cap);
    } else {
        score -= 10.0 * norm_pr; // final items: use up space
    }

    // New-bin candidate: penalize opening a bin early, less so late or when crowded.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference for bins below mean residual (balance residuals smoothly).
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: which "mod band" the leftover falls into.
    // Residuals that are multiples of small units (<=10) are reusable by small items;
    // odd mid-range residuals (e.g. 11..19, 21..29) are dead space.
    let pr = post_residual;
    let harmonic_waste: f64 = if pr == 0 {
        -30.0 // perfect fit, strong reward
    } else if pr <= 5 {
        -8.0 + pr as f64 * 0.5 // tiny leftovers: nearly perfect
    } else if pr <= 10 {
        -4.0 + pr as f64 * 0.3 // reusable by min-size items
    } else if pr <= 20 {
        10.0 + (pr - 10) as f64 * 1.2 // dead zone: too big to ignore, too small to use
    } else if pr <= 30 {
        4.0 + (pr - 20) as f64 * 0.4 // partially recoverable
    } else if pr <= 50 {
        1.0 + (pr - 30) as f64 * 0.15 // decent working residual
    } else {
        -1.0 // large residual: bin stays flexible
    };
    score += harmonic_waste;

    // Lookahead: does the next item fit into post_residual? Reward exact harmonic match.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap).max(0.0); // tight lookahead fit rewarded
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; penalize bins whose leftover traps us
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, adjusted by stream position and openness.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 18.0 + 10.0 * progress + open_bins_count as f64 * 0.5;
        // If item is large, opening fresh is fine
        if item_size as f64 > 0.6 * cap {
            score -= 6.0;
        }
    }

    // Prefer bins tighter than average (best-fit flavor) with harmonic scaling.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Penalize leaving residuals in awkward modular classes (mod 7 bands).
    let m = pr % 7;
    if m == 1 || m == 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: small leftover gaps are nearly unusable
    // (items >= 1, but gaps far below the typical item size waste capacity).
    if post_residual > 0 {
        let gap = post_residual as f64;
        // gaps below ~10 are pure dead space
        if post_residual < 10 {
            score += 40.0 * (1.0 - gap / 10.0);
        } else {
            // mild superlinear penalty on moderate gaps
            score += 0.05 * gap;
        }
        // gap too small for the lookahead item: extra penalty
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        // gap exactly usable by the next item: big reward (perfect chaining)
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 30.0;
    }

    // Reward tight fits (high fill ratio of the residual)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading; a new empty bin candidate
    // (bin_residual == bin_capacity) gets penalized when pressure is high.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
    }

    // Slight preference for bins with residuals above the mean
    // (keep low-residual bins for smaller future items).
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize leaving dead space that no typical item can use
    // (residuals in 1..10 are hard to fill when items are >= 10).
    if post_residual >= 1 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: check if the next item can still fit in the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: next item also fits here, chain placement.
            score -= 10.0 + (next_item_size as f64) * 0.15;
        } else if next_item_size > bin_capacity - (item_size as f64) as u32 {
            // Next item can't fit anywhere after this placement anyway; neutral.
        } else {
            // Placing here blocks the next item; penalize proportionally.
            let block = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.10 * block;
        }
    }

    // Global pressure: when many bins are open with high mean residual,
    // encourage filling existing bins rather than spreading.
    let pressure = mean_residual / (bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New-bin candidate: base penalty so it's chosen only when attractive.
        score += 20.0;
        // Reduce penalty when existing bins are mostly full (low mean residual)
        // or when few bins fit the item (fragmented state).
        score -= 30.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 35.0;
        } else if fitting_bins_count == 1 {
            score += 10.0; // keep using the single fitting bin
        }
    }

    // Time horizon: early in the stream, be conservative about opening bins;
    // late in the stream, allow slightly more aggressive consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Mild preference to balance load across bins: avoid dumping into the
    // single fullest bin when alternatives exist.
    let this_load = (bin_capacity as f64 - bin_residual as f64) / (bin_capacity as f64);
    if open_bins_count > 1 && this_load > 0.9 && post_residual > 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial decay of the residual penalty as the stream advances:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= progress_poly * 6.0;

    // Non-linear coupling: post_residual^2 normalized by capacity.
    // Quadratic waste penalty: large leftovers are disproportionately bad.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let waste = (pr * pr) / (cap * cap);
    score += waste * 10.0;

    // Reward near-perfect fits smoothly: gaussian-like bump centered at post_residual == 0
    let fit_quality = (-waste * 8.0).exp();
    score -= fit_quality * 5.0;

    // Mean-residual coupling: if this bin's residual deviates strongly from the mean,
    // prefer consolidating into bins with less remaining space (tighter bins first).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 4.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (scaled smoothly by progress).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress_poly;
    }

    // Lookahead coupling: reward placements that leave room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (pr - nx) / cap;
            // smooth reward peaking when post_residual just covers next item
            score -= (-slack * slack * 40.0).exp() * 4.0;
        } else {
            // penalize placements that nearly-but-not-quite fit the next item
            let gap = (nx - pr) / cap;
            score += gap * gap * 12.0;
        }
    }

    // New-bin candidate handling: neutral baseline with slight smooth penalty
    // that shrinks as the stream progresses (late in stream, prefer reusing bins).
    if bin_residual == bin_capacity {
        score = cap * 0.5 + progress_poly * 25.0 - fit_quality * 0.0;
        // allow new bin early in stream when few bins are open
        score -= (open_bins_count as f64).recip() * 5.0 * (1.0 - progress_poly);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let pr = post_residual;
    let class = pr / (bin_capacity / 8).max(1); // 8 harmonic classes of dead space
    score += class as f64 * 2.0;                 // larger dead-space class => worse

    // Perfect / near-perfect fits get strong reward (subtract).
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 5 {
        score -= 200.0;
    } else if pr <= 10 {
        score -= 80.0;
    }

    // Modulo arithmetic: residual divisible by small sizes is reusable.
    if pr > 0 {
        let reusable = (2..=40).filter(|&d| pr % d == 0).count();
        score -= reusable as f64 * 4.0;
    }

    // Penalize residuals that no typical item (1..=80) can ever fill usefully.
    if pr > 80 {
        score += (pr - 80) as f64 * 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (next_item_size.saturating_sub(pr)) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when open bins are congested or mean residual is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let congestion = (fitting_bins_count == 0) as i32;
        let pressure = mean_residual / cap;
        score = cap * 0.9
            + progress * 20.0
            - congestion as f64 * 250.0
            - pressure * 60.0
            + (open_bins_count as f64) * 3.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            score += 30.0; // next item won't fit alongside in a fresh bin either
        }
    }

    // Mild preference for filling more-loaded bins (mean residual comparison).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (size 1..10) are effectively dead weight; penalize small gaps hard.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 60.0; // perfect closure is the best outcome
    } else if post_residual <= 20 {
        score += 10.0; // only fits tiny items, mildly wasteful
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual) as f64;
    score -= 25.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(25.0);
    } else {
        // New-bin candidate: penalize it, more so when many bins are open,
        // unless the current item is huge and would leave a bad gap anyway.
        score += 8.0 + pressure * 0.6;
        if post_residual >= 40 {
            score -= 15.0; // a fresh bin with room for follow-up items is fine
        }
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // creates a gap the next item can't use
    }

    // Slight preference for bins whose residual is near the mean (balanced fill).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by how much
    // of the bin we consumed relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 1.5 * fill_ratio * (bin_residual as f64);

    // --- 2-step lookahead core: exact match with next item is gold ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect pairing: this bin becomes exactly full on next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here afterwards: mild bonus, scaled by slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.15 * slack;
        } else {
            // Next item cannot use the leftover: dead space risk.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
        // If next item is big, prefer keeping large-residual bins for it.
        if next_item_size > item_size {
            let over = (bin_residual as f64) - (next_item_size as f64);
            if over > 0.0 && over < (item_size as f64) {
                score += 0.3 * over; // this bin is the better home for the next big item
            }
        }
    }

    // --- Mean-residual coupling: avoid leaving bins far below average residual ---
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev * dev * 0.01 * 10.0; // penalize large deviations (quadratic coupling)
    score -= 0.05 * mean_residual;           // slight preference to drain high-residual bins

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: only open a new bin when nothing decent fits ---
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; make it unattractive unless existing fits are bad.
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin pairs well with next item
        }
        if open_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // --- Stream progression: late in stream, consolidate aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill_ratio;

    // Small post-residuals (<10) are near-perfect closures.
    if post_residual < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: low post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (typical small items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // marginal space
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // mild penalty so tightest bin wins among many candidates
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).sqrt();
        // Baseline penalty so we prefer existing bins unless they're bad.
        score += 35.0 + 3.0 * crowd;
        // If mean residual is high and this item is small relative to mean residual,
        // opening a fresh bin is more attractive.
        if mean_residual > item_size as f64 * 1.5 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins with little left to pack.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If next item is large, a fresh bin is valuable for it.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Prefer filling bins that deviate from the mean residual (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild pressure to close out nearly-full bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual <= 15 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual interacts with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    // smooth coupling: dead-space penalty grows with progress (late stream => consolidate)
    let coupling = prn * prn * (1.0 + 2.0 * t) - prn * (1.0 - t);
    score += 12.0 * coupling;

    // Lookahead: reward residual that can host the next item (smooth polynomial)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr - nx).max(0.0);
        let fit_frac = fits / cap;
        score -= 8.0 * fit_frac * (1.0 + fit_frac);
        // penalize near-miss residuals (wasted space just below next item)
        let near_miss = (nx - pr).max(0.0) / cap;
        score += 10.0 * near_miss * near_miss;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual context: prefer bins deviating below mean (tighten tight bins)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev - 3.0 * dev;

    // Slight preference for existing bins vs new empty bin as stream progresses
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residues are "dead space"
    // classes: 0 (perfect), 1..10 (near-perfect), 11..=40 (medium), >40 (usable)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 50.0; // perfect fit, strongly reward
    } else if post_residual <= 10 {
        // small dead space: reward by closeness to zero
        score -= (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 40 {
        // medium residue: check harmonic divisibility classes
        let m = post_residual % 10;
        if m == 0 {
            score -= 6.0; // multiples of 10 align with typical item sizes
        } else if m <= 5 {
            score -= 2.0;
        } else {
            score += 3.0; // awkward class
        }
        // residue must be >= min item size (1) to be usable; penalize unusable
        if post_residual < 10 && post_residual > 0 {
            score += 8.0;
        }
    } else {
        // large residue: good, reward proportionally
        score -= 4.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 30.0;
        } else if diff <= 10 {
            score -= (10 - diff) as f64 * 1.5;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by how much it overflows
        score += ((next_item_size - post_residual) as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let avg_fragment = mean_residual;
        // open new bin if open bins are tightly packed (little usable room)
        if avg_fragment < 12.0 && open_bins_count > 0 {
            score -= 10.0;
        } else if fitting_bins_count > 0 {
            score += 12.0 + progress * 5.0; // prefer existing bins generally
        }
        // late in stream, prefer closing out existing bins
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Slight preference for fuller bins (smaller residual) via mean comparison
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Modulo-5 harmonic bonus on item size vs residual alignment
    if bin_residual % 5 == item_size % 5 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps more than proportionally (dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - (post_residual as f64) / 20.0);
