    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item would leave the post-residual stranded, penalize slightly.
    if next_item_size > post_residual && next_item_size > bin_residual {
        score += 5.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 8.0 - (fitting_bins_count as f64) * 0.0;
        // If this is the only fitting option, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild stream progression adjustment: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }
    // Next item does not fit in the leftover: penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than the mean wastes the bin's "density".
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when it enables a
    // perfect 2-step chain (item then next item filling it exactly),
    // otherwise penalize so existing bins are preferred.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0;
        } else {
            score += 30.0;
        }
    }

    // Late in the stream, close out bins aggressively (prefer tight fits).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (nonlinear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 120.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Lookahead: penalize bins whose post-residual can't host the next item,
    // but reward bins that keep room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + next_item_size as f64 * 0.5;
        } else {
            score += 20.0;
        }
        // Bonus for leaving exactly a useful gap the next item can fill later.
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score -= 15.0;
        }
    }

    // Prefer filling bins with small residuals (avoid wasting nearly-full bins).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 60.0;

    // Global state coupling: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, modulated by mean residual and pressure.
        score = bin_capacity as f64 * 0.55 + open_pressure * 8.0 + mean_residual * 0.4;
        // Early stream: opening bins is cheap; late stream: expensive.
        score -= (1.0 - progress) * 40.0;
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 50 {
            score -= 25.0;
        }
    } else {
        // Existing bin: slight reward when mean residual is high (spread load).
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // Mild time-horizon shaping: later in stream, prefer tight packing.
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // tight fits (small post_residual) are increasingly rewarded as stream advances.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let tightness = 1.0 - pr_norm; // 1 = perfect fit
    let poly = progress * progress * tightness * tightness
             + 0.5 * progress * tightness * tightness * tightness;
    score -= 12.0 * poly;

    // Penalize large dead space non-linearly (quadratic waste), stronger late in stream.
    let waste = pr_norm * pr_norm;
    score += 10.0 * waste * (0.5 + progress);

    // Lookahead: reward leaving space that fits the next item smoothly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 6.0 * fit_quality * (1.0 - fit_quality) * 4.0 * (0.3 + 0.7 * progress);
    } else if next_item_size > 0 {
        // next item cannot use this residual: mild penalty growing with progress
        score += 3.0 * pr_norm * (0.5 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean (compact bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 4.0 * dev * (1.0 - progress);

    // Mild reward for consolidating into fewer bins when many are open.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm);

    // New-bin candidate: keep it neutral-ish, slightly penalized so it is chosen
    // only when open bins fit poorly; bias shrinks as stream progresses.
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 2.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small divisors
    // capture "chunkable" leftover space vs. awkward dead space.
    let pr = post_residual;
    let mod5 = (pr % 5) as f64;
    let mod10 = (pr % 10) as f64;
    let mod25 = (pr % 25) as f64;

    // Penalize post-residuals that are NOT cleanly divisible (awkward classes)
    score += mod5 * 0.8;
    score += mod10 * 0.6;
    score += mod25 * 0.4;

    // Reward exact harmonic buckets: residual divisible by 10 or 25 is reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Capacity fraction classes of the fill level (item_size / capacity)
    let fill = item_size as f64 / cap;
    if fill > 0.9 {
        score -= 6.0; // near-perfect fill, strongly favor
    } else if fill > 0.7 {
        score -= 3.0;
    } else if fill < 0.3 {
        score += 2.0; // wasteful placement into a big bin
    }

    // Integer-division threshold on post_residual vs next item
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // next item fits exactly or in same harmonic class -> reward
            if pr % n == 0 {
                score -= 5.0;
            } else if pr - n <= 10 {
                score -= 3.0;
            } else {
                score -= 1.0;
            }
        } else {
            // next item won't fit here: penalize leaving marginal slivers
            if pr < 10 {
                score += 4.0;
            } else {
                score += (n - pr) as f64 * 0.05;
            }
        }
    } else {
        // last item: prefer tightest fill
        score += 0.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: keep it neutral-ish but slightly penalized so we
    // only open new bins when existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 5.0;
        // but if existing bins would leave terrible residue, new bin is fine
        if post_residual as f64 > mean_residual {
            score -= 6.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / cap);

    // Many open bins: favor filling existing ones over spreading
    score += open_bins_count as f64 * 0.15;

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., fuller bins) to keep a spread of usable large residuals.
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

