    }

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized
    let min_gap = 10u32;
    if post_residual > 0 && post_residual < min_gap {
        score += 18.0 + (min_gap - post_residual) as f64;
    } else if post_residual >= min_gap && post_residual <= 20 {
        // medium-small gaps are moderately wasteful
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
