    if bin_residual == bin_capacity {
        score += 6.0 + 0.35 * open_bins_count as f64;
        // but if all open bins would leave big dead space, allow the new bin
        if post_residual == bin_capacity - item_size && post_residual < 15 {
            score -= 10.0;
        }
    }

    // Lookahead: penalize leaving a gap that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 + (next_item_size - post_residual) as f64 * 0.15;
    }
    // Reward leaving exactly enough room for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Mild preference for filling fuller bins when mean residual is high (fragmentation risk)
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
