        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // Next item won't fit here: penalize large leftover that becomes dead space.
            score += 8.0 + 0.15 * gap;
        }
        // Coupled penalty: leftover far from both current and next item sizes.
        score += 0.05 * (gap - (post_residual as f64 - item_size as f64).abs()).max(0.0);
    } else {
        // Last item: just minimize waste.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins tighter than average are worth preserving.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // offers a good fit (post_residual would be large) or early in the stream.
    if bin_residual == bin_capacity {
        let dead_space_penalty = 12.0 + 0.35 * post_residual as f64;
        let early_bonus = (1.0 - progress) * 6.0;
        score = dead_space_penalty - early_bonus;
        // If many bins fit the item already, discourage opening yet another bin.
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
    }

    // Mild pressure to consolidate as the stream matures.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Penalize creating dead space below the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            let slack_after_next = post_residual - next_item_size;
            score -= 4.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
        // If next item would fit perfectly after this placement, big bonus
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, prioritize consolidation into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;
    score -= progress * 4.0;

    // Global state: many open bins -> favor filling existing ones
    score += (open_bins_count as f64) * 0.4;

    // Mean residual coupling: penalize bins far above mean residual (wasteful use)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 12.0 };
        score += desperation + (open_bins_count as f64).sqrt() * 2.0;
        // Late stream: prefer closing out open bins rather than opening new
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, mildly discounted as stream progresses
    let mut score = pr * (0.9 + 0.2 * progress);

    // Non-linear polynomial coupling: penalize large residuals quadratically,
    // but only mid-stream where residual flexibility still matters.
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 30.0 * poly * t * (1.0 - t) * 4.0;

    // Penalize small post-residuals that waste space (dead space), stronger early
    if pr < 10.0 {
        score += (10.0 - pr) as f64 * (1.5 - progress);
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64).abs();
        score -= 15.0 / (1.0 + d * d);
        // Penalize leaving residual just barely too small for next item
        if next_item_size as f64 > pr && next_item_size as f64 - pr < 20.0 {
            score += (next_item_size as f64 - pr) * 0.6;
        }
    }

    // Mild penalty for spreading across many open bins early; encourage consolidation
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins below mean residual slightly (balance residuals)
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: neutral-ish score so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into "wasted" harmonic bands:
    // residuals in (0, 10] are near-unusable dead space -> strong penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 10.0;
    } else if post_residual <= 30 {
        score += 4.0;
    }

    // Reward perfect and near-perfect fits (harmonic closure of capacity).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Integer-division thresholds on post_residual: residuals divisible into
    // common item-size classes (10, 20, 25, 50) are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0;
        } else {
            score -= (next_item_size as f64) * 0.3;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to leftover quality.
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.2;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Opening a new bin is more attractive early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // Attractive if existing bins are fragmented (high mean residual spread).
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 6.0;
        }
    }

    // Prefer bins with residual close to item size (tight packing) via harmonic distance.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 12.0;

    // Modulo class of item size: items in "awkward" classes (not divisors of 100)
    // pack better into bins whose residual shares their modulo class.
    if item_size % 10 != 0 && bin_residual % 10 == item_size % 10 {
        score -= 3.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
