pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in stream, keep bins flexible; late, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step chain: consume residual exactly across two items.
            score -= 60.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= post_residual {
            // Next item fits: mildly reward, scaled by how snug the fit is.
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * snug;
            // Bonus if next item fills bin completely after its placement.
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space creation,
            // worse if post_residual is small (unusable sliver).
            let sliver = post_residual as f64 / bin_capacity as f64;
            if sliver < 0.10 {
                score += 20.0;
            } else {
                score += 8.0 * (1.0 - snug_fit(next_item_size, post_residual));
            }
        }
    } else {
        // Last item: pure tight packing.
        score -= 15.0;
    }

    // Reward placements that keep this bin's residual near the mean
    // (balanced bin portfolio), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post residual would be terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage closing bins out (tight fits) to consolidate.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: neutral baseline with mild attractiveness when
    // current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 0.5 * bin_capacity as f64;
        // Attractive early when few bins open; unattractive if item is small.
        score = score.max(base) - 10.0 * progress + (item_size as f64) * 0.2;
        if item_size <= 20 {
            score += 25.0; // don't waste a fresh bin on tiny items
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

#[inline]
fn snug_fit(next: u32, residual: u32) -> f64 {
    if residual == 0 { return 1.0; }
    let gap = (residual - next) as f64;
    1.0 / (1.0 + gap / 10.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
