pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: residual pressure grows as stream progresses.
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += 0.3 * progress_coupling;

    // Tight-fit reward: small post residual favored more strongly later in stream.
    let tightness = 1.0 - (pr / cap);
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward bins whose post residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap) * (0.3 + 0.7 * progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item.
        score += 8.0 * (1.0 + progress);
    }

    // Mean-residual divergence: prefer bins below mean residual (denser bins).
    score += 0.2 * (mean_residual - pr);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more strongly when open bins exist
    // and stream is late (waste of capacity).
    if bin_residual == bin_capacity {
        let base = 12.0 + 18.0 * progress;
        score += base + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste buckets by decade
    let decade = post_residual / 10;
    score += match decade {
        0 => -30.0,               // near-perfect fit
        1 => -15.0,               // small usable gap
        2 => 0.0,
        3 => 8.0,
        4 => 15.0,
        _ => 25.0,                // large dead space
    };

    // Modulo coupling: residuals divisible by small harmonics pair well with
    // common item sizes; reward residuals whose class matches next item
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0; // next item fills this bin exactly
        } else if gap >= 0 && gap <= 5 {
            score -= 20.0;
        } else if gap < 0 {
            score += 12.0; // next item can't use this bin's residue
        }
        // harmonic match: post_residual mod 10 == next_item_size mod 10
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 20.0;
    }

    // Last-chance bin: penalize abandoning it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 18.0 + 0.15 * open_bins_count as f64;
        // open a new bin early in the stream if current residuals are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 25.0 && progress < 0.9 {
            score -= 20.0;
        }
    }

    // Prefer filling bins far below mean residual (balancing via harmonic mean)
    score -= (mean_residual - post_residual as f64).abs() * -0.05;

    // Integer-division threshold: post_residual >= half capacity is wasteful
    if post_residual >= bin_capacity / 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the smallest
    // plausible item (1..100, min item = 1 here, but small gaps < ~10 are
    // practically unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead space is worse if the next item cannot use it: penalize when the
    // lookahead item is bigger than the leftover gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size - post_residual as u32) as f64 * 0.5;
    }
    // Reward gaps that can host the next item (keeps lookahead feasible).
    if next_item_size > 0 && post_residual >= next_item_size as f64 && post_residual > 0 {
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins rather than opening new ones. New-bin candidate has
    // bin_residual == bin_capacity, penalize it when decent fits exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
    } else {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer bins with below-mean residual (tighter bins) to consolidate.
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also land here: strong reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.3 * slack;
        } else {
            // Dead space relative to lookahead: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.05;
        }
    }

    // Penalize tiny unusable leftovers (dead space) harder than large ones
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

