    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins -> prefer packing into existing bins.
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Mean residual coupling: bins far from the mean residual get nudged toward it.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, keep bins flexible (penalize very low residuals);
    // late in the stream, greedily fill.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if t < 0.3 {
