    } else {
        score -= 6.0 * t;
    }

    // New-bin candidate: neutral baseline, chosen only when no open bin is decent.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * item_size as f64 - 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
