    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (small post_residual); late in stream,
    // allow larger residuals to be absorbed by partially-filled bins.
    let tightness = x * x * (1.0 - progress) + x * progress * (1.0 - x);
    score += 40.0 * tightness * (1.0 - progress);

    // Reward near-perfect fills, stronger as stream progresses.
    let perfect = 1.0 - x;
    score -= 25.0 * perfect * perfect * perfect * (0.5 + progress);

    // Penalize residuals that are too small to be useful later (dead space),
    // scaled by how much room the next item would need.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let unusable = if x < nx { (nx - x) * (nx - x) } else { 0.0 };
        score += 30.0 * unusable * (0.5 + progress);
        // Reward bins whose residual closely matches the next item.
        let match_next = 1.0 - ((x - nx).abs());
        if match_next > 0.0 {
            score -= 15.0 * match_next * match_next;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * progress;

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = (open_bins_count as f64) / (1.0 + mean_residual / cap * 10.0);
        score += 10.0 + 5.0 * crowding - 20.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "usable"
    // for typical item sizes; prime/odd fragments are dead space.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 6.0; // perfectly aligned residual, very reusable
    } else if cls <= 2 {
        score += 4.0; // sliver, nearly dead
    } else if cls >= 8 {
        score -= 2.0; // close to an aligned class
    }

    // Integer-division thresholds: large post_residual blocks are valuable.
    let block = post_residual / 10;
    if block >= 5 {
        score -= 3.0;
    } else if block == 0 {
        score += 8.0; // tiny leftover, bin effectively closed
    }

    // Reward near-perfect fills (waste <= 5).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0;
        } else if slack <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // next item cannot use this residual
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual <= 15 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: prefer opening a fresh bin only when the item
    // is large and no open bin is well-suited.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: waste = capacity - item
        score = (bin_capacity - item_size) as f64;
        if item_size >= 60 {
            score -= 5.0; // large items are fine in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        }
        // Don't open a new bin when many bins fit and mean residual is generous.
        if fitting_bins_count >= 2 && mean_residual >= item_size as f64 + 10.0 {
            score += 15.0;
        }
    }

    // Mild pressure against hoarding too many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 8 && progress > 0.5 {
        score += (open_bins_count as f64 - 8.0) * 0.5;
    }

    // Prefer bins whose residual is below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept any item (min item size 1, but tiny gaps below the common
    // item scale are effectively unusable) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward leaving residual that can accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Penalize wasting a large residual on a small item (bad ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.5 {
        score += (0.5 - fill_ratio) * 80.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, mild preference to consolidate.
    let pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 + pressure * 0.5;
    } else {
        // New-bin candidate: only attractive when nothing fits well.
        // Penalize unless this is a last-chance situation or item is large.
        if fitting_bins_count > 0 {
            score += 120.0 + pressure * 2.0;
        } else {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean
    // (a nearly-full bin), reward finishing it off.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 20.0 * (1.0 - progress);
    }
    // Next item fits into the leftover: good chaining, reward proportional to tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.25;
    }
    // Next item does NOT fit leftover: dead space risk, penalize small unusable leftovers.
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        score += (30.0 - dead.min(30.0) as f64) * 0.8;
    }

    // Reward bins that are tighter than average (better fills), penalize loose bins.
    let rel = if mean_residual > 0.0 { bin_residual as f64 / mean_residual } else { 1.0 };
    score += (rel - 1.0) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it competitive only when current bins are nearly full
    // or the item would leave a tiny unusable fragment everywhere.
    if bin_residual == bin_capacity {
        let fragment_risk = post_residual < 10 && next_item_size > 0 && post_residual < next_item_size;
        if fragment_risk {
            score -= 20.0; // opening a fresh bin is fine
        } else {
            score += 35.0 + 20.0 * (1.0 - progress); // prefer existing bins early
        }
    }

    // Slight preference for filling nearly-full bins (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fits strongly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate logic: an empty bin has large residual; make it
    // attractive only when the current fit is poor or many bins are open
    // with slack. Penalize opening a new bin when a good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // more attractive early in stream or when few bins are open
        score -= (1.0 - progress) * 8.0;
        // if this bin is the only fitting option, opening is fine
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
        // if many open bins with high mean residual, spreading load is good
        if mean_residual > item_size as f64 && open_bins_count > 2 {
            score -= 10.0;
        }
    } else {
        // Filling existing bins: reward bins whose residual is below mean
        // (consolidating fuller bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream: pack tighter, avoid opening new bins.
    score += progress * 10.0 * (open_bins_count as f64).ln().max(0.0);

    // Mild penalty scaled by item size for large items into nearly-full bins
    // (risk of fragmenting remaining capacity).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: residual normalized and squared/cubic terms
    let x = pr / cap; // normalized post residual in [0,1]
    let g = progress * (1.0 - progress); // peaks mid-stream
    score += 12.0 * x * x * (1.0 + g) - 8.0 * x * x * x * progress;

    // Reward tight fits more strongly as stream progresses (polynomial in progress)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize waste relative to mean residual of open bins (quadratic coupling)
    score += 0.05 * (pr - mean_residual).abs() * (1.0 + progress * progress);

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward residual that can host next item, penalize near-misses
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 6.0 * (1.0 - (nx / cap)) * (0.5 + progress);
        } else {
            score += 4.0 * (1.0 - pr / nx.max(1.0)) * (1.0 - progress * 0.5);
        }
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress) + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Harmonic class of post_residual (integer-division thresholds on tens)
    if pr == 0 {
        // Perfect closure: strongly reward
        score -= 40.0;
    } else if pr < 10 {
        // Dead-space class: unusable sliver, heavy penalty
        score += 45.0;
    } else {
        // Larger classes are progressively less wasteful
        let class = pr / 10;
        score -= class as f64 * 3.0;
    }

    // Lookahead (k=2) harmonic coupling: does the next item fit the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0;
            let leftover2 = pr - next_item_size;
            if leftover2 == 0 {
                score -= 12.0; // two-step perfect chain
            } else if leftover2 < 10 {
                score += 22.0; // chain creates dead space
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (pristine full residual)
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
        // Opening a new bin is attractive if the next item is large and won't fit anywhere after this placement
        if next_item_size > 0 && next_item_size > pr {
            score -= 18.0;
        }
    }

    // Stream progression: later in stream, be slightly more conservative about waste
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 4.0;

    // Prefer bins that are fuller than average (relative fullness coupling)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Mild penalty for crowding many open bins
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space trap: residuals too small for the smallest item (1) are pure waste,
    // but residuals in the "awkward zone" (small but nonzero) are the real killers
    // when item sizes are unknown. Penalize any post_residual below a usable threshold.
    let dead_threshold = 4.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    }

    // Exact-fill of next item lookahead: strongly favor bins whose leftover
    // could host the upcoming item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // leftover smaller than next item: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Open-bins pressure: discourage spreading across many bins; encourage
    // closing bins out. Stronger pressure as bin count grows.
    let pressure = open_bins_count as f64;
    score += (pressure / (pressure + 6.0)) * 12.0;

    // Last-chance bin: if this is the ONLY bin that fits, using it avoids
    // opening a new bin — reward it, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin mildly unattractive by
    // default, but attractive when the item is large relative to mean space.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / bin_capacity as f64;
        score += 20.0 - 30.0 * tight;
        // If many bins fit already, opening new bins is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
    }

    // Prefer bins whose residual is below average (closable bins) —
    // placing into nearly-full bins consolidates waste.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Mild preference for placing larger items into tighter bins.
    score += (item_size as f64) * 0.02 * ((bin_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: perfect pairing with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 70.0;
        } else if post_residual > next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item leaves large dead space everywhere). Penalize mildly by default.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 40.0 + 0.3 * waste;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 30.0; // fresh bin can also host next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference for filling older (likely emptier) bins late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full packing (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact / near-exact fits get a strong bonus.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, this bin
    // remains useful; reward that. If post residual is a "dead" gap that the next
    // item cannot use, penalize mildly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_fit / bin_capacity as f64);
        } else {
            score += 15.0;
        }
    } else {
        // Last item: prefer to close bins as tightly as possible.
        score -= 30.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer the best-fitting one, penalize slack choices.
        score += 8.0 * (fitting_bins_count as f64).ln();
    }

    // Global residual state: if mean residual is low (bins nearly full overall),
    // be more forgiving of imperfect fits; if mean residual is high, demand tight fits.
    let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
    score += (mean_residual - post_residual as f64) * (0.3 + 0.5 * progress);

    // Time horizon: early on, allow opening new bins to spread items; later,
    // strongly prefer filling existing bins.
    score += 25.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for too many open bins relative to stream length (bin sprawl).
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize opening a fresh bin unless current fits are poor
    // or the item is large and nothing tight exists.
    if bin_residual == bin_capacity {
        let escape_valve = (fitting_bins_count == 0) as i32 as f64
            + (item_size > 50 && post_residual as f64 > 0.0 && mean_residual > 45.0) as i32 as f64;
        score += 70.0 - 90.0 * escape_valve;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let item = item_size as f64 / cap;

    let mut score = prn * (1.0 + 0.8 * progress * progress);

    // smooth non-linear coupling: penalize residuals that are hard to fill later
    let fill_term = (prn - item) * (prn - item);
    score += 0.35 * fill_term * (1.0 + 0.5 * progress);

    // reward tight fits, especially when this is the only fitting bin
    let tightness = 1.0 - prn;
    score -= 0.6 * tightness * tightness * (1.0 + (fitting_bins_count == 1) as i32 as f64 * 0.8);

    // lookahead: favor bins whose leftover matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (prn - nxt).abs();
        score += 0.45 * gap * gap;
        if prn >= nxt {
            score -= 0.3 * (1.0 - gap);
        }
    }

    // slight preference to keep mean residual balanced
    score += 0.1 * (prn - mean_residual / cap).abs();

    // new-bin candidate handling: penalize opening a new bin mildly, more early
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: modulo-10 classes
    // capture typical item granularity (sizes 1..100 often arrive on
    // 5/10 grids). Residuals that are exact multiples of 10 are the
    // most reusable, so reward them progressively.
    let cls = (post_residual % 10) as f64;
    if post_residual > 0 {
        score -= 8.0 * (10.0 - cls) / 10.0; // perfect class 0 gets -8
    } else {
        // Perfect closure: bin completely filled — strongly reward.
        score -= 60.0;
    }

    // Integer-division thresholds on post_residual: a residual that
    // can still hold a "small" item (<20) is valuable; one that is a
    // sliver (<10) is nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead sliver penalty
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 10.0; // can absorb small item
    } else if post_residual >= 20 && post_residual < 35 {
        score -= 4.0; // moderate usability
    }

    // Lookahead coupling: harmonic class match between post_residual
    // and next_item_size. If next item fits exactly into the residual,
    // reward heavily; if next item cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 12.0; // next item still fits here
        } else {
            // next item won't fit: residual must be reusable later,
            // reward only if it's a "clean" harmonic class
            if post_residual % 10 == 0 && post_residual > 0 {
                score -= 6.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly
    // discourage opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make
    // it attractive only when the fit is poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin baseline: slightly above a perfect-fit open bin.
        score = (bin_capacity - item_size) as f64 + 15.0
            - 20.0 * (1.0 - progress) // early on, opening bins is cheap
            - 6.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // fresh bin has room for lookahead too
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.4 * open_bins_count as f64;

    // Tie-break: prefer bins whose residual deviates least from mean
    // (keeps residual distribution harmonic and predictable).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit the
    // smallest possible item (1) are worthless; residuals below the
    // lookahead item are likely dead space too.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, heavily reward
    } else if post_residual < next_item_size && next_item_size > 0 {
        // post-residual cannot host the next item -> probable dead space
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Small-gap penalty: residuals in [1, 15] are hard to fill later
    if post_residual > 0 && post_residual <= 15 {
        score += 6.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward tight fits (low waste ratio)
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 4.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open
        score += 10.0 + pressure;
    } else {
        score -= 1.0 + 0.2 * pressure.min(10.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // Prefer bins with residual below mean (consolidate waste)
    if bin_residual != bin_capacity {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    // Lookahead synergy: if next item exactly fits post_residual, reward strongly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && next_item_size <= bin_capacity {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect chain fit: item fills bin, next item exactly fills remainder
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Post-residual too small for next item: dead space penalty
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else if next_item_size == 0 {
        // Last item: strongly prefer tightest fit
        score -= 25.0;
    }

    // Prefer bins tighter than average residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 && post_residual >= 10 {
            score += 15.0;
        }
        // Late in stream, opening new bins is costlier
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight reward for very tight fits (small leftover)
    if post_residual < 10 {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
