pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but weight grows smoothly with stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let coupling = norm_pr * norm_pr * (0.5 + 3.0 * progress) - norm_pr * norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += coupling * cap * 0.1;

    // Penalize dead space relative to mean residual across open bins
    score += (pr - mean_residual).abs() * 0.05;

    // Reward last-chance bins (only fitting bin) smoothly
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * progress;
    }

    // Lookahead: reward leaving space for the next item, smoothly scaled
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 1.5 * (1.0 - (pr - n) / cap);
        } else {
            score += 1.0 * (n - pr) / cap;
        }
    }

    // Mild penalty for many open bins early on (encourage consolidation)
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    // New-bin candidate: keep it competitive only when fits are poor
    if bin_residual == bin_capacity {
        score += 0.5 + 3.0 * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small divisors) are preferred.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize large dead space nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic residue classes: post_residual divisible by 2, 4, 5, 10, 20
    // is more likely reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 25.0; }
        else if post_residual % 5 == 0 { score -= 12.0; }
        else if post_residual % 2 == 0 { score -= 6.0; }
        else { score += 10.0; } // odd residues are awkward
    }

    // Small dead-space thresholds (integer division classes).
    let dead_class = post_residual / 10; // 0..10 classes
    score += match dead_class {
        0 => -15.0,           // 0..9: nearly full
        1 => -5.0,            // 10..19
        2 | 3 => 0.0,         // 20..39: mid-range usable
        4 | 5 => 4.0,         // 40..59
        _ => 10.0,            // 60+: wasteful
    };

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly reward; if next item can't fit at all, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: this is the only bin that fits — keep it attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // all existing bins; penalize proportionally to open bins and mean residual,
    // relaxed early in the stream.
    if bin_residual == bin_capacity {
        score = 100.0
            + open_bins_count as f64 * mean_residual * 0.05
            + (1.0 - progress) * 10.0;
        if post_residual == bin_capacity {
            // brand new empty bin at stream start is fine
            if open_bins_count == 0 { score = 50.0; }
        }
    }

    // Slight preference for tighter bins overall (low mean residual regime).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        // Unusable sliver: heavy penalty proportional to how dead it is.
        score += (dead_threshold - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual >= dead_threshold {
        // Usable leftover: mild reward scaled by how reusable it is.
        score -= (post_residual as f64).ln() * 4.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: discourage spreading across many bins; favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).sqrt() * (2.0 + 6.0 * progress);

    // Mean residual coupling: when open bins are already slack, prefer bins that
    // absorb space rather than adding another slack bin.
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is catastrophically bad).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // But if the resulting dead space is unusable, soften the last-chance bonus.
        if post_residual > 0 && post_residual < dead_threshold {
            score += 18.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here: penalize leaving a gap the next item can't use.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when no open bin
    // offers a decent fit; make it slightly worse than a good existing fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheap; later, resist proliferation.
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        // Perfect 2-step match: residual after placing equals next item exactly
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if next_item_size <= post_residual {
            // Next item still fits: reward tightness of the gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leftover that's too small to be useful
            let dead = post_residual as f64;
            score += 10.0 * (dead / 10.0) * (0.5 + progress);
        }
    } else {
        // Last item: just prefer tightest fill
        score -= 15.0;
    }

    // Reward bins already tighter than average (concentrate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin for one item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: only attractive when the item leaves a large, reusable chunk
    if bin_residual == bin_capacity {
        let reusable = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && reusable >= next_item_size as f64 {
            score -= 8.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> prefer filling open bins; late -> allow new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits (low post_residual) more strongly as stream progresses.
    score -= 8.0 * fill * (0.4 + 0.6 * t);

    // Penalize dead space that nothing reasonable can use: residual < 10 is fine (near full),
    // but residual in [1, 9] traps small items; residual in [10..item_size) can't matter.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - t); // early dead space is worse
    }

    // Lookahead coupling: if next item fits the post-residual exactly or well, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * next_fit;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty if we leave a big gap.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidating
    // into bins with residual below mean (fill the emptier-tight ones less).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev; // favor bins tighter than average
        // If lots of bins are open, discourage spreading; prefer best fit strongly.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill);
    }

    // New-bin candidate handling: empty bin gets a base cost that shrinks over time
    // and when no existing bin fits well.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 18.0 - 10.0 * t;
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0; // no alternative: must open
        } else {
            // Only open new bin if all fits are terrible (large post_residual elsewhere).
            new_bin_cost += 5.0 * (mean_residual / bin_capacity as f64);
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, non-linearly warped by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm);

    // Quadratic penalty on large dead space, amplified later in the stream.
    score += 30.0 * pr_norm * pr_norm * (0.4 + 0.6 * progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Coupling with mean residual: prefer bins whose residual differs from mean
    // (move toward balanced residual distribution), smooth interaction.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits the post residual well.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_ratio = ns / pr.max(1.0);
            score -= 20.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
        } else {
            // Penalize leaving residual that cannot fit next item, scaled by progress.
            score += 12.0 * progress * ((ns - pr) / cap);
        }
    }

    // Slight penalty for proliferating bins early on.
    score += 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // New-bin candidate: make empty bin moderately attractive only when it
    // genuinely beats poor fits (its post_residual = cap - item_size).
    if bin_residual == bin_capacity {
        score += 15.0 * progress + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward small post_residual strongly (tight fits).
    score -= (cap - post) / cap * 30.0;

    // Dead-space penalty: post residuals in "unusable" classes (1..10) are poison
    // unless exactly zero (perfect fit).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score += 40.0;
    }

    // Harmonic classes: residuals divisible by common item granularities (5,10,20)
    // are more reusable by future items.
    let r = post_residual;
    if r % 10 == 0 { score -= 12.0; }
    else if r % 5 == 0 { score -= 6.0; }
    if r % 20 == 0 { score -= 5.0; }

    // Integer-division threshold: large residual chunks (>= half capacity) keep bins flexible.
    if r >= bin_capacity / 2 { score -= 8.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if next_item_size <= r {
            // Next item fits; reward proportional to how well it fills.
            let fill = next_item_size as f64 / r as f64;
            score -= 25.0 * fill;
            if r % next_item_size == 0 && next_item_size >= 5 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize small leftover residuals more.
            score += 10.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But if existing residuals are all small relative to item, opening is good.
        if mean_residual < item_size as f64 * 0.6 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post) * 0.1;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += open_bins_count as f64 * 0.5;
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
