pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fit (perfect packing).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect 2-chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Post-residual can host the next item: mild reward proportional
            // to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack * 0.15);
        } else {
            // Next item cannot fit in the leftover: penalize dead space
            // relative to how much the leftover exceeds the next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // "cramped"; prefer spreading load toward bins with more room, but only
    // when the fit is not exact (exact fits already heavily rewarded).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // but relax the penalty late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 300.0 - 120.0 * progress - 2.0 * open_bins_count as f64;
        // If the next item is huge and would leave this bin wasted anyway,
        // opening a new bin is less costly.
        if next_item_size > 70 {
            score -= 100.0;
        }
    }

    // Small bonus for keeping residuals "chunky" (usable by future items
    // of typical size): leftover >= 20 is more useful than 1..19.
    if post_residual >= 20 && post_residual < 100 {
        score -= 15.0;
    } else if post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space (post_residual).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead synergy: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * (next_item_size as f64);
        } else {
            // Next item won't fit here: penalize leaving medium-sized dead space.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 30.0 + 0.5 * fragmentation;
        if item_size >= 60 {
            score -= 20.0; // large items pair well with fresh bins
        }
        if open_bins_count == 0 {
            score = -100.0; // must open a bin
        }
    }

    // Time horizon: late in the stream, consolidate aggressively (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress > 0.7 {
        score += 20.0 * progress;
    }

    // Mild preference for filling bins below mean residual (balance avoidance of many half-full bins).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on leftover space (smaller residual = better fit)
    let mut score = post * (1.0 + norm_post);

    // Cubic coupling with stream progress: early on, tolerate leftovers slightly
    // (future items may fill them); late in the stream, punish dead space harder.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: leftover vs mean residual of open bins.
    // If this bin's post-residual deviates strongly below mean residual,
    // it means we are consuming fragmented space — reward it.
    let mean_norm = mean_residual / cap;
    let deviation = mean_norm - norm_post;
    score -= 8.0 * deviation * (1.0 + progress);

    // Lookahead: if next item fits in the post-residual, reward this placement
    // (smooth bell around exact fit, decaying with slack).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item won't fit here; mild penalty scaled by gap
            let gap = (nx - post) / cap;
            score += 3.0 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin smoothly, more when many bins are open and
    // when good fitting alternatives exist.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln_1p();
        score += 30.0 + 5.0 * open_pressure + 15.0 * progress;
        // But if no open bin fits (fitting_bins_count == 0 for real bins),
        // the new bin gets no extra competition penalty — soften it.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild reward for using nearly-full bins (tight packing incentive)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Tiny tie-breaker noise-free deterministic term on bin index proxy
    score += 0.001 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic penalty on waste.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Harmonic class of post_residual: residues that are "usable" (multiples of
    // common small item sizes) are rewarded; odd dead-space residues penalized.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fit
    } else if pr % 10 == 0 {
        class_bonus -= 25.0; // aligned to decile grid
    } else if pr % 5 == 0 {
        class_bonus -= 12.0;
    } else if pr % 2 == 0 {
        class_bonus -= 4.0;
    } else {
        class_bonus += 8.0; // odd residue: likely dead space
    }
    // Small residues (< 10) are nearly dead space regardless of alignment.
    if pr > 0 && pr < 10 {
        class_bonus += 22.0;
    }
    score += class_bonus;

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if (pr as f64) >= next_item_size as f64 {
            // Exact harmonic match is gold.
            if pr % next_item_size.max(1) == 0 {
                score -= 30.0;
            } else {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize more if this bin was the only option.
            score += 10.0;
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early; relax later or when residuals are fragmented.
        score = bin_capacity as f64 * (0.9 + 0.5 * progress) - crowd.min(50.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin gives room for big next item
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference for using more open bins early vs. fewer later.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min size 1..100 unknown; treat < 12 as near-dead)
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness relative to current residual: reward filling most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: prefer consolidating into existing bins
    score += 2.5 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        }
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Mean residual coupling: bins with residual far below mean are more
    // valuable to fill; bins far above mean should absorb this item
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early stream: be greedy with tight fits; late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * fill_ratio;

    // New-bin candidate: keep it neutral-ish but slightly penalized so it
    // only wins when all open bins would create dead space
    if bin_residual == bin_capacity {
        score += 8.0 + 1.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
            if diff == 0.0 {
                score -= 25.0; // perfect 2-step match
            }
        } else {
            // next item cannot use the leftover space at all
            score += 15.0 + diff * 0.2;
        }
    }

    // Penalize small unusable dead space (post_residual < minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 12.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Mild new-bin penalty so we only open a bin when the fit is truly bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But allow new bin if the item is huge and no good fit exists.
        if item_size >= 70 && fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill_ratio;

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, strongly reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item cannot use the leftover; penalize proportionally
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / 50.0;
    }

    // New-bin candidate logic: empty bin should win only when fits are poor
    if bin_residual == bin_capacity {
        // mild base cost for opening a new bin
        score += 5.0;
        // more open bins -> discourage opening another
        score += 0.5 * open_bins_count as f64;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
        // if mean residual across open bins is large, opening new bin is wasteful
        score += 0.15 * mean_residual;
    } else {
        // prefer bins with residual close to capacity when mean residual is low? no:
        // prefer bins below mean residual (consolidate fuller bins)
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Slight preference for placing into bins when many bins can fit (consolidation)
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * (pr / cap) * (pr / cap));

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals become increasingly valuable
    let prog_coupling = progress * progress * (3.0 - 2.0 * progress);
    score += 6.0 * prog_coupling * (pr / cap) * cap * 0.1;

    // Reward filling bins close to capacity (low post residual) more strongly as stream advances
    score -= 10.0 * prog_coupling * (it / cap);

    // Penalize opening new bins when good fits exist; smooth pressure via fitting_bins_count
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 12.0 * (1.0 - prog_coupling) * scarcity;
        score += 4.0 * prog_coupling * (pr / cap);
    } else {
        // Last-chance bonus: smooth reward when this is nearly the only fitting bin
        let last_chance = 1.0 / (fitting_bins_count as f64);
        score -= 8.0 * last_chance * (1.0 - pr / cap);
    }

    // Lookahead: if next item fits snugly into the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_quality = 1.0 - ((pr - nxt).abs() / cap);
        let usable = if nxt <= pr { 1.0 } else { 0.3 * (1.0 - (nxt - pr) / cap) };
        score -= 5.0 * fit_quality * usable;
        // Penalize leaving residual too large for typical next items
        score += 2.0 * prog_coupling * ((pr - nxt).abs() / cap);
    }

    // Mild preference for bins below mean residual (balance load) via smooth term
    score += 1.5 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual modulo capacity fractions.
    // Residuals in the "harmonic sweet spots" (multiples of small divisors of 100)
    // are more likely to be filled by future items.
    let sweet = |r: u32| -> f64 {
        let m10 = (r % 10) as f64;
        let m25 = (r % 25) as f64;
        let m50 = (r % 50) as f64;
        // distance to nearest harmonic class boundary
        let d10 = m10.min(10.0 - m10);
        let d25 = m25.min(25.0 - m25);
        let d50 = m50.min(50.0 - m50);
        (d10 + d25 * 0.5 + d50 * 0.25) / 1.75
    };
    score += sweet(post_residual) * 1.5;

    // Penalize small unusable dead space strongly (post_residual < 10 can never be filled).
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward near-perfect fits (harmonic complement: item + residual = capacity multiples).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 3.0 + sweet(post_residual - next_item_size) * 0.5;
        } else {
            // next item won't fit here; penalize leaving mid-range residual
            score += 2.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: empty bin (residual == capacity). Prefer open bins unless
    // this bin's residual is poorly harmonically aligned or the fit is loose.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = (bin_capacity - item_size) as f64 + 8.0 - 4.0 * progress;
        // If item is large relative to capacity, new bin is more attractive.
        if item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
        // If no open bin fits, opening is inevitable: reduce penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Prefer using bins whose residual is close to item (tight packing).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= tightness * 2.0;
        // Slight preference for bins deviating from the mean residual (diversity of classes).
        score -= ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64) * 1.0;
    }

    // Integer-division threshold: post_residual in [1..=5] is near-dead space.
    if post_residual >= 1 && post_residual <= 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Lookahead: if next item fits the post-residual, this is a great chain.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 && next_item_size > post_residual {
            // post_residual too small for next item: dead space for lookahead
            score += 6.0;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer spreading load; penalize when many bins open.
    score += 0.35 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins first).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: mildly penalize so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    // Early stream: be more conservative with opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to wasted potential
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual near/below mean (tighter bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize creating tiny unusable dead space (1..small) that no item (min size 1..) reliably uses
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Early in stream: slightly discourage opening too many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    // Prefer filling larger-residual bins when many bins are open (consolidation)
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64 / cap).powi(3) * 40.0;

    // Reward filling the bin heavily.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * fill_ratio * 30.0;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.08; // exact-chain fit bonus
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here: mild penalty proportional to wasted chain chance.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // late in stream, prefer tight fits regardless.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - t) * 6.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));

    // Global residual balance: prefer bins close to mean residual (keeps flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / 100.0).powi(2) * 20.0;
        score += 15.0 - big_item_bonus + (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;

    // Tight-fit reward: quadratic penalty on wasted space, amplified late in stream
    let waste = post_residual as f64 / cap;
    score += 30.0 * waste * waste * (0.5 + progress);

    // Reward near-perfect fits strongly (smooth non-linear coupling)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio * fit_ratio;

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.4 + 0.6 * progress);
    }

    // Prefer bins with residual below mean (consolidate small leftovers)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * waste;
    }

    // New-bin candidate: prefer early in stream or when current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score -= 10.0 * (1.0 - progress) - 15.0 * fragmentation * progress;
        // Penalize new bin when a decent fit exists among open bins
        if post_residual == 0 {
            score += 1e9;
        }
    }

    // Exact fill is always best
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: overwhelming reward
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of dead space via integer division thresholds (capacity/10 bands)
        let class = pr / 10;
        score += match class {
            0 => 60.0, // 1..9 : nearly dead space, strongly penalize
            1 => 25.0, // 10..19
            2 => 10.0, // 20..29
            3 => 4.0,  // 30..39
            _ => 0.0,  // large residual is fine
        };

        // Lookahead coupling: reward bins whose residual can host the next item
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 15.0 + (pr - next_item_size) as f64 * 0.1;
            } else {
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }

        // Modulo-5 harmonic penalty: residuals near multiples of 5 pair better
        // with typical item granularities
        let m = pr % 5;
        score += match m {
            0 => -6.0,
            1 => 5.0,
            4 => 3.0,
            _ => 0.0,
        };
    }

    // New-bin candidate: mild penalty so existing usable bins win,
    // but not so strong it never opens when fits are terrible
    if is_new_bin {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (more items to co-fill)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Reward packing large items tightly (utilization term)
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Slight preference for bins below mean residual (balance avoidance of
    // many half-empty bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (1..100) are nearly worthless dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    } else if post_residual > 0 && post_residual < 25 {
        // Small gaps only fit tiny items; penalize proportionally.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening yet another one.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded
        // and mean residual is low; otherwise penalize opening a new bin.
        score += 10.0 + pressure * 2.0;
        // Lookahead: if the next item is small, a fresh bin is fine.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 8.0;
        }
    } else {
        score -= pressure.min(20.0);
    }

    // Lookahead coupling: leaving room for the next item is valuable.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Wasting residual that next item cannot use.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Mild late-stream bias: near the end, close out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: squared residual punishes small unusable leftovers.
    score += (post_residual as f64).powi(2) / 100.0;

    // 2-step lookahead: reward exact match between post_residual and next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Perfect 2-step match: strong reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits in the leftover: mild reward proportional to snugness.
        if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize wasting space relative to mean residual.
            score += 5.0 * (1.0 - next_item_size as f64 / post_residual as f64).max(0.0);
        }
    } else {
        // Last item: just minimize leftover.
        score -= 15.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average when residuals are large.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let bad_fit = if post_residual > 0 { 1.0 } else { 0.0 };
        // Opening a new bin is penalized unless few bins exist or item is huge.
        score += 40.0 - 2.0 * crowd + 10.0 * bad_fit;
        if item_size >= 70 {
            score -= 25.0;
        }
        // Lookahead: opening a fresh bin is good if next item also large.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild stream-progression pressure: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 - post_residual as f64;
    }

    // Penalize large dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead_frac * dead_frac;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if the next item then fills the bin exactly.
            if post_residual - next_item_size <= 10 {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space the next item cannot use: penalize.
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;
        }
    } else {
        // Last item: prioritize exact fills above all.
        if post_residual == 0 { score -= 40.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let mut newbin_score = 55.0 + dead_frac * 0.0;
        // Early in the stream, opening bins is cheap and flexible.
        let progress = step_index as f64 / total_items.max(1) as f64;
        newbin_score -= 20.0 * (1.0 - progress);
        // If many bins are open and mean residual is high, prefer reusing.
        newbin_score += open_bins_count as f64 * 1.5;
        newbin_score += (mean_residual - item_size as f64).max(0.0) * 0.3;
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 1 {
            newbin_score -= 25.0;
        }
        // Large items fit better in fresh bins.
        newbin_score -= item_size as f64 * 0.15;
        score = score.min(newbin_score);
    }

    // Mild preference for fuller bins among open candidates.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear penalty on wasted space, normalized by capacity
    let waste_frac = post / cap;
    score += 12.0 * waste_frac * waste_frac * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 6.0 * (-post / 15.0).exp() * (0.5 + progress);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 8.0 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if next item fits into post_residual, reward leaving usable space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 3.0 * (1.0 - (post - nxt) / cap).abs();
        } else {
            // penalize post_residual that is too small for the next item (dead space)
            score += 2.5 * (1.0 - nxt / cap) * (1.0 + progress);
        }
    }

    // Prefer bins below mean residual slightly (keeps larger bins for larger items)
    score += 0.05 * (post - mean_residual);

    // New-bin candidate: keep it neutral-ish but discourage when decent fits exist
    if bin_residual == bin_capacity {
        score += 4.0 - 2.0 * progress;
        if post_residual == bin_capacity {
            score += 6.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue modulo 10 defines
    // "harmonic bands" of leftover space. Residues near 0 (perfect fills)
    // are heavily rewarded; mid-range residues are penalized.
    let r = post_residual % 10;
    let band_bonus: f64 = match r {
        0 => -60.0,
        1 => -15.0,
        2 => -8.0,
        3 | 4 => 4.0,
        5 => 10.0,
        6 | 7 => 6.0,
        8 => -2.0,
        _ => -5.0,
    };
    score += band_bonus;

    // Integer-division thresholds: post_residual in [0,10) is "dead space"
    // class; in [10,40) is reusable for small items; >=40 is prime space.
    let q = post_residual / 10;
    if q == 0 {
        score -= 25.0; // near-perfect fill
    } else if q >= 4 {
        score += 12.0; // leaving big space is fine only if bin was big
    }

    // Coupling with next item: if the next item fits exactly into the
    // post-residual, strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // reward tight follow-up fits, penalize loose ones
            score -= (20.0 - slack as f64 * 0.3).max(-10.0);
        } else {
            // next item cannot use the residue: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Fraction of capacity: prefer filling bins whose residual fraction
    // after placement is a small harmonic fraction of capacity.
    let frac = post_residual as f64 / cap;
    if (frac - 0.5).abs() < 1e-9 {
        score += 5.0; // half-empty bin: keep it for larger items
    } else if frac < 0.25 {
        score -= 10.0 * (0.25 - frac);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: baseline penalty so it only wins when open bins
    // are genuinely bad (large residuals with poor harmonic classes).
    if bin_residual == bin_capacity {
        score += 55.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Tie-break: prefer bins tighter than the mean residual.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Slight preference for many open bins being consolidated.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }
    // Penalize if post_residual cannot hold next item but is small.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open bins pressure: prefer tighter bins when many bins are open.
    score += (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Prefer bins already below mean residual (consolidate fullness).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Mild penalty for opening a new bin when stream is late and bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: strongly reward bins whose post-residual
    // can host the NEXT item (chained fit), scaled by lookahead size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits perfectly here: big reward, stronger for tight chains.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * next_item_size as f64 - 0.2 * slack_after_next;
            // Perfect two-item fill bonus.
            if slack_after_next == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot follow: penalize proportionally to how much
            // the leftover dead space blocks the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins that are already
    // below-average residual (denser bins), keeping sparse bins flexible.
    let rel = if mean_residual > 0.0 { post_residual as f64 / mean_residual } else { 1.0 };
    score += 5.0 * (rel - 1.0);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no good chaining exists; make the empty bin costly by default.
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * (1.0 - progress);
        // Late in the stream, opening new bins is even less desirable.
        score += 20.0 * progress * progress;
        // But if the item nearly fills a fresh bin, allow it.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Tight fit reward: residual close to zero is good.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Mild penalty for proliferating open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are rewarded: penalize large post-residual non-linearly.
    let frag = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * frag * frag;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasting space next item could use elsewhere.
            score += 6.0;
        }
    }

    // Global state: with many open bins, prefer filling existing ones (avoid fragmentation).
    let density = open_bins_count as f64 / (total_items.max(1) as f64);
    score += density * 20.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a "small hole"
    // that only small items can use — filling it now is good.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff.min(30.0) * 0.5;
    } else {
        score += (-diff).min(30.0) * 0.3;
    }

    // Time horizon: early in stream, be more willing to open fresh bins for large items;
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if it creates a good future structure.
        let base = 60.0 + 40.0 * (1.0 - progress);
        score = base + item_size as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin can host next item too
        }
    } else if progress > 0.7 {
        score -= 5.0; // consolidation pressure late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its smooth non-linear shaping.
    let x = pr / cap; // 0..1
    // Dead-space penalty: quadratic growth in residual, modulated by stream progress.
    // Early on, residuals are tolerable; late in the stream, waste is costlier.
    let mut score = 100.0 * x * x * (1.0 + 0.8 * progress) + 20.0 * x * (1.0 - progress);

    // Tight-fit reward: smooth bell around zero post-residual.
    score -= 45.0 * (-8.0 * x).exp();

    // Lookahead coupling: reward if next item fits the post-residual (smooth falloff with mismatch).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 25.0 * (-6.0 * gap).exp();
        // Penalize leaving a gap too small for the next item (dead space trap).
        if pr < next_item_size as f64 {
            score += 12.0 * (1.0 - pr / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean when mean is small
    // (pack tight bins), above the mean when mean is large (drain fat bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (1.0 - 2.0 * progress).tanh();

    // New-bin candidate (empty bin): base score is cap; apply smooth pressure so that a new
    // bin is only chosen when all open bins are badly fragmented.
    if bin_residual == bin_capacity {
        // Attractive early / when open bins are few or very full on average.
        let mean_fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap as f64 - 40.0 * mean_fullness * (0.5 + 0.5 * progress) - 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define
    // "dead space classes". Small residues that are NOT multiples of 10
    // are hard to fill later; multiples of 10 are reusable.
    let r = post_residual % 10;
    if post_residual > 0 {
        if r == 0 {
            score -= 12.0; // perfectly harmonic residual, highly reusable
        } else if r <= 3 {
            score += 14.0; // tiny dead sliver, nearly unusable
        } else if r <= 6 {
            score += 6.0;  // mildly awkward
        } else {
            score -= 3.0;  // 7..9 can still host small items
        }
    } else {
        score -= 25.0; // perfect closure of the bin
    }

    // Integer-division threshold: post_residual bucketed by capacity tenths
    let tenth = bin_capacity / 10;
    let bucket = post_residual / tenth;
    score -= match bucket {
        0 => 8.0,           // almost full: good compaction
        1 => 2.0,
        2 => 0.0,
        3 => 3.0,
        _ => 5.0,           // leaving a half-empty bin is wasteful
    };

    // Lookahead coupling: does post_residual harmonically fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 10.0; // next item leaves a harmonic residual again
            } else if gap <= 3 {
                score += 9.0;  // next item would create a sliver here
            } else {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item cannot use this bin's remainder
        }
    } else {
        score -= 6.0; // last item: prefer tightest packing
    }

    // Last-chance bin before opening a new one: reward strongly.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: keep it available but not preferred
    // unless all open bins are poor fits.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 30.0 - 10.0 * pressure.min(3.0);
        if post_residual == bin_capacity - item_size && next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 20.0; // pairing with next item justifies a fresh bin
        }
    }

    // Stream progression: late in the stream, avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference for bins tighter than the mean residual.
    score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: penalize placing into bins when many are open,
    // unless this is the only fitting bin (last chance).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += (open_bins_count as f64) * 2.0;
    }

    // Prefer bins whose residual is tighter than average (best-fit coupling).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Lookahead: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item cannot fit in post_residual and post_residual is small.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 15.0;
    }

    // Slight preference for opening new bins early vs late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match gets a large bonus; near matches scale down.
        if gap == 0.0 {
            score -= 60.0;
        } else {
            score += gap * 0.6;
        }
        // If next item cannot fit here at all, penalize mildly (wasted lookahead slot).
        if post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0;
    }

    // Dead-space penalty: residuals that are too small to hold any plausible item are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins with residual below mean residual (tighter packing) unless it's the new bin.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if is_new_bin {
        // Base penalty so it's chosen only when alternatives are bad.
        score += 20.0;
        // If many bins fit, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early in stream, opening bins is cheaper; late in stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // If next item is large and this item is large, a fresh bin keeps flexibility.
        if next_item_size > 50 && item_size > 50 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if post_residual >= next_item_size {
            // Bonus if residual can still host the lookahead item.
            score -= 2.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Time horizon: late in the stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * tightness;

    // Global state: many open bins -> discourage new bins, encourage consolidation.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Base penalty for opening a new bin, reduced when few bins are open
        // or the item fits poorly everywhere.
        score += 8.0 - 2.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open a new bin
        }
        // If mean residual is high, existing bins are roomy; opening new bins is wasteful.
        score += 0.05 * mean_residual;
    } else {
        // Slight reward for using existing bins when many are open.
        score -= 0.3 * (open_bins_count as f64).sqrt();
    }

    // Penalize leaving residuals in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: reward tight fits via non-linear (quadratic + cubic) coupling with progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr) + 40.0 * norm_pr * norm_pr * (1.0 - progress);

    // Penalize large dead space more aggressively as the stream progresses
    score += 25.0 * norm_pr.powi(3) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits in the post-residual space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // penalize leaving residual that can't host the next item
            score += 6.0 * (1.0 - pr / cap.max(1.0)) * progress;
        }
    }

    // Mildly prefer consolidating into fewer bins when many are open
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral-ish baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) + 5.0 * norm_pr;
    }

    // Mean-residual coupling: discourage bins far from the mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) strongly favored,
    // small unusable slivers penalized.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals that no plausible item (1..=100) can
        // use well. Residual < 10 is nearly dead in classic streams; here
        // items can be as small as 1, so weight by how "unharmonic" the
        // residual class is.
        let r = post_residual;
        let class = r % 10; // harmonic sub-class
        score += (10 - class) as f64 * 0.35; // prefer residuals aligned to decadal classes

        // Small residuals are risky: less likely to absorb the next item.
        if r < 20 {
            score += (20 - r) as f64 * 1.5;
        }
    }

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 300.0;
            } else {
                score -= (next_item_size as f64).min(post_residual as f64) * 0.5;
                score += gap as f64 * 0.2;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are tight
        // or fragmented. Compare item fit against mean residual.
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.1;
        // Discourage opening new bins early in the stream or when many bins exist
        // with usable space.
        if mean_residual >= item_size as f64 {
            score += 80.0;
        }
        if open_bins_count > 0 && post_residual >= 40 {
            score += 25.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (< 10) are useless -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the typical minimum item (<= 10) are dead space
    if post_residual > 0 && post_residual < 12 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill_ratio; // prefer bins where the item fills most of the residual
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / cap);
    }
    // Penalize if next item cannot fit here (bin will become dead space unless reused later)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Prefer bins whose residual is below the mean (tighter bins get filled first)
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base new-bin cost; scales with number of open bins
        score = cap * 0.9 + open_bins_count as f64 * 8.0;
        // If item leaves a large usable residual in a fresh bin, slightly soften
        score -= (post_residual as f64) * 0.2;
        // If it's the last chance among fitting bins, opening new bin is less attractive
        if fitting_bins_count >= 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit lookahead bonus: post residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead match (small leftover after next item)
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next <= 5 {
            score -= 25.0 - after_next as f64 * 3.0;
        } else if after_next <= 15 {
            score -= 8.0;
        }
    }
    // Penalize if next item cannot fit here (forces future new bin)
    if next_item_size > 0 && next_item_size > post_residual {
        score += 12.0;
    }

    // Exact fill now
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Dead-space penalty for tiny unusable residuals relative to smallest item (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate handling: only attractive when item is large
    // (few open bins could ever absorb it well) or stream is late.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_bonus = if fill_frac > 0.7 { 35.0 } else { 0.0 } + progress * 20.0;
        // Base new-bin cost: opening a bin is expensive unless justified
        score += 25.0 - new_bin_bonus;
        // If many bins already open, discourage spreading further
        score += open_bins_count as f64 * 1.5;
    }

    // Mild preference to fill fuller bins when many bins are open
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: nothing of size >=10 can use it
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting capacity
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else if fitting_bins_count == 1 {
            score += 8.0; // prefer using the last fitting bin
        }
        // late in stream, opening new bins is more costly
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * t;
    }

    // Prefer bins whose residual deviates from mean (consolidate fragmented space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins as stream progresses (best-fit bias).
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // Penalize many open bins slightly to encourage consolidation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: reward tight fits via smooth polynomial in post_residual
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Non-linear coupling: as stream progresses, prefer filling bins tighter
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead coupling: reward if next item fits the post residual (smooth kernel)
    let gap = (pr - next_item_size as f64).abs() / cap;
    score -= 12.0 * (-gap * gap * 20.0).exp();

    // Penalize leaving dead space that next item cannot use
    score += 8.0 * norm_pr * (1.0 - norm_next);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Mild penalty proportional to number of open bins to consolidate
    score += open_bins_count as f64 * 0.5 * norm_pr;

    // Mean residual interaction: prefer bins deviating from mean (tighter ones)
    score += (pr - mean_residual) * 0.3;

    // New-bin candidate: neutral baseline, opened only if all fits are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it partitions capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual as u64) / 10; // decade class of leftover

    // Penalize unusable dead space: leftovers in (0, 10) are dead
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Chain compatibility: reward if next item fits into post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_ratio = (post_residual - next_item_size) as f64 / cap;
        // Harmonic coupling: reward tighter chains more
        score -= 15.0 * (1.0 - slack_ratio);
        // Extra bonus if next item exactly fills or nearly fills leftover
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't chain here; penalize proportionally to wasted potential
        score += 5.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic threshold on residual classes: mid-range leftovers (30-60)
    // are the most reusable; small leftovers (10-30) less so
    match class {
        0 => score += 8.0,          // 0-9: nearly dead
        1 => score += 4.0,          // 10-19
        2 => score += 1.0,          // 20-29
        3 | 4 | 5 => score -= 3.0,  // 30-59: sweet spot
        6 => score -= 1.0,          // 60-69
        _ => {}                     // 70+: naturally penalized by base score
    }

    // Congestion: many open bins -> prefer consolidation (favor filling existing)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.5 * open_bins_count as f64 * progress;

    // Prefer bins tighter than the mean residual (better fit quality)
    score += 0.1 * (mean_residual - (bin_residual as f64));

    // New-bin candidate bias: make empty bin moderately attractive only when
    // current bin would leave a bad class of leftover
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by potential of a fresh bin
        score = 40.0;
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            // current item will strand the next one anyway
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that are too small for the smallest plausible next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 0.9 * (next_item_size - post_residual) as f64;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Mild tilt toward tighter bins (smaller residual).
    score += (bin_residual as f64) * 0.05;

    // Reward keeping room for the lookahead item when it fits exactly.
    if next_item_size > 0 && post_residual == next_item_size as f64 as u32 {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, slight penalty so it is
    // chosen only when existing bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in stream, opening a new bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect: next item fits with small slack left afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 25.0 - slack as f64;
        } else {
            score -= (10.0 / slack as f64) * 5.0;
        }
    }
    // Penalize residuals that are too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize leaving tiny unusable gaps relative to the smallest possible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when it enables a good 2-step chain
    // (e.g., current item plus next item pack perfectly into a fresh bin).
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover <= 10 {
                score -= 35.0 - leftover as f64;
            }
        }
        // As the stream progresses, be slightly more willing to open new bins
        // when many bins are already open (spreading load).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a brand-new bin unless nothing else works.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.35 * (bin_capacity as f64 - post_residual as f64);
        // Late in the stream, opening new bins is even less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // If many bins already fit the item, new bin is very unattractive.
        score += 15.0 * (fitting_bins_count as f64).min(5.0);
    } else {
        // Reward tight fits: post_residual near zero is best.
        score -= 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

        // Last-chance bin (only fitting bin) gets a big bonus.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }

        // Lookahead: penalize leaving a residual that barely fails to fit the next item
        // (dead space), reward residuals that can host the next item.
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if (post_residual as f64) >= nx {
                score -= 12.0;
            } else if (post_residual as f64) >= nx * 0.75 {
                score += 8.0; // awkward dead space
            } else {
                score += 3.0 * (1.0 - (post_residual as f64) / nx);
            }
        }

        // Slight preference for bins with residual below the mean (consolidate large holes).
        score += 0.15 * ((bin_residual as f64) - mean_residual).max(0.0);

        // Early in the stream, mildly prefer keeping the number of open bins low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 0.5 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping.
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more -> amplify small residuals' penalty.
    let t = progress * std::f64::consts::PI;
    let progress_weight = 1.0 + 0.8 * (1.0 - t.cos()) * progress;
    score += progress_weight * 30.0 * norm_pr * norm_pr;

    // Reward near-perfect fits smoothly: subtract a bump peaked at norm_pr near 0.
    score -= 15.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Penalize residuals that are too small to ever fit future items (dead space),
    // smoothed via interaction with next_item_size lookahead.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr).max(0.0) / cap;
        score += 40.0 * waste * waste;
        // Reward leaving exactly enough room for the next item (smooth valley).
        let gap = (pr - nxt) / cap;
        score -= 12.0 * (-(gap * gap) / 0.01).exp();
    } else {
        // Last item: strongly prefer filling bins as completely as possible.
        score += 20.0 * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, penalize opening a new bin
    // (which is the competing new-bin candidate with residual == capacity).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild pressure toward consolidating among many open bins: prefer bins whose
    // residual deviates from the mean (fill the emptiest-relative bins first),
    // with smooth polynomial coupling to progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev * (1.0 + progress);

    // Discard spreading across too many open bins late in the stream.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress * norm_pr;

    // New-bin candidate handling: make an empty bin mildly unattractive unless
    // no open bin fits well (its high post_residual already scores high via base term).
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / cap;
    let class = (frac * 10.0).floor() as i32; // 0..10 harmonic band

    // Reward tight fits strongly (low post_residual classes)
    match class {
        0 => score -= 40.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 4.0,
        _ => {}
    }

    // Penalize dead space that is too small for typical future items (1..100)
    if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Modulo arithmetic on post_residual: divisible residuals pair well with many sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // prefer leaving space that still accommodates the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot follow here: mild penalty proportional to overflow
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin would be nearly full
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score = cap * 0.55 - 20.0 * tightness;
        if item_size >= 80 {
            score -= 15.0; // big items deserve fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 10.0; // pairing possible elsewhere; avoid wasteful open
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress;

    // Spread-awareness: prefer bins below mean residual (keeps balance)
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Many open bins: discourage spreading, favor filling existing ones
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any future item (min size 1..100 unknown,
    // but small gaps are hard to fill) get a strong nonlinear penalty.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 20 {
            score += 40.0 * (1.0 - dead) * (20.0 - post_residual as f64) / 20.0;
        } else if post_residual < 40 {
            score += 12.0 * (40.0 - post_residual as f64) / 40.0;
        }
    } else {
        // Perfect fill is heavily rewarded.
        score -= 30.0;
    }

    // Tight-fit reward: item occupying most of the bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item still fits after this placement
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins when residual is large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (1.0 - fill_ratio) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this placement would leave a bad gap
    // or no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < 20;
        if bad_fit {
            score -= 15.0; // opening a fresh bin beats wasting space
        } else {
            score += 10.0 + 5.0 * open_bins_count as f64; // keep using open bins on decent fits
        }
    }

    // Slight alignment with mean residual: prefer bins below-average residual (already tight).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect match where the
    // next item exactly fills the residual left by this placement.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.7 * diff;
        if post_residual == next_item_size {
            score -= 40.0; // exact chain: this bin will be perfectly closed next step
        }
        // Penalize residuals too small for the next item (dead space), but
        // reward very small residuals only if they are unusable anyway (<10).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
        // Penalize leaving a residual that nothing typical can use.
        if post_residual > 0 && post_residual < 10 {
            score -= 5.0; // tiny dead space is fine
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.2 * post_residual as f64;
    }

    // Tight-fit bonus: item nearly fills the bin now.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score += 20.0; // wasteful placement, soften the bonus
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when the item is large relative to capacity or when
    // open bins are on average too full to help.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 18.0 * fill_ratio;           // big items deserve fresh bins
        score += 10.0 * (1.0 - fill_ratio);   // small items should use open bins
        score += 8.0 * mean_residual / bin_capacity as f64; // fuller open bins -> new bin ok
        score -= 5.0 * (1.0 - progress);      // early on, consolidate into open bins
    } else {
        // Slightly favor bins below mean residual (balance load across bins).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Mild pressure against accumulating many open bins with poor fits.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize dead space that cannot fit the average item (>=10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Perfect chain bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item could fit this bin anyway; slight penalty for wasting it now.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins;
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins with residual near/below mean (avoid fragmenting large-residual bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // New-bin candidate: give it a moderate baseline so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But early in stream, new bins are cheap.
        score -= (1.0 - progress) * 30.0;
        // If next item is large, opening a fresh bin now is fine.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) + 2.0 * x * x * x * t;
    score += 30.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - x;
    score -= 40.0 * tightness * tightness * (0.5 + t);

    // Penalize wasted residual relative to mean residual of open bins
    score += 0.3 * (pr as f64 - mean_residual).abs() * (1.0 + t);

    // Reward using a bin that matches the lookahead item's complement
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.5 * gap * (1.0 - t);
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + t);
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10
    let pr = post_residual as i64;
    let cls = pr % 10;
    // Penalize "awkward" residuals that few item sizes can use
    let awkward = match cls {
        1 | 2 | 3 | 7 | 8 | 9 => 6.0,
        4 | 6 => 2.0,
        _ => 0.0,
    };
    score += awkward;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness: reward small-but-usable residuals (>=10) more than large waste
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space under min item size
    }

    // Lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni <= pr {
            let gap = pr - ni;
            if gap == 0 {
                score -= 30.0;
            } else if gap < 10 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot use this bin's remainder
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fractional capacity coupling: penalize leaving residual in the 50-70 band
    let frac = post_residual as f64 / cap;
    if (0.5..0.7).contains(&frac) {
        score += 4.0;
    }

    // Mild penalty for spreading across many bins
    score += 0.3 * open_bins_count as f64;

    // Slight preference to fill bins as stream progresses
    score -= 0.02 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the lookahead item
    // (or the smallest plausible item) are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        score += 60.0 + (min_useful - post_residual) as f64 * 4.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 20.0 * (item_size as f64 / (post_residual + item_size) as f64);
    }

    // Lookahead synergy: if the next item fits exactly into the post-residual gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 15.0; // next item won't fit here: mild penalty
        }
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; a fresh empty bin candidate gets a surcharge.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: only attractive when current bin residuals are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3 - 0.2 * (open_bins_count as f64);
        if mean_residual < 20.0 {
            score -= 40.0; // existing bins are nearly full; opening is fine
        }
    }

    // Slight preference for bins below the mean residual (fill emptier bins).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild convex penalty
    // so that near-zero post_residual is strongly favored.
    score += (post_residual as f64).powi(2) * 0.01;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size exactly or closely.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Perfect chain: post_residual == next_item_size -> big reward
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item fits exactly after this placement AND leaves 0 residual, extra reward
        if next_item_size >= post_residual {
            // next item cannot use this bin anyway; penalize wasted space relative to mean
            score += 0.15 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Penalize creating dead space below the minimum item size (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item is large and current item leaves awkward residual, allow new bin
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates usefully
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight preference to fill older/denser bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack_after_next = post_residual - next_item_size;
            // reward if next item leaves small dead space
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a gap that blocks it
            let gap = next_item_size - post_residual;
            if gap > 0 && post_residual > 0 {
                score += 15.0 * (gap as f64 / next_item_size as f64);
            }
        }
    }

    // Penalize creating small unusable dead space relative to min item size (~10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // dead space below minimum item size
    }

    // Compare against mean residual: prefer bins with less residual (fuller bins)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Time horizon: late in stream, prefer filling existing bins tightly over opening new ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    } else {
        // New-bin candidate: penalize opening new bins, more so when many open bins exist
        score += 35.0 + 2.0 * open_bins_count as f64 + 15.0 * progress;
        // But allow new bin if item is huge and would leave a very awkward remainder in others
        if item_size >= 70 && post_residual <= 5 {
            score -= 40.0;
        }
    }

    // Slight preference for bins whose residual is close to item size
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 2.0 * norm_post * (1.0 - progress));
    let mut score = post * (0.5 + 0.5 * progress) + 20.0 * poly * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    score -= 15.0 * (1.0 - norm_post).powi(3) * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dead = (norm_post - mean_residual / cap).max(0.0);
    score += 10.0 * dead * dead * cap * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin, scaled by item size
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + norm_item);
    }

    // New-bin candidate: penalize opening a new bin unless residual would be large
    if bin_residual == bin_capacity {
        let waste = (cap - post) / cap;
        score += 30.0 * (1.0 - waste) * (1.0 - progress) + 12.0 * (1.0 - waste);
    }

    // Lookahead: reward bins whose post-residual accommodates the next item
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10.
    // Small post_residuals are "good" (tight fit); reward them more aggressively
    // when they fall into classic packing-friendly classes (0, 10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 200.0; // perfect fit
    } else {
        let harmonic = match pr {
            0..=5 => 0.0,
            6..=10 => 1.0,
            11..=20 => 2.0,
            21..=25 => 1.5,
            26..=50 => 3.0,
            _ => 4.0,
        };
        score += harmonic * 10.0;

        // Modulo-class bonus: residuals that are multiples of 10 or 25 are
        // more likely to be exactly consumed by future items.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 2.0; }
    }

    // Lookahead: if the next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportionally to how well it uses the leftover.
            let fill = next_item_size as f64 / pr as f64;
            score -= 20.0 + 30.0 * fill;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space,
            // worse for very small leftovers (fragmentation).
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has full residual. It should win
    // only when no open bin offers a decent fit. Penalize the fresh bin mildly,
    // more so when several bins already fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + 15.0 * (fitting_bins_count as f64);
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer filling bins whose residual deviates below the mean (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild pressure to use existing bins when many are open.
    score += (open_bins_count as f64) * 0.5;

    // Integer-division threshold: reward placements leaving residual in the
    // "reusable" band (half capacity or less) with a step function.
    if pr <= bin_capacity / 2 && pr > 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that cannot hold typical items are punished hard.
    // Items range 1..100 (unknown dist); treat residuals < 10 as near-worthless dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit is heavily rewarded.
        score -= 80.0;
    } else {
        // Favor larger post_residual (more reusable space) mildly.
        score -= 0.25 * post_residual as f64;
    }

    // Reward tight packing relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / 100.0);
        } else {
            score += 10.0;
        }
    }

    // Mean residual coupling: placing into a bin below mean residual tightens the spread.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: empty bin gets a baseline cost that must be
    // beaten by a genuinely good existing fit.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tight = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.3 * tight.min(60.0) as f64;
        if post_residual == next_item_size {
            score -= 300.0; // chain of perfect fits
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportional waste.
        score += 0.5 * post_residual as f64;
    }

    // Prefer bins whose residual was already below average (tight bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.4 * dev;

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive if nothing fits well.
    if bin_residual == bin_capacity {
        let good_fits = fitting_bins_count.saturating_sub(1);
        if good_fits == 0 {
            score -= 50.0;
        } else {
            score += 200.0 + 10.0 * good_fits as f64;
        }
        // Late in the stream, avoid spawning bins with big unusable space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Slight preference for very full bins overall.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Penalize residuals that are awkward: too small to fit typical items (wasted dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // dead space penalty
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot fit here; residual becomes dead space for the horizon.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large / no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 15.0; // big items are fine in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits, must open
        }
    }

    // Prefer bins with residual below the mean (consolidate fullness).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for bins whose residual is just above item (snug but not exact).
    let snug = (bin_residual as f64 - item_size as f64);
    if snug > 0.0 && snug <= 20.0 {
        score -= 12.0;
    }

    // Late in stream: be more conservative, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor filling.
    score += open_bins_count as f64 * 0.05 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;

    // Core: reward tight fits with a smooth non-linear decay in post_residual
    let mut score = post * post / cap + post * (1.0 - progress);

    // Extra reward for near-perfect fills, smoothly scaled by stream progress
    score -= 12.0 * (fill * fill * fill) * (0.5 + 0.5 * progress);

    // Penalize creating dead space that can't fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.0 + progress);
        } else {
            // reward residuals that still accommodate the next item
            score -= 2.0 * (post - nxt).min(20.0) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 - post / cap);
    }

    // New-bin candidate: baseline cost, softened when many bins are open and mean residual is high
    if bin_residual == bin_capacity {
        score = cap * 0.9 - 0.05 * mean_residual * (open_bins_count as f64).ln_1p();
        // prefer opening new bins late in the stream when open bins are fragmented
        if mean_residual > 25.0 { score -= 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: dead space quality by residue class
    // post_residual in (0..10] is nearly unusable dead space (min item size 1..100 unknown, but small)
    let pr = post_residual;
    let class: f64 = match pr {
        0 => 0.0,
        1..=5 => -0.5,          // tiny dead space, acceptable
        6..=15 => 6.0,          // awkward dead zone
        16..=30 => 2.0,
        31..=60 => 0.5,
        _ => -1.0,              // large residual, bin still useful
    };
    score += class;

    // Integer-division thresholds: reward leaving residuals that are likely
    // to fit a future item (multiples of common sizes)
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0) {
        score -= 3.0;
    }

    // Lookahead coupling: penalize if next item can't use this bin's post residual
    if next_item_size > 0 {
        if next_item_size > pr {
            score += 5.0; // this bin dies for the next item
        } else if next_item_size == pr {
            score -= 20.0; // chain of perfect fits
        } else {
            let new_pr = pr - next_item_size;
            if new_pr <= 10 {
                score -= 8.0; // next item nearly empties this bin
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty-bin less attractive unless
    // no open bin fits well (post_residual close to capacity means bad fit here)
    if bin_residual == bin_capacity {
        // opening a new bin costs one bin; only attractive if this item fits
        // very poorly elsewhere. Base penalty:
        score += 8.0;
        // but if item is large relative to capacity, a fresh bin is natural
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
        // late in the stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score -= 4.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it's a small leftover bin), prefer packing it tightly
    let res_f = bin_residual as f64;
    if res_f + 1.0 < mean_residual {
        score -= 2.0 * (mean_residual - res_f) / bin_capacity as f64;
    }

    // Mild penalty for spreading across many open bins
    if open_bins_count > 5 {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any item (min size 1,
    // but realistically small gaps) are wasted space. Penalize gaps below a
    // usable threshold with a steep non-linear term.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is the best outcome: strongly reward.
        score -= 120.0;
    }

    // Tightness reward: the smaller the post_residual (within usable range),
    // the better the fit. Reward proportional closeness to zero.
    if post_residual >= 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize candidates that leave
    // large residuals when bin count is already high.
    let ob = open_bins_count as f64;
    if open_bins_count > 0 {
        score += 2.5 * ob * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the ONLY bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "dirty" bin; using it cleans up the bin landscape.
    let dev = mean_residual - bin_residual as f64;
    score += 0.35 * dev;

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // reserving that space; if next item cannot fit post_residual, the gap
    // becomes more dead — penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists (fitting bins are dirty) or
    // when bin pressure is low.
    if bin_residual == bin_capacity {
        let dirty_fits = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let openness = 1.0 / (1.0 + ob * 0.35);
        // Base cost of opening a new bin grows with open bin count.
        score = 55.0 + 3.0 * ob
            - 30.0 * openness
            - 8.0 * dirty_fits as f64
            // If the item is large relative to capacity, opening fresh is safer.
            - 0.4 * item_size as f64;
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 + 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post-residuals that cannot host the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + 0.5 * post_residual as f64;
    }

    // Penalize leaving residual far below typical small-item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins whose post-residual stays near/above mean.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
    }

    // Slight preference for tighter fits as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful
    // (assume future items can be as small as 1, but typical items larger).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // near-unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual (perfect chain),
    // penalize if next item fits but wastes the slot.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            let chain_waste = post_residual - next_item_size;
            score += 0.5 * chain_waste as f64;
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += 3.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is attractive when the item
    // is large and no open bin fits well, or when open bins are already crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a bin, discounted early in the stream.
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        // If many open bins exist, prefer consolidating into them.
        new_bin_cost += 1.5 * open_bins_count as f64;
        // If mean residual is large, open bins have room; discourage new bin.
        new_bin_cost += 0.4 * mean_residual;
        // Large items into fresh bins are fine (avoids fragmentation).
        if item_size >= 60 {
            new_bin_cost -= 15.0;
        }
        // If no open bin can fit (fitting_bins_count counts only open bins),
        // new bin is essentially forced.
        if fitting_bins_count == 0 {
            new_bin_cost -= 200.0;
        }
        score += new_bin_cost;
    }

    // Mild time pressure: late in the stream, prefer using existing space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - fit_ratio);

    // Small stabilization: prefer bins whose residual deviates favorably from mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: prefer tight fills (small post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth polynomial coupling with stream progress:
    // early on, mild preference for tight packing; later, stronger.
    let progress_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 12.0 * progress_term * (cap - post) / cap;

    // Dead-space penalty: post_residual that no future item (>=1) can use well.
    // Penalize small-but-nonzero post residuals non-linearly.
    if post > 0.0 {
        score += 8.0 * (1.0 - norm_post).exp() * (post / (post + 5.0));
    }

    // Lookahead: reward if next item fits in post_residual (smooth reward).
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= post { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((next_item_size as f64 - post).abs() / cap);
        score -= 10.0 * fits * closeness.max(0.0);
        // Penalize when next item is close to post but slightly larger (near-miss waste)
        let near_miss = ((next_item_size as f64 - post) / cap).max(0.0);
        score += 6.0 * near_miss * (1.0 - near_miss).max(0.0) * 4.0 * near_miss.min(0.25) / 0.25;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: keep base ordering
        score += 0.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    let open_f = open_bins_count as f64;
    score += 0.5 * (open_f / (open_f + 5.0)) * norm_post * cap;

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += 0.3 * (mean_residual - post);

    // New-bin candidate handling: empty bin gets neutral-ish score so it wins
    // only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = cap - 0.5 * item + 15.0 * progress_term;
        // discourage opening new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 && post >= 0.0 {
            score += 20.0 * (1.0 - norm_post);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic class bonus: exact modulo match of post_residual to next item size
        // (chain packing potential), scaled by how much room remains after.
        let chain = post_residual / next_item_size;
        score -= 20.0 + 5.0 * chain as f64;
        if post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Dead space for the lookahead item: penalize unusable slivers.
        let min_item = 1u32;
        if post_residual < min_item {
            score += 50.0;
        } else if post_residual < next_item_size {
            // Sliver too small for next item: penalize more when it's a "hard" class
            // (odd leftover that few items will ever fill).
            score += 10.0 + (post_residual % 7) as f64 * 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Harmonic class of post_residual: quantize into capacity fractions.
    // Residuals in "awkward" classes (small odd leftovers) get a penalty,
    // large usable residuals are mildly preferred for big items.
    let class = post_residual / 10;
    match class {
        0 => score += 25.0,          // 0-9: nearly dead
        1 => score += 12.0,          // 10-19: only tiny items fit
        2 => score += 5.0,           // 20-29
        3 => score += 1.0,           // 30-39
        _ => {}                      // >=40: flexible
    }

    // New-bin candidate (residual == capacity): make it attractive only when
    // the item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Large items deserve fresh bins; small items should reuse open bins.
        score -= 30.0 * fill_frac;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference for bins below mean residual (keeps residual distribution balanced).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Slight preference for using already-open bins vs. opening more.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small but still usable residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Penalize bins whose residual barely exceeds the item (awkward near-fit).
    if post_residual > 0 && post_residual < item_size / 4 + 1 {
        score += 15.0;
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use this leftover space: penalize proportionally
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 + 2.0 * fitting_bins_count as f64 };
        score += pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for any plausible future item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Two-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // next item won't fit here: penalize proportionally to wasted gap.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are more "packed",
    // favor finishing them off; bins above mean should absorb big items.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless the stream is early or many bins open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 200.0 - 150.0 * progress + 2.0 * open_bins_count as f64;
        // But allow opening when item leaves a very tight residual (good long-term fit).
        if post_residual <= 5 {
            score -= 250.0;
        }
    }

    // Slight tie-breaker favoring tighter fills as stream progresses.
    score += 0.01 * (step_index as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual approaches 0.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) * 0.35;

    // Penalize dead space that is too small for typical items (unusable slivers).
    if pr > 0 && pr < 10.0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // reward leaving room for the next item
            score -= (pr - nxt).max(0.0) * 0.6;
        } else {
            // penalize leaving a residual the next item cannot use
            score += (nxt - pr).min(30.0) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // this bin would waste a lot of space, or the stream is early/many bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity as f64 - item_size as f64);
        // base cost of a new bin
        score += 45.0;
        // attractive if item is large (little waste in a fresh bin)
        score -= (100.0 - waste) * 0.2;
        // early in stream, prefer consolidation less; late, prefer consolidation more
        score += progress * 20.0;
        // if many bins are open already, discourage opening another
        score += open_bins_count as f64 * 1.5;
        // if mean residual across bins is high, existing bins likely usable
        score += mean_residual * 0.4;
    } else {
        // Slight preference for using already-open bins proportional to fill.
        let fill = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        score -= fill * 12.0;
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps the pool of usable residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = r * (1.0 + 0.35 * progress) - 0.9 * (rn * (1.0 - rn)) * cap * (1.0 - 0.5 * progress);

    // Penalize large dead space nonlinearly
    score += 0.25 * r * r / cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - rn) * (1.0 - rn) * (0.5 + progress);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.15 * gap;
        if next_item_size as f64 <= r {
            score -= 6.0;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 10.0 * (1.0 - rn);
    }

    // Slight preference for consolidating into fewer bins
    score += 0.05 * open_bins_count as f64 * rn;

    // Keep new-bin candidate from winning too easily unless residuals are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10
    let residue_class = (post_residual % 10) as f64;
    // Bins whose post residual is a "nice" multiple of 10 are easier to fill later
    score -= 8.0 * (10.0 - residue_class) / 10.0; // reward small residue (tight fit) mod 10

    // Integer-division thresholds: post_residual buckets of size 10
    let bucket = post_residual / 10;
    match bucket {
        0 => score -= 25.0,               // nearly full bin: excellent
        1 => score -= 15.0,
        2 => score -= 5.0,
        3 => score += 5.0,
        4 => score += 12.0,
        5 => score += 18.0,
        6 => score += 25.0,
        _ => score += 30.0,               // half empty or more: wasteful
    }

    // Coupling with next item: harmonic class of next_item_size mod 10
    if next_item_size > 0 {
        let next_class = (next_item_size % 10) as f64;
        // If the next item would fit exactly into post_residual, big reward
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 20.0 - (slack_after_next as f64) * 0.3;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 10.0 + next_class * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default
    if bin_residual == bin_capacity {
        score = 55.0
            + mean_residual * 0.1
            - (open_bins_count as f64) * 2.0
            + (post_residual as f64) * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // next item is large, fresh bin is attractive
        }
        if fitting_bins_count <= 1 {
            score += 20.0; // don't abandon the last fitting open bin too easily
        }
    }

    // Progress term: late in the stream, prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is far from the mean, slight penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Strict dead-space avoidance: post_residual that no item (min size 1..10 range)
    // can ever use is wasted; penalize small gaps harshly.
    if post_residual > 0 {
        let dead_threshold = 10u32.min(next_item_size.max(1));
        if post_residual < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual) as f64;
        }
        // Gap unusable by lookahead item: penalize proportionally.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Perfect fit: big reward.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += 0.8 * open_bins_count as f64;

    // Slight preference toward bins below mean residual (consolidate emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Late in stream, prefer tighter packing overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is highly desirable
        if diff == 0.0 {
            score -= 25.0;
        } else {
            score += diff * 0.35;
        }
        // If next item cannot fit here after placement, mild penalty scaled by tightness
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Penalize unusable dead space relative to the smallest possible item (assume ~1..100 unknown, use 10 baseline)
    let dead = post_residual as f64;
    if dead > 0.0 && next_item_size > 0 && dead < next_item_size as f64 {
        score += dead * 0.2; // dead space below next item size is likely wasted
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins tighter than the mean residual (good fits leave less room than average)
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Slight preference for filling bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits, open a new bin
        } else {
            score += 15.0; // discourage opening new bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 heuristic: <20)
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Baseline penalty for opening a new bin
        score += 60.0;
        // More acceptable early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Less acceptable when many bins are already open
        score += 2.0 * open_bins_count as f64;
        // If the current item leaves a lot of waste anyway, new bin is fine
        if post_residual <= 15 {
            score -= 30.0;
        }
        // If the next item is large and wouldn't fit anywhere after this placement,
        // a fresh bin is more attractive
        if next_item_size > 0 && next_item_size > bin_capacity.saturating_sub(item_size) {
            score -= 10.0;
        }
    } else {
        // Prefer bins with residuals below the mean (consolidate small leftovers)
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Mild preference for reusing bins as stream progresses (avoid bin explosion)
    score += 0.05 * open_bins_count as f64;

    // Small time-horizon modulation: later in stream, be more conservative with waste
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let prog = t * (1.0 - t); // peaks mid-stream
    score -= 12.0 * prn * prn * prog * cap * 0.01;
    score += 4.0 * prn * t * t; // late-stream penalty on leftover space

    // Reward tight fits smoothly
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * fill * (1.0 - t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * (1.0 - t);
    }

    // Lookahead: reward residual that can hold the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / cap) * (1.0 - t);
    }

    // Penalize deviation from mean residual (keeps bins balanced)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: mildly discourage unless current residuals are tight
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals near useful fractions of capacity
    let pr = post_residual as f64;
    let frac = pr / cap;
    // Dead-space penalty: residuals too small to ever fit (below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward "perfect" residuals: multiples of common item sizes (10,20,25,50)
    let harmonic_bonus = |r: u32| -> f64 {
        if r == 0 { return -15.0; }
        let mut b = 0.0;
        for m in [10u32, 20, 25, 50, 100] {
            if r % m == 0 { b += 4.0; }
        }
        // fractional closeness to half/quarter capacity
        let d = (frac - 0.5).abs();
        if d < 0.1 { b += 3.0; }
        let d2 = (frac - 0.25).abs();
        if d2 < 0.05 { b += 2.0; }
        b
    };
    score -= harmonic_bonus(post_residual);

    // Lookahead: penalize if post_residual cannot fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64) * 0.1;
        } else {
            score += 8.0;
        }
        // Harmonic coupling: next item aligns with residual modulo classes
        if next_item_size <= post_residual && (post_residual % next_item_size.max(1) == 0) {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = mean_residual / cap;
        score += 12.0 - 20.0 * crowd;
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Tight-fit reward
    if item_size == bin_residual {
        score -= 18.0;
    }

    // Stream progression: later in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // Gaps below the smallest item size (1) are trivially unusable, but gaps
    // below a conservative "practical minimum" are highly likely to become
    // dead space given unknown distributions. Penalize sharply.
    let practical_min = 12.0;
    if (post_residual as f64) < practical_min {
        score += (practical_min - post_residual as f64) * 6.0;
    }

    // Perfect fit reward: strongly favor exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Open bins pressure: discourage spreading across many bins when few
    // bins can fit the item (last-chance bins deserve priority).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count >= 3 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current bin would leave a large dead gap or the item barely fits
    // elsewhere. Neutral residual baseline; penalize opening new bins when
    // many bins are already open (pressure to consolidate).
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But if placing here would waste more than half the bin elsewhere,
        // a new bin becomes competitive.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Lookahead coupling: if the next item could use the post residual well,
    // reward leaving exactly that much space; penalize residuals that neither
    // fit the next item nor are near zero.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= ni && pr - ni <= 10.0 {
            score -= 10.0; // next item slots in snugly
        } else if pr < ni && pr > 0.0 {
            score += 5.0; // residual too small for lookahead item
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean — filling below-average-residual bins tightens packing.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Mild consolidation pressure as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // exact chain: bin becomes perfectly reusable
        } else {
            score += diff * 0.8; // penalize mismatch with next item's demand
        }
        // If next item cannot fit after placement, penalize proportionally
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins whose residual is near mean (balanced packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize tiny unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when item barely fits anywhere else
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0; // open bin could still chain, prefer reusing
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead space relative to next item: penalize unusable gap.
            score += 0.25 * (post_residual as f64) * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64));
        }
    }

    // Time horizon: early in the stream, be pickier (prefer tight fits); late in
    // the stream, prefer spreading load to keep residuals usable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    score += 8.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // Global state coupling: many open bins with large mean residual -> favor
    // filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_alternatives = if fitting_bins_count <= 1 && post_residual > item_size / 2 { 1.0 } else { 0.0 };
        score += 55.0; // base cost of opening a new bin
        score -= 70.0 * scarcity;
        score -= 30.0 * poor_alternatives * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Small residual waste penalty: leaving tiny unfillable gaps is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a smooth non-linear penalty on wasted space
    let mut score = pr as f64;

    // Non-linear polynomial coupling: dead space matters more as stream progresses
    let waste_penalty = norm_pr * norm_pr * (1.0 + 3.0 * progress) * cap * 0.5;
    score += waste_penalty;

    // Cubic term: heavily penalize mid-range residuals that are hard to fill
    score += 20.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Lookahead: reward bins whose post_residual fits the next item well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let tight = 1.0 - ((pr - nxt) / cap);
            score -= 8.0 * tight * tight * (1.0 + progress);
        } else {
            // next item won't fit here; mild penalty scaled by gap
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        // slight preference for bins among many competitors that fit tightly
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Encourage consolidation toward mean residual alignment
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only when open bins would leave large waste
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        let new_bin_appeal = 5.0 + 10.0 * progress + 0.2 * open_bins_count as f64;
        score = new_bin_appeal + best_possible * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in "small" bands is worse.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit, best possible outcome
    } else if pr < 10 {
        score -= 18.0; // near-perfect, unusable sliver is fine
    } else if pr <= 20 {
        score -= 6.0; // still usable by smallest items
    } else if pr <= 35 {
        score += 3.0; // awkward middle band
    } else if pr <= 50 {
        score += 8.0;
    } else {
        score += 12.0; // large residual wasted on a big item
    }

    // Modulo-10 class penalty: residuals congruent to small classes are harder to fill.
    let m = (pr % 10) as f64;
    score += m * 0.4;

    // Reward tight fill ratio of the bin (integer division threshold).
    let fill = bin_capacity - bin_residual; // used space before placement
    let used_after = fill + item_size;
    if used_after * 2 >= bin_capacity {
        score -= 4.0; // bin crosses half-full threshold
    }
    if used_after * 4 >= bin_capacity * 3 {
        score -= 6.0; // crosses three-quarters threshold
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr && pr - next_item_size < 10 {
            score -= 10.0;
        } else if next_item_size > pr && next_item_size <= bin_residual {
            score += 5.0; // next item would prefer this bin's pre-state; mild penalty
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        score = 60.0
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64).sqrt() * 3.0
            + (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 4.0;
        }
        if step_index as f64 / total_items as f64 > 0.9 {
            score += 6.0; // late in stream, avoid sprawl
        }
    }

    // Mild penalty for hoarding many open bins.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: reward very tight fits (small unusable leftovers
    // are eliminated entirely), penalize mid-range gaps that tend to become dead space.
    let pr = post_residual as f64;
    score -= 30.0 * (-pr / 8.0).exp();          // exponential bonus for near-perfect fits
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;                           // tiny gap: slightly worse than a perfect fit
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 6.0 * (1.0 - (pr - 10.0) / 20.0); // awkward mid-range leftover zone
    }

    // Penalize candidate bins whose residual is far above the mean (hoarded space),
    // which pushes selection toward bins already partially filled.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0; // leftover will likely be dead space for the next item
    }

    // Open-bins pressure: with many open bins, consolidate aggressively
    // (deepens the reward for tight fits as the stream progresses).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress * 0.5);

    // New-bin candidate: make the empty bin strictly unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: minimize wasted space after placement.
    let mut score = post;

    // Strong reward for exact/tight fit (dead space near zero).
    if post <= 0.5 {
        score -= 40.0;
    } else if post <= 5.0 {
        score -= 25.0 - post * 3.0;
    }

    // 2-step lookahead: reward when post_residual exactly accommodates the next item.
    if next > 0.0 {
        let gap = (post - next).abs();
        if gap <= 0.5 {
            score -= 30.0; // perfect chain: this bin will be exactly filled next step
        } else if next <= post {
            // next item fits: reward proportionally to how well it uses leftover
            let fill_ratio = next / post.max(1.0);
            score -= 20.0 * fill_ratio;
        } else {
            // next item does NOT fit: penalize leftover space that's stranded
            let stranded = post / cap;
            score += 15.0 * stranded;
        }

        // Two-item chain: post_residual fits next item and then remains small
        if next <= post && (post - next) <= 5.0 {
            score -= 15.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (fill fuller bins first, keep emptier bins flexible).
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= 8.0 * (dev / cap).min(1.0);
    } else {
        score += 4.0 * ((-dev) / cap).min(1.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin is decent
    // (empty bin has large post_residual, so base score already high;
    //  add mild penalty unless late in stream with few bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 - 8.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Slight preference for filling nearly-full bins as stream progresses.
    let fullness = 1.0 - (bin_residual as f64 / cap);
    score -= 6.0 * fullness * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    let fill_ratio = 1.0 - post / cap;
    score -= 2.5 * fill_ratio * fill_ratio * cap * 0.1;

    // Penalize leaving awkward dead space (small but nonzero residual).
    if post > 0.0 && post < 10.0 {
        score += 6.0 * (1.0 - post / 10.0);
    }

    // Lookahead: reward if the next item can also fit into the post-residual
    // (chain packing), penalize if it just barely cannot.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 * (nxt / post.max(1.0));
        } else {
            score += 2.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mildly discourage hoarding many open bins when residuals are large.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * spread;
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current item is large (a fresh bin wastes less capacity) or when
    // existing bins would leave a very poor fit.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / cap;
        score += 12.0 * (1.0 - item_ratio); // small items in fresh bins are bad
        if post < 15.0 {
            score -= 5.0; // large item nearly fills the fresh bin
        }
    }

    // Late-stream pressure: near the end, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 3.0 * progress * (item_size as f64 / bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear penalty on small leftovers
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic residual waste term scaled by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize residuals that are too small to be useful (dead space), smoothly
    let deadness = 1.0 - (pr / 10.0).min(1.0);
    score += 15.0 * deadness * deadness;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * 8.0 * progress;

    // Last-chance bonus: only fitting bin -> strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        score -= 10.0 * fits_next * (pr - next_item_size as f64) / cap;
        // penalize if post residual barely misses next item
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.3 * gap.min(10.0);
    }

    // Coupling with mean residual: avoid bins far from the mean early on
    score += 2.0 * ((pr - mean_residual) / cap).abs() * (1.0 - progress);

    // New-bin candidate: penalize opening new bins unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * norm_pr;
    }

    // Mild penalty for spreading across many bins
    score += 0.5 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: bins whose leftover falls into
    // "small remainder" classes (<= 10 or exactly divisible by common item
    // sizes) are more likely to be filled by later small items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if pr <= 10 {
        score -= 25.0; // near-perfect fit, low dead-space risk
    } else {
        // reward post-residuals that are multiples of small item classes
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 30 == 0 || pr % 40 == 0 || pr % 50 == 0 { score -= 8.0; }
    }

    // Penalize awkward dead-space classes: primes and odd residuals in mid range
    if pr > 10 && pr < 50 && pr % 2 == 1 {
        score += 6.0;
    }
    // Very awkward zone: 51..=69 leftover (too big to waste, too small for big items)
    if (51..=69).contains(&pr) {
        score += 9.0;
    }

    // --- Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // guaranteed chain fill
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 { score -= 20.0; }
            else if slack <= 20 { score -= 8.0; }
            else { score += slack as f64 * 0.15; }
        } else {
            // next item cannot fit here; leftover is pure dead space
            score += (pr as f64) * 0.35;
        }
    }

    // --- Last-chance bonus: only bin that fits avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling: empty bin should only win when nothing
    // else is attractive. Base penalty decays as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 55.0 - 25.0 * progress;
        // opening a fresh bin is fine if item is huge (few future fits anyway)
        let huge_bonus = if item_size >= 70 { 25.0 } else if item_size >= 50 { 10.0 } else { 0.0 };
        score += (base - huge_bonus).max(0.0);
        // if no open bin fits, new bin is the only option
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // --- Mild pressure to consolidate: prefer bins tighter than the mean
    score += (mean_residual - bin_residual as f64) * 0.1;

    // --- Slight preference for fuller bins among many open bins
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Integer-division threshold on item_size: large items prefer tight bins
    if item_size / 20 >= 3 {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (<10) are unusable for future items
    // in the classic regime, so heavily penalize them.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium-small gaps (10..20) are also poor fits for typical item sizes.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only prefer it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
        // Lookahead: if next item is small enough to use typical residuals, prefer existing bins.
        if next_item_size > 0 && next_item_size <= mean_residual {
            score += 15.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is close to mean (balance the pool).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Lookahead synergy: reward placements leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if post_f >= next_f {
            let slack = post_f - next_f;
            // Perfect chain: next item fills this bin exactly afterward
            if slack == 0.0 {
                score -= 400.0;
            } else if slack <= 10.0 {
                score -= 150.0;
            }
            // Penalize residual that next item can't use at all (dead space risk)
            if post_f < next_f * 0.4 {
                score += 120.0;
            }
        } else {
            // Next item cannot fit into post-residual: residual likely wasted
            score += 60.0 + (next_f - post_f) * 0.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    let dev = mean_residual - post_residual as f64;
    score -= dev * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Mild penalty for spreading across too many open bins late in stream
    if open_bins_count > 8 && post_residual > 0 {
        score += (open_bins_count as f64 - 8.0) * 2.0;
    }

    // Prefer filling fuller bins early (tight packing), scaled by progress
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 50.0 * (step_index as f64 / total_items.max(1) as f64);

    // New-bin candidate: make empty bin attractive only when current fit is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 250.0;
        // But if this item is large and would leave bad residual in others, empty bin is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: squared post-residual penalizes dead space nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward if lookahead would then nearly fill the bin.
            let second_post = post_residual - next_item_size;
            if second_post <= 5 {
                score -= 30.0;
            }
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_residual as f64).min(1.0);
        // Opening a new bin is attractive only when item is large relative to
        // residuals and many bins are already open (fragmentation risk).
        let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 3.0))
            * (mean_residual / bin_capacity as f64);
        score = 55.0 + pressure * 40.0 - tightness * 30.0;
        if fitting_bins_count == 1 {
            score += 60.0; // don't abandon the only fitting bin
        }
    }

    // Time-horizon modulation: early in stream, be conservative about
    // fragmenting bins; late, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 * 0.15);
    score -= progress * (bin_residual as f64 / bin_capacity as f64) * 12.0;

    // Prefer bins whose residual is below the mean (consolidate emptier space usage).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Mild preference for filling larger-residual bins when many bins open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tighten tolerance for wasted space more aggressively
    let coupling = 1.0 + progress * (1.0 - progress) * 4.0 * norm_pr;
    score += pr * coupling * 0.5;

    // Penalize very small dead space less than mid-range waste (smooth quadratic valley)
    score -= norm_pr * (1.0 - norm_pr) * cap * 0.3;

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    }

    // Lookahead: reward leaving space that the next item can still use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= nxt * fit_quality * 0.4;
        } else {
            score += (nxt - pr) * 0.2;
        }
    }

    // Prefer fuller bins when many bins are open (smooth pressure term)
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * norm_pr * 2.0;

    // Deviation from mean residual: penalize outliers smoothly
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.2;

    // New-bin candidate: make empty bins mildly attractive only for poor fits
    if bin_residual == bin_capacity {
        score += cap * 0.25 - item_size as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 5 harmonic bands.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_residual * 5 / bin_capacity) as i32; // 0..4

    // Reward small post residuals, but with class-dependent bonuses
    // (dead space of a "harmonically useful" size is less penalized).
    match class {
        0 => score -= 8.0,                       // near-perfect fill
        1 => score -= 3.0,                       // good fill
        2 => score -= 1.0,                       // mediocre
        3 => score += 2.0,                       // large gap
        _ => score += 5.0,                       // mostly empty bin used
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common small item sizes (10/20/25) are more reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic class of the lookahead fit quality
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 - 4.0 * (slack / cap_f);    // tight lookahead fit rewarded
        if (next_item_size % 10 == 0) && (post_residual % 10 == 0) {
            score -= 2.0;                        // aligned harmonic pair
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover; penalize proportionally to waste
        score += 1.5 + 3.0 * (post_f / cap_f);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer keeping item with the current stream state;
    // penalize opening a new bin unless the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0;            // baseline cost of a fresh bin
        new_bin_score -= 0.3 * open_bins_count as f64; // fewer open bins -> cheaper to open
        if item_size >= 50 {
            new_bin_score -= 10.0;               // large items like fresh bins
        }
        if next_item_size > 0 && next_item_size >= 60 {
            new_bin_score += 8.0;                // big next item: save fresh bins
        }
        new_bin_score += 5.0 * progress;         // later in stream, slightly cheaper
        score = score.max(0.0) * 0.5 + new_bin_score;
    }

    // Tie-break with mean residual coupling: prefer bins below mean residual
    // (keeps residuals balanced across the fleet).
    score -= 0.05 * (mean_residual - post_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: leftover gaps too small for any item (min size 1,
    // but practically tiny gaps) are wasted. Penalize residuals in the "dead zone".
    let dead_threshold = 4u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item almost fits (small miss), mild penalty for creating a tempting gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer tight fits
    // (low post_residual). When few bins are open, tolerate looser fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when the item is large
    // relative to the residual or fits are scarce.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to what we consume (tight fit),
    // penalize wasting large residuals on small items.
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += waste_ratio * 10.0;

    // Mean residual coupling: if average residual is high, encourage consolidating
    // into bins (favor bins below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving almost no space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 500.0;
        } else if diff <= 3.0 {
            score -= 250.0 - 50.0 * diff;
        } else {
            // penalize residual that neither fits next item nor is tiny
            score += 0.6 * diff;
        }
        // If next item cannot fit in this bin's post residual, mild penalty
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual)
    // than the mean residual of open bins.
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Penalize large dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small unusable scrap is fine
    } else if post_residual >= 10 && post_residual < 40 {
        score += 0.3 * post_residual as f64; // mid-range waste is worst
    }

    // Early in the stream, allow opening new bins more freely;
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good fit exists.
        score += 120.0 - 80.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        score -= 40.0 * progress;
    }

    // Slight preference for bins with more open bins (spread consolidation).
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - leftover / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that next item cannot use; penalize proportionally.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If many open bins have large mean residual, prefer reusing them.
        score += 0.3 * mean_residual;
        // If no open bin fits at all, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 14.0;
        }
    }

    // Mild preference for fuller bins among equals.
    score -= 0.1 * (bin_residual as f64 - post_residual as f64);

    // Penalize bins whose residual becomes tiny and unusable (< 10).
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Time-horizon: later in stream, prioritize compactness.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly,
    // large dead space is penalized super-linearly.
    let pr = post_residual as f64 / cap;
    let poly = pr * pr * (0.5 + 1.5 * progress) + pr * (1.0 - progress) * 0.3;
    score += poly * cap;

    // Smooth decay of residual value with stream progress: leftover space matters less early
    score -= (1.0 - progress) * 0.15 * pr * pr * cap;

    // Last-chance bonus: strongly prefer the only fitting bin (subtract to favor)
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild competition penalty scaled by number of alternatives
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // lookahead coupling: reward leaving room close to the next item size
        if next_item_size > 0 {
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 12.0 * (1.0 - gap / cap).max(0.0);
        }
    }

    // New-bin candidate handling: keep it available but usually slightly worse
    // than a decent fit; becomes attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 5.0 * open_bins_count as f64 - 0.1 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with a large next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class by integer division thresholds of capacity quarters.
    let q = post_residual / 25; // 0..4 harmonic class
    let class_bonus: f64 = match q {
        0 => 0.0,        // dead space, heavily penalized below
        1 => -6.0,       // residual in [25,50): quite usable
        2 => -10.0,      // residual in [50,75): very usable
        _ => -12.0,      // residual >= 75: excellent
    };
    score += class_bonus;

    // Perfect fits: modulo arithmetic on residual
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // round-number residual is reusable by common sizes
    }

    // Penalize small dead space (<10) — nothing can fit in it later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the leftover fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(20.0) * 0.2;
            if post_residual == next_item_size {
                score -= 20.0; // perfect chain
            }
        } else {
            score += 5.0; // next item can't use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Tightness ratio: reward filling a large fraction of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Early in stream: keep bins flexible (mild penalty for very tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && item_size > 70 {
        score += 4.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // if no decent fitting option exists; make empty bin moderately costly.
    if bin_residual == bin_capacity {
        score += 10.0;
        // but if many open bins exist and none fit well, allow opening
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in stream, prefer consolidating into open bins
        if progress > 0.7 {
            score += 6.0 * progress;
        }
    }

    // Mean residual context: if this bin is far below mean residual,
    // it's a good "garbage collector" bin — reward using it.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Harmonic residue penalty: residuals that are awkward primes mod 10
    if post_residual % 10 != 0 && post_residual < 25 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10, minimum item size)
    // are the worst outcome; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable when open bins are few or mean
        // residual is small (existing bins nearly full).
        score += 20.0 + 3.0 * pressure;
        score -= (mean_residual / 10.0).min(12.0);
    } else {
        // Favor fuller bins slightly (smaller residual = better packing).
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Early in the stream, allow new bins more freely to build diversity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover after the pair (dead space minimization).
            score -= 0.5 * (post_residual - next_item_size) as f64;
            if post_residual - next_item_size == 0 {
                score -= 400.0;
            }
        } else {
            // Next item won't fit here: penalize small unusable residuals.
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Penalize residuals far below the mean (creating isolated dead space).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.3 * (mean_residual - pr);
    } else {
        score -= 0.1 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late in stream: prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: near-full fills are excellent (best-fit core, sharpened).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize small dead space that nothing can use (post_residual < 10 unusable),
    // but reward moderately small residuals lightly.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting a flexible slot
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless existing
    // bins are all poorly suited. Base penalty for a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheap; late, prefer filling existing.
        score += 20.0 * (1.0 - progress) + 8.0;
        // If many bins are open with slack, avoid new bins.
        score += 0.5 * open_bins_count as f64;
        // If mean residual is large, an open bin likely fits — penalize new bin more.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Reward using bins with residual close to mean (balanced depletion).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        // Slight preference for fewer open bins overall.
        score -= 0.3;
    }

    // Time-horizon coupling: as stream progresses, tighten packing pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Item-size coupling: large items in roomy bins are fine; small items
    // should not occupy large-residual bins.
    if item_size < 25 && bin_residual > 60 {
        score += 5.0;
    }
    if item_size > 60 && bin_residual >= item_size && bin_residual <= item_size + 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress: later in stream, waste is costlier
    score += 30.0 * norm_pr * norm_pr * (progress * progress);

    // Reward filling bins deeply (large item fraction relative to residual)
    score -= 12.0 * norm_item * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize post_residual that is too small to be useful later (dead space), smooth trough
    let useless = ((pr - 15.0) / 15.0).powi(2).min(1.0);
    score += 8.0 * useless * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin gets a penalty that decays as fits become scarce
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score = cap * (1.0 + 0.5 * progress) - 15.0 * scarcity * (1.0 - progress);
        // If item is large relative to capacity and no tight fit exists, new bin becomes attractive
        score -= 10.0 * norm_item * norm_item;
    }

    // Mild diversity pressure: avoid concentrating residual far from mean
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    // Open-bin count pressure: with many bins open, prefer consolidation
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by modulo arithmetic
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = pr / cap;
    score += 40.0 * waste_frac * waste_frac; // quadratic penalty on dead space fraction

    // Harmonic classes: post_residual mod small integers reveal "friendly" gaps
    let pr_u = post_residual;
    // Perfect fit bonus
    if pr_u == 0 {
        score -= 60.0;
    } else {
        // Gaps that are multiples of common item sizes are reusable
        let gap_class: f64 = if pr_u % 10 == 0 {
            -25.0 // gap is a multiple of 10: highly reusable
        } else if pr_u % 5 == 0 {
            -10.0
        } else if pr_u % 3 == 0 {
            -3.0
        } else {
            8.0 // awkward gap, penalize
        };
        score += gap_class;

        // Integer-division thresholds: small residuals are dead space
        if pr_u <= 10 {
            score += 30.0;
        } else if pr_u <= 20 {
            score += 12.0;
        } else if pr_u <= 35 {
            score += 4.0;
        }
    }

    // Lookahead coupling: does the gap fit the next item exactly or well?
    if next_item_size > 0 {
        let nx = next_item_size;
        if pr_u == nx {
            score -= 45.0; // perfect lookahead fit
        } else if pr_u >= nx {
            let slack = (pr_u - nx) as f64;
            score -= 20.0 * (1.0 - slack / cap); // reward next item fitting with little slack
            // harmonic match: gap and next item share residue class
            if pr_u % 10 == nx % 10 {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 + 15.0;
        if crowded && fitting_bins_count > 0 {
            score += 50.0; // discourage opening new bin when a fitting bin exists
        } else {
            score -= 5.0 + 10.0 * progress; // allow new bin early / when nothing fits well
        }
    }

    // Mild preference to balance residuals across open bins
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100)
    // can realistically use are heavily penalized. Small gaps (< 20) are near-waste.
    if post_residual > 0 {
        if post_residual < 20 {
            score += 60.0; // unusable dead space
        } else if post_residual < 40 {
            score += 25.0;
        }
    }

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += fit_ratio * 15.0;

    // Open-bin pressure: penalize creating new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0 + 6.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins, stronger when few fitting bins remain.
        score -= 10.0;
        if fitting_bins_count == 1 {
            score -= 30.0; // last-chance bin: strongly prefer
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would be blocked by the resulting residual, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter bins absorb the item, leaving looser bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: as the stream progresses, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 120.0 / (1.0 + diff);
        // Bonus if item + next item exactly fill the bin
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize residuals too small for the next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 50.0;
    }

    // Reward small post-residuals (tight packing)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize deviation from mean residual: prefer bins with typical remaining space
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let lookahead_bad = next_item_size > 0 && post_residual.saturating_sub(item_size) < next_item_size;
        let new_bin_bonus = 100.0 - 90.0 * pressure
            - if lookahead_bad { 30.0 } else { 0.0 }
            - (open_bins_count as f64).min(10.0) * 2.0;
        score -= new_bin_bonus.max(-80.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is close to the item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness).powi(6) * 18.0;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { (post_residual as f64 / 20.0).powi(2) };
        score += dead * 3.0;
    }

    // Lookahead: reward residual that exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // residual too small for next item: mild penalty scaled by wasted fraction
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // last item: fill as fully as possible
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // bins fit poorly (large mean residual dispersion) early in the stream.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        let mut nb = 30.0; // baseline cost of opening a new bin
        nb -= open_bins_count as f64 * 1.5; // spreading load across bins can help
        nb -= waste * 20.0 * (1.0 - progress); // early on, big items justify new bins
        if next_item_size > 0 && next_item_size <= post_residual {
            nb -= 8.0; // fresh bin can host the next item too
        }
        if fitting_bins_count > 0 && tightness < 0.5 {
            nb -= 15.0; // existing fits are bad -> new bin more attractive
        }
        score += nb;
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins
    score += mean_residual * 0.03 * (open_bins_count as f64).ln().max(1.0);

    // Mild time decay of tightness reward late in the stream (consolidation phase)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear tightness reward: quadratic decay of residual
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * 30.0;

    // Smooth progress coupling: later in stream, prefer fuller packing
    score -= progress * (1.0 - pr / cap) * 25.0;

    // Reward if next item fits into post_residual (chained packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (pr - nxt).powf(1.5) * 0.3 + 10.0;
        } else {
            score += (nxt - pr) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // Penalize residual far from mean residual (keeps bin pool homogeneous)
    score += (pr - mean_residual).abs() * 0.2;

    // Mild penalty for opening new bins when many bins exist
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * open_bins_count as f64;
        // But allow new bin early if fit is very tight elsewhere is impossible —
        // smooth tradeoff with progress
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity fractions
    let frac = (post_residual as f64) / (bin_capacity as f64);
    let class = (frac * 10.0).floor() as i64; // 0..10 harmonic decile

    // Reward near-perfect fits strongly (post_residual in lowest classes)
    score -= match class {
        0 => 40.0,
        1 => 25.0,
        2 => 12.0,
        3 => 4.0,
        _ => 0.0,
    };

    // Penalize awkward dead space: post_residual too small for any typical item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }
    // Harmonic band: residuals in [10, 30) are re-usable by small items
    if post_residual >= 10 && post_residual < 30 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // extra reward if next item nearly fills the remainder
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize proportionally to wasted potential
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if post_residual == bin_capacity && item_size >= bin_capacity / 2 {
            score -= 10.0; // large item into fresh bin is fine
        }
    }

    // Progress modulation: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer bins with low mean residual spread (tighter packing)
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Modulo harmonic classes on post_residual: multiples of 10 are "clean" states
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (1..100).
    let dead_threshold = 10.0_f64.min(post_residual as f64);
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += (10.0 - post_residual as f64) * 12.0; // small leftover = wasted bin space
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= tightness * 20.0;

    // Penalize large leftover gaps that nothing in a typical stream can use well
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 8.0; // gap smaller than the next item's need
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && next_item_size > bin_capacity {
        // next item needs a fresh bin anyway
        score += 0.0;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer consolidation
    // (favor bins with low residual = fuller bins when open_bins_count is high).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 / (mean_residual + 1.0)) * 2.0 * (1.0 - progress);

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit (poor fit = large post_residual or dead gap).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in the stream.
        score = bin_capacity as f64 * 0.75 + 5.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // If next item is large and current item is small, opening a bin may be fine.
        if next_item_size >= item_size * 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 / (1.0 + diff * 0.15));
        // Exact match bonus: next item perfectly fills remaining space
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // Post-residual too small to fit next item: penalize dead space
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 20.0;
    }

    // Relative-to-mean residual term: prefer bins deviating from mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are all too full relative to item
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += 15.0 + scarcity - 0.1 * item_size as f64;
    }

    // Favor filling nearly-full bins (small residual waste)
    score += 0.2 * (bin_capacity - bin_residual) as f64;

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * (next_item_size as f64);
    }
    // If next item almost fits (small gap), slight penalty for wasting space
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins, more so when many bins are open
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if the item is large and mean residual is small, new bin may be better
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.6 {
            score -= 30.0 * (1.0 - progress * 0.5);
        }
    }

    // Prefer filling bins with large residual capacity utilization
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Penalize tiny dead space that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Mild time-varying exploration pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (progress - 0.5) * (mean_residual / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space hurts quadratically, amplified late in stream.
    let waste_frac = post / cap;
    score += waste_frac * waste_frac * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 10.0 * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Discard bins whose leftover cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if (post as u32) < next_item_size {
            score += 6.0 * (1.0 - progress);
        } else {
            score -= 4.0 * (post - next_item_size as f64) / cap;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0 * (1.0 - waste_frac);
    }

    // Mild penalty for very full bins early (keep flexibility), reward late.
    score += (mean_residual / cap) * (1.0 - 2.0 * progress);

    // New-bin candidate: acceptable early (preserve open-bin space) or when
    // this bin's post-residual is tiny dead space; otherwise penalize.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score = post + early * 8.0 - progress * 12.0;
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // opening fresh bin helps chain large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small primes create
    // "usable" vs "dead" classes for typical item sizes.
    let r = post_residual;
    let class_bonus = match r % 10 {
        0 => 14.0, // perfectly harmonic: likely exact future fit
        2 | 5 => 9.0,
        1 | 3 | 7 | 9 => 5.0,
        _ => 0.0, // 4,6,8: awkward even residues
    };
    score -= class_bonus as f64;

    // Integer-division thresholds: residual that can hold another
    // standard-size chunk is valuable.
    let chunks = r / 10;
    score -= (chunks as f64) * 1.5;

    // Lookahead coupling: reward if next item fits the post-residual
    // (pairing bonus), penalize if it almost fits but not quite.
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 8.0;
            // extra harmonic reward if residual is a near-multiple class
            if r % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else if next_item_size <= r + 10 {
            score += 6.0; // tease: next item just misses, dead space risk
        }
    }

    // Best-fit tightening: smaller post residual generally better,
    // amplified when competition for bins is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * (0.4 + 0.6 * progress) * 0.5;

    // Last-chance bin: strongly favor using the only fitting bin
    // rather than opening a new one, unless residual is huge waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open
    // bins would leave very poor fits (large post_residual) late in stream.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if post_residual as f64 > item_size as f64 * 1.2 || pressure < 0.15 {
            score -= 10.0 + 8.0 * (1.0 - pressure);
        } else {
            score += 15.0; // prefer reusing open bins normally
        }
    }

    // Penalize scattering when many bins are open: prefer concentrating.
    score += (open_bins_count as f64).sqrt() * 0.8 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize gaps that no future item can plausibly use.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        score += 500.0; // unusable sliver
    }

    // Penalize mid-range dead gaps: residuals in (0, 10] can only fit tiny items,
    // making them low-utility dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the post residual,
    // this placement enables a perfect chain — reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin anyway; leftover is more likely dead space.
        score += 5.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins (especially tight fits) rather than spreading out.
    let open_pressure = open_bins_count as f64 / 10.0;
    if bin_residual != bin_capacity {
        // Existing bin: mild reward scaled by how full the bin already is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * open_pressure * 6.0;
    } else {
        // New-bin candidate: penalize more heavily when many bins are already open.
        score += 25.0 + open_pressure * 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (i.e., it's the fullest), it is the best consolidation target.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f).min(50.0) * 0.6;
    }

    // Late in the stream, tighten up: avoid leaving any residual that smaller
    // future items could have used more efficiently.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this placement is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves slack proportional to mismatch.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.5 * slack;
        } else {
            // Next item cannot use this bin's remaining space: penalize
            // proportionally to how much dead space we would strand.
            score += 0.4 * (post_residual as f64);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving a residual near the mean keeps the bin pool homogeneous
    // (good for future matching); extreme outliers are penalized.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits the item, using it
    // avoids opening a new bin — reward, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Prefer using
    // open bins unless the fit here is very poor (large post_residual).
    if bin_residual == bin_capacity {
        // Neutral base for new bin, but discourage opening when open bins
        // offer decent fits (post_residual small relative to capacity).
        score += 10.0;
        if item_size as f64 <= 0.5 * bin_capacity as f64 {
            score += 15.0; // small items shouldn't open fresh bins
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // a fresh bin can host a 2-item chain
        }
    }

    // Early in the stream, keep bins more uniform; late, prioritize tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual more aggressively when it is small.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness * tightness;

    // Penalize post_residual that cannot fit the next item (dead space risk),
    // but if it CAN fit next item, reward the bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * (next_item_size as f64);
        } else if post_residual > 0 {
            let waste = post_residual as f64;
            score += 0.6 * waste + (next_item_size as f64 - waste) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mildly penalize to keep options open, prefer fullest bin.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins with residual below mean (fuller bins) to consolidate.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.5 * dev;

    // Time horizon: early in stream, be more conservative (penalize low post_residual
    // less, since future items may use it); late in stream, squeeze bins hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening new bins when many open bins exist with room.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 6.0 + pressure * 0.8;
        // But if this is a huge item and residuals are all small, opening is fine.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Small post_residual bonus: residual below typical small item size is near-waste anyway.
    if post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic reward for tight fits (small post_residual).
    let mut score = pr as f64 + 40.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling: as the stream progresses, tightness matters more.
    score *= 1.0 + 1.5 * progress * (1.0 - norm_pr);

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let dead_zone = (25.0 - pr).max(0.0) / 25.0;
    score += 30.0 * dead_zone * dead_zone * (0.5 + progress);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (1.0 - progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * (1.0 - gap);
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly penalize early, but allow late in stream or
    // when this bin would leave a very awkward residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let awkward = ((mean_residual - pr) / cap).abs();
        score += 20.0 * (1.0 - progress) * (1.0 - progress)
            + 8.0 * (open_bins_count as f64).ln().max(0.0)
            - 10.0 * awkward;
    } else {
        // Slight preference for bins deviating from the mean residual (diversity).
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score -= 3.0 * dev * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on "usable"
    // classes (multiples of common small item sizes) are more valuable.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else {
        // Dead-space penalty: residual too small for the smallest item (1..=10
        // typical; assume min item size 10 as baseline, but graded by class).
        if pr < 10 {
            score += 60.0; // unusable sliver
        } else {
            // Reward residuals that remain in "harmonic" classes: divisible by
            // 10, 20, 25, 50 -> likely to host future items exactly.
            let mut harmony = 0.0;
            if pr % 10 == 0 { harmony += 8.0; }
            if pr % 20 == 0 { harmony += 4.0; }
            if pr % 25 == 0 { harmony += 4.0; }
            if pr % 50 == 0 { harmony += 6.0; }
            score -= harmony;

            // Integer-division thresholds on residual: large residuals are
            // flexible; penalize mid-range "awkward" residuals slightly more
            // than very large ones.
            let q = pr / 25; // 0..4
            score -= q as f64 * 3.0;
        }
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if pr >= next_item_size {
            score -= 6.0; // next item still fits here
        } else {
            score += 5.0; // next item forces another bin anyway
        }
        // Harmonic class match between next item and post residual.
        if pr >= next_item_size && (pr % next_item_size.max(1)) == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if pr >= 10 { score -= 10.0; }
    }

    // New-bin candidate handling: an empty bin has max residual; make it
    // attractive only when current placement would create bad dead space or
    // the stream is early (plenty of future items to fill it).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        score += 45.0 - 30.0 * (1.0 - progress);
        if pr < 10 { score -= 30.0; } // rescue dead-space placements with a fresh bin
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference to keep the number of open bins bounded.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 10) are pure waste. Penalize them hard.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 40.0;
    }
    // Residuals that cannot fit the lookahead item are also suspect dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 6.0;
    }
    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64);
    score -= tightness * 25.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when this bin is the last chance and fits poorly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure; attractive only if
        // remaining space would be large and clean.
        score += bin_pressure * 8.0;
        score += mean_residual * 0.5;
        if post_residual >= 40 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward using it to avoid a new bin.
        score -= 20.0 + bin_pressure * 2.0;
    }

    // Mild alignment with mean residual: prefer bins whose leftover stays
    // near the average (keeps the pool of usable gaps healthy).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Penalize distance from a perfect two-item fill
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.3;
    }

    // Reward very tight fits (small post_residual) especially when bin is scarce
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize leaving dead space below the smallest plausible item when
    // post_residual is nonzero but unusable relative to mean residual
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64).abs();
        let _ = poor_fit;
        // Make new bin moderately expensive so it is chosen only when
        // open bins would waste a lot of space
        score += 20.0 + mean_residual * 0.1;
        // If next item is large and this item is small, opening fresh bin
        // with big residual is fine
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0;
        }
    }

    // Slight preference to fill bins that are already relatively full
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fits (small dead space) superlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 * (1.0 - post / 10.0);
    }

    // Penalize residuals that are too small to fit the smallest future item
    // (dead space), scaled by how "full" the stream already is.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin; if post residual can't fit next item but is
    // large, mild penalty (wasted potential).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else if post > nxt as u32 as f64 * 0.0 && post_residual > 0 {
            score += 4.0 * (post / cap);
        }
    }

    // Last chance: if this is the only fitting bin, penalize opening a new
    // bin elsewhere by rewarding this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Fragmentation guard: avoid leaving residuals in the awkward 11..30
    // range when many bins are open (hard to reuse later).
    if post_residual >= 11 && post_residual <= 30 && open_bins_count > 4 {
        score += 6.0 * (mean_residual / cap);
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or existing bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 40.0; // base cost of opening a new bin
        score -= 55.0 * item_frac;      // big items justify fresh bins
        score -= 30.0 * fragmentation;  // fragmented state favors new bin
        score -= 20.0 * (1.0 - progress); // early stream: bins are cheap assets
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for fuller bins (best-fit flavor) with time decay.
    score -= 8.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pn = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * pn * pn * (0.5 + progress));

    // Penalize waste that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - post) / cap;
        score += 25.0 * gap * gap * (1.0 + progress);
    }

    // Reward tight fits and last-chance bins
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness * tightness;
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - pn);
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += 0.05 * (open_bins_count as f64) * (post - mean_residual).abs() / cap;

    // Late-stream bonus for filling bins deeply
    score -= 10.0 * progress * pn * (1.0 - pn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (capacity fractions).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Class A: near-perfect fit (residual <= 10% of capacity) -> strong reward.
    if frac <= 0.10 {
        score -= 60.0;
    } else if frac <= 0.25 {
        score -= 25.0;
    } else if frac <= 0.50 {
        score -= 5.0;
    }

    // Integer-division dead-space classes: residual in (0..10] is "waste class".
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0; // unusable sliver
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes
    // (10, 20, 25, 50) are reusable by future items.
    let reusable = (post_residual % 10 == 0 && post_residual >= 10)
        || (post_residual % 25 == 0 && post_residual >= 25)
        || (post_residual % 20 == 0 && post_residual >= 20);
    if reusable {
        score -= 15.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 30.0 - (gap as f64).min(30.0); // closer gap = better
            // Harmonic class of gap
            if gap % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 15.0; // next item cannot reuse this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are
    // fragmented (high mean residual spread) or it's a very tight fit need.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing else fits: must open
        }
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Prefer fuller bins overall: reward choosing bins below mean residual
    // (i.e., bins that are more filled than average).
    let this_residual = bin_residual as f64;
    if this_residual < mean_residual {
        score -= 8.0;
    } else if this_residual > mean_residual {
        score += 4.0;
    }

    // Many open bins: encourage closing them out (favor small residuals).
    score -= (open_bins_count as f64).ln().max(0.0) * (cap - post) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized,
    // mid-range gaps get a quadratic penalty scaled by how "wasted" they are.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space: nothing can ever use it
        } else {
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 12.0 * waste * waste * (bin_capacity as f64);
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Reward tight fits relative to the item itself.
    score -= 0.5 * (item_size as f64) * (1.0 - (post_residual as f64 / bin_residual.max(1) as f64));

    // Open-bin pressure: discourage opening new bins when many bins exist,
    // but allow it when open bin count is low (early stream / consolidation).
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise this item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (concentrate filling into already-low bins).
    score += 0.15 * (mean_residual - bin_residual as f64).abs() * -1.0;

    // Late-stream urgency: pack tighter as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if the next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item closure
        } else if next_item_size < post_residual {
            // partial fit next step: reward proportionally to how much of post_residual gets consumed
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * frac;
            // penalize leaving a sliver that likely becomes dead space
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score += 25.0 * (1.0 - leftover as f64 / 10.0);
            }
        } else {
            // next item cannot fit here: post_residual likely dead space
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin opening unless current bins are nearly full / bad fits
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 / fitting_bins_count as f64 };
        score += 45.0 - 45.0 * pressure;
        // if post_residual after placing here is small, a fresh bin is fine
        if post_residual <= 10 {
            score -= 20.0;
        }
        // late in the stream, avoid spawning bins for small leftovers
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 10.0;
        }
    }

    // Slight preference for fuller bins as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post residual) nonlinearly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let tightness = 1.0 - (post / cap);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that no plausible item (>=1) can exploit well:
    // very small post_residual is great; mid-range residuals are risky.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 5.0;
    } else if post_residual >= 50 {
        score += 8.0; // large leftover: wasteful unless bin was fresh
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here regardless; slight penalty for stranding space
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.05 * (post_residual as f64);
    }

    // New-bin candidate handling: fresh empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing fits are poor (high post_residual elsewhere)
        // or when open bins are already numerous and fragmented.
        let poor_fit_elsewhere = mean_residual / cap;
        score = 25.0 + post - 30.0 * poor_fit_elsewhere;
        // Early in stream, opening bins is cheap and builds flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If item is large, a fresh bin is often the best home.
        score -= 0.1 * (item_size as f64);
        // If next item is also large, fresh bin keeps pairing options open.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Global fragmentation: many open bins with high mean residual -> prefer
    // consolidating into bins below mean residual (denser bins).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 6.0 * dev; // below-mean-residual (fuller) bins get lower score
    }

    // Time horizon: late in stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with non-linear (quadratic) growth.
    let mut score = norm_pr + 0.35 * norm_pr * norm_pr;

    // Smooth polynomial coupling between post-residual and stream progress.
    // Late in the stream, tighter fits matter more; early on, waste is cheaper.
    let coupling = norm_pr * (1.0 + 1.5 * progress * progress) - 0.5 * progress * norm_pr * norm_pr;
    score += 0.8 * coupling;

    // Interaction with mean residual: prefer bins close to the fleet average
    // to keep residuals homogeneous and mergeable.
    let mean_norm = mean_residual / cap;
    score += 0.4 * (norm_pr - mean_norm).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.5 + 0.3 * progress;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = (fitting_bins_count == 0) as i32 as f64
            + ((pr as f64) - item_size as f64).max(0.0) / cap;
        let _ = desperation;
        // Penalize opening a new bin, less so late in the stream.
        score += 3.0 - 1.0 * progress;
        // But if it would be the only fitting option, allow it.
        if fitting_bins_count == 1 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction remaining

    // Integer-division thresholds on post_residual: bins whose residual falls
    // into small "dead zones" are penalized (wasted space unlikely to be reused).
    let dead_zone = post_residual / 10; // classes of 10 units
    score += (dead_zone as f64) * 1.5;

    // Modulo arithmetic: residual that fits common harmonic sizes (divisible by 5 or 10)
    // is more reusable, so reward it.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward scaled by how tight the fit is
        score -= (next_item_size as f64 / (post_residual + 1.0)) * 10.0;
    } else if next_item_size > 0 {
        // next item does NOT fit in this residual: penalize proportionally to
        // how close the residual is to the next item (near-miss dead space)
        let gap = (next_item_size - post_residual) as f64;
        if gap < 20.0 {
            score += gap * 1.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins that are more filled (smaller residual)
        score += (frac - 0.5) * 10.0;
    }

    // Progression: early in stream, be pickier about residual quality;
    // late in stream, just pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a well-used bin; reward filling it further.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // New-bin candidate: only attractive when item is huge or nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening a new bin unless the item is large relative to capacity
        let size_frac = item_size as f64 / cap;
        score += 40.0 - 30.0 * size_frac;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 40.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 120.0;
    }
    // Small but usable gaps (10..=20) get a mild penalty relative to baseline.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward fitting into an existing bin when alternatives are scarce.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: more open bins -> favor reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // New-bin candidate: prefer it only when the fit is poor or item is large.
    if bin_residual == bin_capacity {
        // Base preference for existing bins.
        score += 25.0;
        // Large items open bins more readily; small items should reuse bins.
        if item_size > 60 {
            score -= 20.0;
        }
        if post_residual < 10 {
            score -= 45.0;
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        if progress > 0.7 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits the post-residual well, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave another dead gap, penalize.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 25.0;
    }

    // Deviation from mean residual: bins far below mean are more "wasted".
    score += (mean_residual - bin_residual as f64).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Reward tight fits relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins could fit, unless residual is large
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0 - 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later
    // (items are 1..=100, so residual < ~10 is nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting space.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // When many bins are open, prefer consolidating into existing bins
    // rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few items remain or many bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * open_bins_count as f64 / (open_bins_count as f64 + 4.0)
            + 15.0 * progress;
    } else {
        // Reward using existing bins, scaled by how full they already are.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier; using it normalizes the bin population.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Late in the stream, be greedier: minimize post residual harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.0 + progress * post_residual as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let tight = (item_size as f64) / (bin_residual as f64).max(1.0);

    let mut score = pr;

    // Non-linear progress coupling: early stream tolerates loose fits,
    // late stream rewards tight packing (smooth polynomial in t).
    let progress_weight = 3.0 * t * t + 0.5 * t;
    score -= progress_weight * 12.0 * tight * fill;

    // Smooth quadratic penalty on wasted residual, modulated by stream position.
    let waste = pr / cap;
    score += (1.0 + 2.0 * t) * waste * waste * 20.0;

    // Reward near-perfect fits with smooth exponential-like polynomial term.
    score -= 15.0 * (1.0 - waste).powi(6);

    // Lookahead coupling: penalize leaving residual too small for next item,
    // reward residuals that still fit the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 3.0 * (nx - pr) / cap * (1.0 + t);
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * t;
    }

    // Crowding effect: with many open bins, mildly favor consolidation.
    let crowd = (open_bins_count as f64).ln();
    score += 1.5 * crowd * waste;

    // Mean residual alignment: prefer bins close to mean (smooth coupling).
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * t - 5.0 * (1.0 - fill);
        if fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "band" of dead space we land in.
    // Classes of width 10: class 0 = perfect-ish fit (0..10), class 3 = half-bin waste, etc.
    let post_class = post_residual / 10;
    let next_class = if next_item_size == 0 { 99 } else { next_item_size / 10 };

    // Reward when next item can nest into the post residual (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Strong reward for tight chaining; the tighter, the better.
        score -= 30.0 - 2.0 * slack_after_next as f64;
        // Extra bonus if the chain leaves a harmonic class boundary (multiple of 10),
        // which keeps future modularity high.
        if slack_after_next % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's remainder: penalize proportionally to waste.
        score += 0.5 * (next_item_size.min(post_residual + 1)) as f64;
    }

    // Penalize landing in the "dead zone" classes: residuals of 1..=9 are nearly unusable
    // (items are >= 1 but typical sizes are larger); residuals just under half-capacity
    // are awkward too.
    match post_class {
        0 => score -= 5.0,               // tiny residual: near-perfect fit, good
        1 => score -= 2.0,               // small but usable
        2 | 3 => score -= 4.0,           // sweet spot: room for medium items
        4 | 5 => score += 3.0,           // half-bin waste zone
        6 | 7 => score += 6.0,           // large leftover, likely dead space
        _ => {}
    }

    // Modulo-5 harmonic resonance: residuals divisible by 5 pair well with the
    // item-size lattice, slightly favor them.
    if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post residual would be terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 12.0 + 0.1 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate (empty bin): only attractive when current bins are crowded
    // or the fit here would be very poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        // If open bins are mostly empty, discourage opening another one.
        score += 25.0 * (1.0 - crowding);
        // But if this item alone leaves a huge remainder in an open bin anyway,
        // a fresh bin is fine.
        if post_residual >= 50 {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten up: prefer filling existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual >= 1 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 40.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual was large (using big bins for big items leaves usable space elsewhere).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when the fit is poor or no good gap exists.
    if bin_residual == bin_capacity {
        // Base penalty keeps new bins from winning unless open-bin fits are bad.
        score += 30.0;
        // If the item would leave a tiny dead gap in every existing bin, a fresh bin is fine.
        if post_residual >= 20 && post_residual <= 40 {
            score -= 25.0;
        }
        // Few open bins -> opening a new one is cheap.
        if open_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    }
    if next_item_size > 0 && post_residual > 0 && next_item_size < post_residual {
        score -= (next_item_size as f64 / post_residual as f64) * 15.0;
    }

    // Mean residual coupling: if this bin is tighter than average, prefer it.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with mild non-linearity.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // 2-step lookahead: perfect match with next item is excellent.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 60.0; // exact 2-step chain: fill now, fill next
        } else if post_residual as u32 > next_item_size {
            // next item can also fit here: good, proportional bonus
            score -= 8.0 + 12.0 * (nxt / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 6.0 + 0.25 * (nxt - pr).max(0.0);
        }
    }

    // Relative to mean residual: bins tighter than average are good targets.
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current leftovers are large relative to the item and next item,
    // or when many bins are open and this one is a poor fit.
    if bin_residual == bin_capacity {
        let poor_fit = pr as f64 > next_item_size as f64 && pr > 45.0;
        if next_item_size == 0 {
            score += 20.0; // last item: prefer existing bins
        } else if poor_fit && fitting_bins_count > 0 {
            score -= 5.0; // allow opening when fit is bad
        } else {
            score += 15.0; // default: discourage opening new bins
        }
        // Early in stream, consolidating is better.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Prefer more-filled bins when several bins fit similarly.
    if open_bins_count > 1 {
        score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // especially when the pair packs well (post_residual == next_item_size).
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin, relaxed late in the stream or when
        // existing residuals are large and fragmented.
        score += 20.0 + 15.0 * (1.0 - progress);
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        if crowded > 0.5 {
            score += 5.0;
        }
    } else {
        // Slight preference for bins whose residual deviates below the mean
        // (consolidate small leftovers rather than spreading across bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Prefer using older/more-filled bins: penalize bins with large residuals
    // relative to capacity when the stream is far along.
    let late = step_index as f64 / (total_items.max(1) as f64);
    score += late * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late in the stream, tight fits matter more.
    let w = 1.0 + 3.0 * progress * progress;
    score += w * (post / cap) * (post / cap) * cap * 0.5;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_ratio = 1.0 - post / cap;
    score -= 8.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize residuals that are unusable relative to the lookahead item:
    // smooth interaction between post_residual and next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        let usable = 1.0 / (1.0 + (gap / (cap * 0.25)) * (gap / (cap * 0.25)));
        score -= 6.0 * usable;
        // penalize leaving a residual slightly below the next item (dead space)
        let dead = ((nx - post) / cap).max(0.0);
        score += 10.0 * dead * dead * cap;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: base penalty, relaxed when many bins are open and
    // residuals are large (fragmented state favors consolidation into new bin).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0);
        score = cap * 1.5 - 20.0 * frag * frag - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // keep last-chance advantage over new bin
        score -= 5.0;
    }

    // Mild coupling with open bins count: more open bins -> prefer filling existing.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "dead zones" (1..=9) are penalized — that space is nearly unusable.
    if post_residual > 0 && post_residual <= 9 {
        score += 12.0 - post_residual as f64; // smaller dead space is worse
    }

    // Reward perfect / near-perfect fits heavily.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Modulo-10 harmonic classes: residuals in "round" classes (multiples of 10)
    // align with typical item sizes, so favor bins whose post_residual is a
    // multiple of 10 or a multiple of 25 (quarter capacity).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post_residual, this bin is a great chain candidate.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left <= 9 {
                score -= 8.0; // chain ends in tiny dead space, still good
            } else if nxt_left % 10 == 0 {
                score -= 5.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot use this bin's leftover; slight penalty for
            // leaving residual in awkward classes.
            if post_residual % 10 != 0 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 15 {
            score -= 10.0;
        }
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // current fit is bad or there are no fitting bins; otherwise penalize.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // penalize proportional to how good existing fits are
            score += 18.0 + mean_residual * 0.1;
            if post_residual as f64 > mean_residual {
                score += 8.0;
            }
        }
    }

    // Prefer filling bins with large residual when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Slight preference for consolidating when many bins are open.
    if open_bins_count > 4 {
        score -= 1.0;
    }

    // Early stream: be a bit more willing to spread (open bins), late stream:
    // consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (smaller than the minimum plausible item size) are heavily penalized.
    let min_item = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 500.0; // perfect fit was actually possible, this is dead space
    }

    // Penalize small-but-nonzero gaps that no future item (>= min size) can use,
    // with severity increasing as the gap shrinks toward zero.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 20.0 {
            score += (20.0 - gap) * 8.0;
        } else if gap < 35.0 {
            score += (35.0 - gap) * 3.0;
        }
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 40.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over.min(30.0) * 1.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins,
    // making the fresh empty bin (bin_residual == bin_capacity) less attractive
    // unless the fit there is genuinely better.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins.
        score += 25.0 + open_bins_count as f64 * 6.0;
        // But if current bin would leave a bad gap, new bin becomes competitive:
        if post_residual > 0 && (post_residual as f64) < 25.0 {
            score -= 20.0;
        }
    } else {
        // Existing bin: small consolidation reward scaled by open bins count.
        score -= open_bins_count.min(10) as f64 * 1.5;
    }

    // Slight preference for bins already below mean residual (filling emptier bins
    // balances residuals and preserves tight bins for tight items).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Late-stream adjustment: near the end, minimize total footprint aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near match: next item still fits tightly after this placement
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item would not fit here: penalize proportionally to wasted lookahead
    else if next_item_size > 0 {
        score += 0.5 * (next_item_size as f64).min(post_residual as f64);
    }

    // Penalize dead space relative to the mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when the current bin would leave
    // large unusable residue or when no tight lookahead match exists
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0; // discourage new bin when open bin has a good 2-step fit
        }
        if fitting_bins_count == 1 {
            score += 30.0; // strongly discourage new bin when it's the only fitting bin
        }
    }

    // Slight pressure toward compactness as stream progresses
    score += 0.1 * (post_residual as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the closer post_residual is to zero, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize creating small unusable dead space (residual below typical small item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - next_tight / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item cannot follow in this bin: mild penalty if we strand space.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize bins with residual far from mean (keeps bin residuals homogeneous,
    // preserving flexibility for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in the stream, be more conservative about opening new bins;
    // late in the stream, prefer consolidating into existing bins less aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: open a new bin when existing fits are poor or many bins
        // already open and current fit wastes a lot.
        let waste = post_residual as f64;
        score += 15.0 - 0.15 * (open_bins_count as f64);
        score += 0.5 * waste * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // next item needs a fresh bin anyway
        }
    } else {
        // Existing bin: slight preference to fill bins with more content as stream progresses.
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * t * t) + 3.0 * norm_pr * norm_pr * (1.0 - t);

    // Penalize large dead space more as stream progresses (less time to recover it)
    score += 8.0 * norm_pr * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits (small post_residual) especially when few bins fit the item
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 4.0 * last_chance * (1.0 - norm_pr);

    // Lookahead coupling: reward if next item fits well into the resulting residual
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 5.0 * (1.0 - gap) * (1.0 - t * 0.5);
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty for wasting capacity
        score += 1.5 * norm_item * (1.0 - norm_pr);
    }

    // Slight preference to fill already-open bins vs opening new ones, scaled by open count
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 2.0 + 0.05 * open_bins_count as f64 + 6.0 * norm_item;
    } else {
        score -= 0.5 * (bin_residual as f64 - pr) / cap;
    }

    // Mild pull toward bins with residual near mean residual (keeps bin states balanced)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity fractions are "good" states.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional position of post_residual within capacity
    let frac = pr / cap;

    // Penalize post-residuals in "dead zones": too small for typical items (1..100).
    // A residual below ~10 is nearly unusable dead space.
    if pr > 0 {
        if pr < 10 {
            score += 25.0; // unusable sliver
        } else if pr < 20 {
            score += 8.0;
        } else if pr < 35 {
            score += 2.0;
        } else {
            score -= 3.0; // roomy residual is good
        }
    } else {
        // Perfect closure is ideal
        score -= 40.0;
    }

    // Modulo-class logic on post_residual: residuals congruent to values that pair
    // well with common item sizes (multiples of 5/10 classes) are favored.
    let mod10 = post_residual % 10;
    score -= match mod10 {
        0 => 6.0,           // clean multiple of 10
        5 => 3.0,           // half class
        _ => 0.0,
    };

    // Integer-division threshold: how many "average items" still fit
    let avg_item = 40.0f64;
    let fits_k = (pr / avg_item).floor();
    score -= fits_k * 2.0;

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // partial harmony: residual class of (post_residual - next_item_size)
            let rem = post_residual - next_item_size;
            if rem < 10 {
                score += 5.0; // next placement would create sliver
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; mild penalty unless residual still large
            if pr >= 50 {
                score += 1.0;
            } else {
                score += 6.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post-residual would be a tiny sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr >= 10 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are already open
        // or stream is early (future flexibility valuable).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress;
        // If no open bin can fit, new bin is fine
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tighten loose bins),
    // keep high-residual bins available for large future items.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 5.0;

    // Exact-fill bonus scaled by item size
    if post_residual == 0 {
        score -= item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else {
        // Moderate gaps that can't fit the next item are also bad.
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 15.0;
        }
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    } else {
        score -= 50.0; // perfect fit
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 20.0 + 8.0 * open_bins_count as f64;
        // But if no existing bin fits well, allow new bin sometimes.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        score -= 5.0 * open_bins_count as f64 / (open_bins_count as f64 + 3.0);
    }

    // Prefer bins whose residual is close to the mean (keeps balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Lookahead: if next item fits in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Early stream: be more liberal with opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits leaving small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // penalize slack beyond the exact match, but still reward fitting the next item
        score -= 25.0 - slack * 0.35;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to how badly it misses
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.5;
    }

    // Penalize tiny dead space that nothing can use (min item size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins whose residual is below mean (tight bins get used first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
    }

    // Late in stream: be more conservative, keep bins tight
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward leaving very little slack.
    let tight = (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score += tight * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tightness = next_item_size as f64 / post_residual as f64;
        score -= 10.0 + 10.0 * lookahead_tightness;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is usually wasteful, but allow it
    // when the item is large relative to capacity and open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).abs()
        } else {
            0.0
        };
        // Penalize opening a bin generally; less so late in the stream or when
        // existing residuals are large (fragmented) and item is big.
        let mut open_penalty = 20.0;
        if fragmentation > 0.5 && item_size > bin_capacity / 2 {
            open_penalty -= 15.0 * (fragmentation - 0.5);
        }
        if progress > 0.8 {
            open_penalty += 10.0 * (progress - 0.8);
        }
        score += open_penalty;
        // A new bin's post-residual slack is unattractive vs. a tight existing fit.
        score += 5.0;
    } else {
        // Mild reward for consolidating into fewer bins when many are open.
        if open_bins_count > 3 {
            score -= 2.0;
        }
        // Prefer bins whose residual is close to the mean (balanced usage),
        // slightly discourage extreme outliers.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack (favor spreading); later, demand tight packing.
    let tightness_weight = 40.0 + 160.0 * progress * progress;
    score += tightness_weight * post_norm * post_norm;

    // Reward filling bins deeply, modulated by progress (quadratic interaction).
    let fill = 1.0 - post_norm;
    score -= (30.0 + 60.0 * progress) * fill * fill * item_norm;

    // Dead-space penalty: post_residual too small to ever fit another item.
    let min_item = 1.0;
    if post < min_item {
        score -= 0.0; // unusable space is fine only if zero
    }
    let waste = (post - min_item).max(0.0) / cap;
    score += 25.0 * waste * waste * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    } else if fitting_bins_count > 1 {
        // Prefer bins that are more filled relative to the mean residual.
        score += (mean_residual - post) * (0.5 + progress);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let gap = (post - next) / cap;
            score -= 20.0 * (1.0 - gap * gap);
        } else {
            // Next item won't fit here; penalize slightly less as stream ends.
            score += 10.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: an empty bin (bin_residual == bin_capacity)
    // should only win when no open bin gives a good fit; make empty bins
    // moderately attractive early, expensive later.
    if bin_residual == bin_capacity {
        let open = open_bins_count.max(1) as f64;
        score = 35.0 + 120.0 * progress * progress + 8.0 * (open.sqrt());
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: opening a new bin is correct
        }
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 10.0; // fresh bin is useful for the lookahead too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residues that commonly pair with small
    // items (multiples of 10) are more reusable than odd residues.
    let residue = post_residual % 10;
    let harmonic_penalty = match residue {
        0 => -18.0,
        5 => -6.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => 9.0,
    };
    score += harmonic_penalty;

    // Coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportionally to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // Extra reward if the pair nearly fills the bin
            if post_residual - next_item_size <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize dead space
            score += 8.0;
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize leaving huge residual when few bins are open (encourage consolidation)
    if open_bins_count > 2 {
        let mean_gap = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * mean_gap;
    }

    // New-bin candidate: penalize unless existing fits are clearly bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if stream is early and many items remain, a fresh bin is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 10.0;
        }
        // Large items relative to capacity favor fresh bins
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Small structural bonus: fractional-capacity thresholds
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 4.0; // bin nearly full: good
    } else if post_residual > bin_capacity - quarter {
        score += 4.0; // bin barely used: bad placement
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Dead space in the awkward 11..=25 band is half-wasted in practice.
    if post_residual >= 11 && post_residual <= 25 {
        score += 12.0;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to the bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the gap: penalize proportionally to waste.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good; encourage filling existing bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.05 * bin_pressure * (1.0 - fit_ratio);

    // Deviation from mean residual: bins far below mean residual are the
    // "leftover" bins; using them up is good (they are hard to fill later).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: make opening a new bin mildly unattractive by default
    // so it only wins when all open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, keep consolidating into open bins.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // next item can also go here: chain reward scaled by leftover
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual to mean residual: avoid making bin worse than average
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to use it instead of opening new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in open bins
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 0.6 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * bin_capacity as f64;

    // Exact fill bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead space penalty: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // wasted capacity if next item can't use the leftover
            score += 6.0;
        }
        // bonus if post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowd penalty: when many bins are open, prefer consolidation
    let openness = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 8.0 * openness;

    // Prefer bins with residual far from mean residual (avoid fragmenting typical space)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, keep bins roomy; late, pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * fit_ratio * 10.0;
    score -= progress * (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // opening fresh bin is attractive when mean residual is fragmented
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    let mut score = post;

    // Non-linear dead-space penalty: small residuals are increasingly bad.
    score += 60.0 * (1.0 - pr).powi(6);

    // Smooth interaction: tight fits rewarded more as stream progresses.
    let fit_bonus = (1.0 - pr) * (0.5 + progress);
    score -= 30.0 * fit_bonus;

    // Perfect-fit term (quadratic coupling with progress).
    score -= 45.0 * (1.0 - pr * pr) * (0.3 + 0.7 * progress);

    // Penalize bins whose residual deviates from mean (fragmentation control),
    // smoothly scaled by number of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr) * (1.0 - progress);
    }

    // Lookahead: if next item could fit into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 20.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Slight bias against opening new bins early in the stream.
    score += (bin_residual == bin_capacity) as i32 as f64 * (15.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (best-fit core).
    score += post_residual as f64 * 0.5;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes are more reusable; heavily fragmented residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        // Penalize residuals in awkward classes (small prime-ish leftovers).
        let class = pr % 10;
        score += match class {
            0 => -6.0,   // round residual: highly reusable
            5 => -3.0,   // half-class
            2 | 4 | 6 | 8 => -1.5, // even classes
            _ => 2.0,    // odd leftover: harder to fill
        };
        // Very small unusable slivers are wasted capacity.
        if pr < 10 {
            score += 8.0;
        }
        // Integer-division threshold: residual that can host a mid/large item is valuable.
        if pr >= 50 { score -= 5.0; }
        else if pr >= 30 { score -= 2.0; }
    } else {
        // Perfect fill: strongly reward closing the bin.
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving space that fits the next item exactly well.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap < 10 {
                score -= 7.0; // next item nearly fills this bin's remainder
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here: residual likely to persist; mild penalty.
            score += 1.5;
        }
    } else {
        // Last item: just close tightly.
        score -= 10.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { (mean_residual - post_residual as f64).abs() } else { 0.0 };
        score += 14.0; // default cost of a fresh bin
        if item_size >= 60 { score -= 10.0; }        // large items deserve fresh space
        if mean_residual > 40.0 && open_bins_count > 2 { score -= 6.0; } // open bins too full anyway
        if fragmentation > 25.0 { score -= 4.0; }
        if progress > 0.9 { score -= 2.0; }          // end of stream: fewer bins matter
    }

    // Slight preference for bins whose residual is above the mean (keep low
    // residuals for tighter future fits).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Mild pressure against bin sprawl.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is more tolerable if the next item can use it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 12.0; // gap too small for lookahead item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins when pressure is low,
    // reward it when open bins are congested (high mean residual / many bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 45.0 - 25.0 * congestion - 10.0 * progress;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // new bin useful for larger lookahead item
        }
    }

    // Open-bins pressure: mild reward for keeping bins few.
    score += (open_bins_count as f64).sqrt() * 0.5;

    // Prefer filling bins that are already partially used (tighter packing).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled slightly
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward bins whose post_residual exactly or nearly fits next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: big reward
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare against mean residual: placing into a bin with residual below mean
    // consolidates space (good); above mean spreads space (bad).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving tiny dead space (< 10, unusable for min item size 1... but
    // small fragments are still useful; penalize only when next item can't use it)
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    // Give the empty bin a moderate penalty so it's chosen only when open-bin scores are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But late in the stream, opening fresh bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Early stream: slight preference for opening bins to build diversity
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual small relative to capacity.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fit_quality * fit_quality;

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual < 10 {
        score += 25.0; // perfect fill bonus instead
    } else if post_residual < item_size.min(30) {
        score += 6.0; // awkward sliver
    }

    // Lookahead: strongly favor bins whose residual fits the next item too.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.25 * (next_item_size as f64);
        } else if bin_residual >= item_size + next_item_size {
            score -= 3.0; // bin could take both if packed in order
        } else {
            score += 4.0; // next item won't fit here after placement
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual.max(0.0) / bin_capacity as f64;
        score += 20.0 - 8.0 * crowded.min(2.5);
        // Early in stream, opening bins is fine; late in stream, prefer filling.
        score += 10.0 * (1.0 - t);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // new bin can host both items
        }
    }

    // Global pressure: when mean residual is low, conserve open space; when high, consolidate.
    score += 0.05 * mean_residual * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth polynomial interaction: penalize large residuals more as stream progresses
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep-like
    score += t * 30.0 * norm_pr * norm_pr * cap;

    // Early phase: reward tight fits (small post_residual) to consolidate
    let early = (1.0 - progress) * (1.0 - progress);
    score -= early * 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual of open bins
    let dead = (pr - mean_residual) / cap;
    score += 10.0 * dead * dead * cap;

    // Lookahead coupling: reward leaving space for next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr as f64 - next_item_size as f64).abs();
        let fit_next = (pr >= next_item_size as f64) as i32 as f64;
        score -= 8.0 * fit_next * (1.0 - gap / cap) * (1.0 - gap / cap);
        score += 4.0 * (gap / cap) * (gap / cap) * cap;
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage closing bins out)
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize opening a fresh bin unless residuals are large
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        score += 15.0 + 40.0 * avg_fill * avg_fill * (1.0 - progress);
        score -= 20.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover space: quantize post_residual into
    // capacity-fraction buckets. Small post_residual classes are "good"
    // (tight packing), large ones waste space.
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i64; // 0..8 harmonic class
    score += class as f64 * 4.0;

    // Non-linear penalty for mid-range waste (dead space that few items fit).
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill: heavily reward
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 6.0; // awkward dead zone
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or well; penalize if the leftover can never host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0; // perfect chain placement
            } else {
                score -= (10.0 - slack.min(10) as f64) * 1.5;
            }
        } else {
            score += 8.0; // leftover unusable for the known future item
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no open
    // bin offers a decent fit, or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // Penalize new bins when existing residual capacity is healthy.
        score += 15.0 + pressure * 20.0;
        // But if the item is large relative to typical residual, allow it:
        let tight_fit = (item_size as f64) / cap;
        if tight_fit > 0.6 {
            score -= 18.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins already: discourage one more.
        score += open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: prefer bins that are tighter than average.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Modulo harmonic bonus: leftovers that are multiples of common item
    // sizes (10/20/25/50) are more reusable.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 { score -= 5.0; }
    if pr % 25 == 0 && pr > 0 { score -= 3.0; }
    if pr % 50 == 0 && pr > 0 { score -= 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1, but
    // realistically gaps < ~10 are near-unusable) get a heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gap unusable for the lookahead item: strong penalty, scaled by gap smallness.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (exact fill is perfect).
    if post_residual == 0 {
        score -= 80.0;
    } else {
        score -= 40.0 / post_residual as f64;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> be lenient.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins whose residual is already below average (consolidating waste).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many fitting bins means spreading is cheap anyway; few means reuse).
    if bin_residual == bin_capacity {
        score += 35.0 + (fitting_bins_count as f64) * 6.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer bins whose post residual matches the next item exactly.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        // Perfect lookahead match: strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize post residuals that leave next item unplaceable here.
            if (post_residual as u32) < next_item_size {
                score += 12.0 + diff * 0.25;
            } else {
                // Reward tight-but-fitting residuals for next item.
                score -= 18.0 * (1.0 - diff / bin_capacity as f64);
            }
        }
    }

    // Reward leaving small unusable dead space only if it's truly dead (< min item 10).
    if post_residual < 10 {
        score -= 8.0;
    } else {
        // Penalize medium dead space (10..30) that is hard to fill later.
        if post_residual < 30 {
            score += (30.0 - post_residual as f64) * 0.4;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it wins only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if next item is large and current item is small, opening fresh is attractive.
        if next_item_size > 60 && item_size < 30 {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual <= 80 {
        score -= 4.0; // residual in reusable range
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist: prefer the tightest one.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty for blocking space.
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a bin is usually worse unless
    // current residuals are fragmented or this is a poor-fit situation.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 18.0 - 8.0 * progress;
        // If existing bins are fragmented (high mean residual spread), opening is cheaper.
        let spread = (mean_residual - bin_residual as f64).abs();
        open_cost -= (spread / bin_capacity as f64) * 6.0;
        // If many bins compete, opening a fresh one is less attractive.
        open_cost += (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += open_cost.max(0.0);
    } else {
        // Reusing an open bin is generally good; small bonus scaled by occupancy.
        let occupancy = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * occupancy;
    }

    // Global pressure: when mean residual is low, conserve open bins harder.
    score += (mean_residual / bin_capacity as f64) * 4.0;

    // Mild time-horizon shaping: early on, be greedy for tight fits; later,
    // consolidate to reduce open-bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, dead space matters more
    score *= 1.0 + 0.8 * progress * (1.0 - norm_pr);

    // Penalize bins whose residual deviates from mean residual (smooth coupling)
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: reward leaving room for the next item smoothly
    let next = next_item_size as f64;
    if next > 0.0 {
        let fit_quality = (pr - next) / cap;
        if fit_quality >= 0.0 {
            score -= 3.0 * fit_quality * (1.0 - fit_quality);
        } else {
            score += 2.0 * (-fit_quality) * cap / 100.0;
        }
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 5.0 + 2.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: keep neutral-ish baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score = 40.0 + 30.0 * progress - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "usable" residue class (multiples of 10) are preferred.
    let post_class = (post_residual % 10) as f64;
    score += post_class * 2.5;

    // Perfect fit is best.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size.
        score += 60.0;
    }

    // Coupling with the next item: if the next item fits exactly in the
    // post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Next item won't fit here; penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let tight_fit = post_residual < 20 && next_item_size <= post_residual;
        if tight_fit {
            score -= 400.0;
        } else {
            score += 120.0 + (open_bins_count as f64).sqrt() * 10.0;
        }
    }

    // Prefer filling bins that are already below mean residual (tight bins).
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 25.0;

    // Integer-division threshold: leftover >= 50 keeps a half bin usable.
    if post_residual >= bin_capacity / 2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits: near-perfect packing gets a strong discount.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // If the next item could use the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for next item: penalize proportionally.
        score += (post_residual as f64 / (next_item_size as f64)) * 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 + progress) * 0.6;

    // Prefer bins whose residual deviates favorably from the mean (below mean residual
    // means this bin is already tight; filling it further is good).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Slight penalty so existing bins are preferred unless dead-space costs dominate.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            let leftover = post_residual - next_item_size;
            // Penalize leftover after hypothetically placing next item.
            score += leftover as f64 * 0.35;
            if leftover <= 10 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; dead space risk grows.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 5.0;
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they are bad fits.
        score += 25.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If item is large, a fresh bin is more useful.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Many open bins already: avoid spreading too thin.
        score += open_bins_count as f64 * 1.5;
        // If next item is large too, a fresh bin pairs well.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Slight preference for bins with more slack consumed relative to capacity.
    score += (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits (small post_residual) more strongly over time.
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + t);

    // Penalize large dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual < item_size.max(10) {
        score += 3.0; // awkward small gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate logic: only attractive when current item is large
    // relative to residual or few bins fit the item.
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 15.0; // no open bin fits; must open
        } else {
            score += (1.0 - fill_ratio) * 25.0 + open_bins_count as f64 * 0.5;
            if fill_ratio > 0.6 {
                score -= 10.0; // big item deserves a fresh bin
            }
        }
    }

    // Mild preference to spread load when many open bins have high residual.
    if !is_new_bin && (bin_residual as f64) > mean_residual {
        score -= 1.5;
    } else if !is_new_bin {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: minimize waste after placement
    let mut score = pr;

    // Non-linear coupling: normalized post-residual interacts with stream progress.
    // Later in the stream, compacting residuals matters more (less time to reuse dead space).
    let pr_norm = pr / cap;
    score += (pr_norm * pr_norm) * cap * (0.5 + 0.5 * progress);

    // Reward near-perfect fits smoothly: subtract a bump peaked at pr = 0
    let fit_bonus = (pr / 12.0).exp() * 8.0;
    score -= fit_bonus;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 + gap / cap).recip() * 6.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty scaled by dead space
        score += pr_norm * 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 5.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin, but relax when existing residuals
    // are large (poor fits elsewhere) or late in the stream.
    let new_bin_penalty = 10.0
        - 4.0 * (mean_residual / cap).min(1.0)
        - 3.0 * progress
        - 2.0 * (open_bins_count as f64).ln().max(0.0);
    score += is_new_bin * new_bin_penalty.max(1.0);

    // Mild preference to fill bins with larger residual when many bins are open
    score += 0.05 * (open_bins_count as f64).sqrt() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on leftover space.
    // Leftovers that are "harmonically useful" (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // reward leftovers divisible by small common sizes (they can host future items exactly)
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 30 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // dead-space penalty: tiny unusable gaps
        if pr < 10 { score += 15.0; }
        else if pr < 20 { score += 5.0; }
        // harmonic bucket via integer division thresholds
        let bucket = pr / 25; // 0..4
        score += bucket as f64 * 2.0;
    } else {
        // perfect fit: strongly reward
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // exact or near-exact match with next item is very desirable
            let gap = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap);
            if pr == next_item_size { score -= 10.0; }
        } else {
            // next item cannot use this leftover: mild penalty scaled by leftover size
            score += 0.05 * pr as f64;
        }
    } else {
        // last item: prefer fullest packing
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0;
        // opening new bins early in the stream is cheaper (more future use)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    }

    // Spread-awareness: prefer bins below mean residual when mean is high (balance loads)
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.05 * (mean_residual - resid_f);
    } else {
        score += 0.03 * (resid_f - mean_residual);
    }

    // Congestion: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10.0 - post_residual as f64) * 4.0;
    }

    // Reward tight fits (post_residual near zero) more aggressively.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the post-residual, this placement
    // chains nicely; reward it proportionally to the leftover after both.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step_left = post_residual - next_item_size;
        score -= 8.0 + two_step_left as f64 * 0.15;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual becomes dead space for the known next item.
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: keep the number of active bins in check; the more
    // bins are open, the more we should prefer filling existing ones.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure and stream progress,
        // but offer a clean-slate bonus (full residual) when the item is large
        // relative to typical residuals (poor fit elsewhere).
        score += 20.0 + pressure + (step_index as f64 / total_items.max(1) as f64) * 15.0;
        if item_size as f64 > mean_residual {
            score -= 18.0;
        }
    } else {
        // Filling an existing bin: reward scaled by how much better this bin's
        // residual is than the mean (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= (mean_residual - bin_residual as f64) * 0.3;
        } else {
            score += (bin_residual as f64 - mean_residual) * 0.15;
        }
        // Mild bonus for using existing bins as pressure rises.
        score -= pressure * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or nearly: strong reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack.min(200.0);
            if post_residual == next_item_size {
                score -= 500.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here: penalize wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 50.0;
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 80.0; // fresh bin likely wasted
        }
    }

    // Late stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness * tightness;

    // Perfect fit: exact closure of the bin.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: post residual too small for the smallest plausible item (1..100 range).
    // Residuals below ~10 are likely wasted; penalize proportionally to wasted fraction.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that can host it but only barely (fragmenting).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = post - nxt;
            score -= 12.0 * (1.0 - slack / cap);
            if slack as u32 == 0 {
                score -= 40.0; // next item closes this bin perfectly
            }
        } else {
            // residual can't host next item: mild penalty scaled by gap
            score += 6.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * tightness;
    }

    // New-bin candidate handling: an empty bin has large post residual.
    // Make it attractive only when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows slightly with number of open bins
        // to encourage consolidation when bins are few, but capped.
        let open_cost = 15.0 + 2.0 * (open_bins_count as f64).min(20.0);
        score += open_cost;
        // If the item nearly fills a fresh bin, opening is cheap.
        let fill = item / cap;
        score -= 20.0 * fill * fill;
        // Late in the stream, prefer closing out existing bins; opening is costlier.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Global state coupling: when mean residual across open bins is high (lots of
    // slack available), penalize placements that leave large residuals to push
    // consolidation; when mean residual is low, allow looser fits.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let res_gap = post - mr;
    score += 3.0 * res_gap.signum() * (res_gap.abs() / cap).min(1.0) * (1.0 - mr / cap);

    // Congestion: many open bins -> reward filling existing bins harder.
    if open_bins_count > 4 {
        score -= 2.0 * ((open_bins_count as f64) - 4.0).min(10.0) * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let next_fit = (next_item_size as f64 / cap).clamp(0.0, 1.0);

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, tighten more.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * 40.0 * norm_pr * norm_pr;

    // Reward snug fits (small post_residual) more as stream advances.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 25.0 * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item (smooth gate).
    let unusable = ((pr as f64) - (next_item_size as f64)).max(0.0) / cap;
    score += 18.0 * unusable * unusable * (next_item_size > 0) as i32 as f64;

    // Reward bins whose residual still accommodates the next item.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 10.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - fit_ratio);
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0) * progress;

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 60.0 * fit_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a "useful"
    // residue class (multiples of common small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 12.0,
            5 => 6.0,
            2 | 4 | 6 | 8 => 3.0,
            _ => 0.0,
        };
        score -= class_bonus;
    } else {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Integer-division threshold: post_residual bucketed by quarters of capacity.
    let quarter = (cap / 4.0) as u32;
    if pr >= 3 * quarter {
        score -= 8.0; // large leftover remains flexible
    } else if pr < quarter && pr > 0 {
        score += 10.0; // tiny dead space, penalize
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 15.0 - 0.15 * slack;
        if (pr - next_item_size) % 10 == 0 {
            score -= 5.0; // harmonic chain fit
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 6.0; // next item won't reuse this bin
    }

    // Last-chance bin: strongly prefer to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap.max(1.0));
        let base = 45.0 + 20.0 * progress + 2.0 * pressure;
        // If item leaves a harmonic residual in a fresh bin, soften the penalty.
        let fresh_class = match (bin_capacity - item_size) % 10 {
            0 => 18.0,
            5 => 9.0,
            _ => 0.0,
        };
        score = base - fresh_class;
        // Prefer new bin only if existing bins leave truly bad residue.
        if mean_residual > (item_size as f64) * 1.6 {
            score += 30.0;
        }
    }

    // Mild late-stream tightening: reduce waste as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness bonus: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor filling
    // existing bins (hurts the new-bin candidate which has full residual).
    score += (open_bins_count as f64) * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // If next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: dead space locked in
        score += 10.0;
    }

    // Mean residual coupling: placing into a bin far below the mean residual
    // (i.e., a large-residual bin) is mildly favored to consolidate space.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: opening a new bin should only win when existing bins
    // would create bad dead space. Make the empty bin moderately attractive.
    if bin_residual == bin_capacity {
        score += 5.0;
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward exact or near-exact fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for typical items (unusable gap).
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 60.0; // tiny unusable sliver
        }
        // 2-step lookahead: if the next item fits exactly in post_residual,
        // this bin is a great match for a chain of placements.
        if next_item_size > 0 {
            let next_f = next_item_size as f64;
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size <= post_residual {
                // next fits but not perfectly: mild reward proportional to tightness
                let tight = 1.0 - ((post_residual - next_item_size) as f64) / 100.0;
                score -= 150.0 * tight;
            } else {
                // next item won't fit here after placement: penalize more if
                // this bin would otherwise be left as a poor candidate.
                score += 40.0 * (next_f / 100.0);
            }
        }

        // Compare post_residual against mean residual: prefer bins whose
        // remaining space is below-average (consolidating fullness).
        let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        if mean > 0.0 {
            let diff = dead - mean;
            score += 0.5 * diff;
        }

        // Last-chance bin: if this is the only bin that fits, strongly favor
        // using it rather than opening a new bin (unless fit is terrible).
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 120.0;
        }

        // New-bin candidate: make empty bins less attractive than decent fits,
        // but attractive when no good open-bin fit exists.
        if bin_residual == bin_capacity {
            score += 90.0;
        }

        // Late in the stream, tighten packing: reward tighter fills more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 0.3 * progress * (bin_capacity - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: reward tight fills (subtraction grows as more space is consumed)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Lookahead (k=2): strong reward if the next item can also fit here
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // extra coupling: perfect chain fit
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // penalize leaving dead space the next item cannot use
        score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.08;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Near-perfect fill bonus
    if post_residual < 10 && !is_new_bin {
        score -= 6.0;
    }

    // Penalize large unusable leftovers
    if post_residual > 40 && !is_new_bin {
        score += (post_residual - 40) as f64 * 0.25;
    }

    // New-bin candidate: penalize so it only wins when open bins fit poorly;
    // penalty relaxes slightly late in the stream (horizon effect)
    if is_new_bin {
        score += 30.0 - progress * 12.0;
        // if the next item is large, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Global state coupling: prefer bins deviating favorably from mean residual
    score += (mean_residual - post_residual as f64) * 0.06;

    // Mild pressure to consolidate into fewer bins
    score -= open_bins_count as f64 * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    // Later in the stream, small residuals (dead space) become more costly.
    let dead_penalty = prn * prn * (1.0 - prn) * (0.5 + 2.5 * prog2 + 3.0 * prog3);
    score += dead_penalty * cap;

    // Lookahead: reward residuals that can still host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 3.0 * (1.0 - slack * slack) * (1.0 + progress);
        } else {
            // next item won't fit here: penalize proportionally to the shortfall
            let gap = (nx - pr) / cap;
            score += 2.0 * gap * gap * cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild bonus for bins with company, scaled by tightness
        let tight = 1.0 - prn;
        score -= (fitting_bins_count.min(5) as f64).ln() * tight * 1.5;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter packing)
    let mean_gap = (mean_residual - pr) / cap;
    score -= mean_gap * (1.0 + prog2);

    // Mild penalty for very full bins early (keep flexibility), reward late
    let fullness = 1.0 - prn;
    score += fullness * fullness * (1.0 - 2.0 * progress) * 2.0;

    // Slight bias against opening new bins when several are open and fit
    if bin_residual == bin_capacity {
        score += 6.0 + 3.0 * progress + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) heavily rewarded,
    // small unusable slivers (1..10) heavily penalized.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score += 25.0;
    } else if post_residual <= 10 {
        score += 12.0;
    } else {
        // Modulo classes: residuals that are multiples of 10 are "harmonic"
        // (likely reusable by future 10-multiple items).
        let r = post_residual % 10;
        if r == 0 {
            score -= 8.0;
        } else if r <= 2 {
            score += 6.0;
        }
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 {
                score -= 15.0; // near-perfect chain
            } else {
                score -= 5.0 * (1.0 - leftover as f64 / cap);
            }
        } else {
            // next item cannot use this bin's residual -> residual may be dead space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Integer-division thresholds on bin fill fraction.
    let fill_quarters = (bin_capacity - bin_residual) / (bin_capacity / 4);
    score -= fill_quarters as f64 * 4.0; // prefer fuller bins (best-fit flavor)

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly so we
    // only open a new bin when no existing bin scores well.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream or crowded state: opening fresh bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 15.0;
        }
        if open_bins_count > 8 {
            score += 10.0;
        }
    }

    // Prefer bins with below-mean residual (close out emptier bins first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // even the minimum plausible item are essentially wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, zero waste
    } else if post_residual <= 10 {
        // small dead space: nearly unusable later, but at least it was a tight fit
        score -= 30.0;
    } else if post_residual <= 25 {
        // moderate dead space: mildly penalized on top of raw residual
        score += 10.0;
    } else {
        // large leftover: could still host future items, mild reward relative to residual
        score += 0.0;
    }

    // Perfect-fit bonus scaled by residual size
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when open bins
    // already exist; penalize unless the current item is huge and would leave
    // a tiny unusable gap elsewhere.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let waste_elsewhere = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64
        } else {
            0.0
        };
        score += 60.0 + open_pressure * 5.0;
        // if placing in any open bin would leave a tiny gap, opening a new bin is fine
        if waste_elsewhere > 0.0 && waste_elsewhere < 10.0 {
            score -= 100.0;
        }
        // early stream: slightly cheaper to open bins to build a good portfolio
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into the post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 120.0;
        } else if slack <= 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // Prefer bins with below-average residual (tighter bins fill first),
    // keeping looser bins available for awkward items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Mild penalty per open bin to discourage bin proliferation overall
    score += open_bins_count as f64 * 0.5;

    // Progress-aware residual weighting: later in the stream, dead space hurts more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: small post_residual.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to the leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative-to-mean residual shaping: prefer bins that absorb more than average.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0) * 0.6;
    } else {
        score += (res - mean_residual).min(50.0) * 0.4;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin candidate slightly unless the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        score += 45.0 + (item_size as f64) * 0.1;
    }

    // Late-stream tightening: as stream progresses, avoid leaving awkward residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Avoid leaving residuals that nothing (10..80 range) can ever use again.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual quadratically.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Dead-space penalty: post-residual that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer filling bins that are already relatively full (larger used fraction).
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 15.0;

    // Global pressure: many open bins with low mean residual -> consolidate into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual < bin_capacity {
        score -= pressure * 1.5;
    }

    // Time horizon: early in the stream, opening new bins is cheap (keep score high for new bins);
    // late in the stream, consolidate aggressively.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - t);
    } else {
        score -= 10.0 * t;
    }

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize wasting a large bin on a small item when residual stays huge.
    if post_residual > 70 {
        score += (post_residual as f64 - 70.0) * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 2.0 * progress) + 3.0 * x * x * (0.5 + progress);

    // Reward tight fits, amplified as stream progresses
    let tight = 1.0 - x;
    score -= tight * tight * (1.0 + 3.0 * progress) * 2.0;

    // Penalize dead space below typical next-item sizes (smooth kernel)
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * 4.0 * (0.5 + progress);
        // Reward reserving room for the lookahead item
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= fit_next * (nxt / cap) * (1.0 + progress) * 2.0;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 5.0 * (0.5 + progress);
    }

    // Mild penalty for bin proliferation
    score += open_bins_count as f64 * 0.02 * (1.0 + progress);

    // Slight preference for filling bins below mean residual (balance avoidance)
    score += (mean_residual - pr) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and near-perfect fits are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect packing, no dead space
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr > 50 {
        score += 15.0; // large leftover: wasteful unless new bin
    }

    // Modulo classes: residuals that are multiples of common item sizes (10,20,25)
    // remain usable by future items -> reward them.
    if pr % 10 == 0 && pr > 0 { score -= 8.0; }
    if pr % 25 == 0 && pr > 0 { score -= 6.0; }
    if pr % 20 == 0 && pr > 0 { score -= 5.0; }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0; // chained perfect fit
        } else if next_item_size <= pr {
            score -= 12.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; penalize more if leftover is awkward
            score += 5.0 + 0.1 * (pr as f64);
        }
        // next item exactly divides residual -> harmonic continuation
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 10.0;
        }
    } else {
        // last item: any residual is pure waste
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad class.
    if bin_residual == bin_capacity {
        let bad_fit = pr > 30 || (next_item_size > 0 && next_item_size > pr && pr > 0);
        if bad_fit {
            score -= 18.0;
        } else {
            score += 12.0; // prefer reusing existing bins when fit is decent
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual context: if this bin is far from mean, adjust.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Fragmentation pressure: many open bins -> prefer tight fits.
    if open_bins_count > 5 {
        score += 0.02 * (open_bins_count as f64) * (pr as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, min item size) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // wasted dead space
    } else if post_residual == 0 {
        // Perfect fit: strongly reward
        score -= 25.0;
    } else {
        // Tight fit reward: scale by how well the gap is filled
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio;
    }

    // Dead-space coupling: residual that can't fit the next item is also wasted
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item (chaining)
        score -= 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor filling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins below mean residual (keep residuals balanced, avoid
    // creating one very empty and many nearly-full bins)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: base cost of opening a fresh bin.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Opening a new bin is attractive when the item is large and would
        // leave a well-usable residual, or when no open bin fits well.
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 {
            score -= 18.0 * large_item;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Two-step lookahead core ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward proportionally to how tight the fit is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize dead space left behind.
            let dead = post_residual as f64;
            let ratio = dead / bin_capacity as f64;
            // Small dead space is worse than large (large may serve future items).
            score += 25.0 * (1.0 - ratio) * ratio.max(0.05);
        }

        // If next item fits *exactly* only in this configuration, extra reward.
        if post_residual == next_item_size && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    } else {
        // Last item: simply minimize waste.
        score -= 10.0;
    }

    // ---- Last-chance bonus: only this bin can host the item ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // ---- Mean residual coupling ----
    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling a bin far below the mean residual consolidates waste.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when:
        //  - the item is large relative to capacity (poor fits elsewhere), or
        //  - few bins can fit the item and mean residual is small (no useful space).
        let item_ratio = item_size as f64 / bin_capacity as f64;
        let mean_ratio = mean_residual / bin_capacity as f64;
        let open_bonus = item_ratio * 70.0
            + (1.0 - mean_ratio) * 40.0
            + (1.0 - progress) * 10.0;
        score += 100.0 - open_bonus; // base penalty for opening a bin, reduced by conditions
        // If next item also fits in a fresh bin together, slightly favor opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild preference for tighter fits overall (small post residual squared).
    score += 0.05 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly (fractional fill of the bin).
    score -= 1.7 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 100.0;

    // Penalize dead space that can never fit typical items again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 2.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer fullest packing
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 0 {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 8.0 + 6.0 * (1.0 - crowding) - 4.0 * t;
        // early stream: keep new bins cheap to spread capacity; late stream: expensive
        score += 20.0 * (1.0 - t);
    }

    // Time horizon: late in stream, be greedier about tight fits.
    score *= 1.0 + 0.3 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 18.0 * fit_norm * fit_norm * (1.0 + t);
    score -= 12.0 * fit_norm * (1.0 - t) * (1.0 - t);
    // Reward near-perfect fits (small post residual) more aggressively over time
    score -= 25.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (0.4 + 0.6 * t);
    // Penalize leaving residuals that match neither current nor next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let mismatch = (pr - nxt).abs() / cap;
        score += 15.0 * mismatch * mismatch * t;
        if pr >= nxt {
            score -= 8.0 * (1.0 - mismatch);
        }
    } else {
        score += 5.0 * fit_norm;
    }
    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + t);
    }
    // Mild penalty for spreading across many open bins early
    score += 0.5 * (open_bins_count as f64) * (1.0 - t) * fit_norm;
    // New-bin candidate: keep neutral baseline so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 40.0 + 20.0 * t;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 create "dead zones"
    let post_class = post_residual % 10;
    let post_quotient = post_residual / 10;
    // Penalize small nonzero residues (unusable slivers)
    if post_residual > 0 {
        score += (10 - post_class) as f64 * 0.35;
        // Reward large quotients (residual still usable for many items)
        score -= post_quotient as f64 * 1.2;
    } else {
        // Perfect fill: strong reward
        score -= 25.0;
    }

    // Harmonic class of next item relative to post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward, especially if it exactly fills (harmonic pairing)
            let next_res = post_residual - next_item_size;
            score -= 6.0;
            if next_res % 10 == 0 || next_res == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit: penalize leaving a residual it could have used
            score += 3.0;
        }
        // Modulo coupling between next item size and capacity classes
        let next_class = next_item_size % 20;
        score += (next_class as f64) * 0.08;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count > 0 {
            // If some open bin fits reasonably (post residual <= ~30), discourage new bin
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins deviating from mean (tighten spread)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Stream progression: late in stream, be greedier (minimize residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Open bins pressure: many open bins -> consolidate
    if open_bins_count > 4 {
        score -= (open_bins_count as f64 - 4.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Zero post_residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Reward when the next item fits exactly into the post residual (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // Next item cannot use this residual: penalize large wasted capacity.
            score += 0.15 * (post_residual as f64);
        } else {
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 10 {
                score += 25.0; // creates a dead gap for the next item
            } else {
                score -= 8.0; // next item still leaves usable space
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin (only fitting bin): strong reward to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Slight preference for tighter bins overall.
    score += 0.25 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step match)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 100.0; // perfect chain: both slots fully used
        } else {
            score += gap * 0.9; // penalize mismatch between post space and next item
        }
        // Bonus if next item still fits after this placement
        if next_item_size <= post_residual {
            score -= 15.0;
        }
        // Penalize leaving dead space too small for the next item
        if next_item_size > post_residual && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Last item: prefer tightest fill
        score += post_residual as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (good fits)
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit (new-bin candidate gets slight penalty)
    if bin_residual == bin_capacity {
        score += 8.0;
        // but allow new bin if item is large and fits poorly anywhere
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mild penalty for waste proportional to post residual, scaled by how many bins are open
    score += post_residual as f64 * (0.02 * open_bins_count as f64).min(0.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    // (items in [1,100]; residuals < 10 are nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would be blocked by the post residual, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 20.0; // perfect pairing
            } else {
                score -= 8.0;
            }
        } else if next_item_size <= bin_residual {
            // placing here forces next item into a new bin; small penalty
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are genuinely fragmented or full-ish.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins grows with number of open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;

        // If open bins have small mean residual (fragmented), a new bin is attractive.
        if mean_residual < item_size as f64 * 1.5 {
            score -= 30.0;
        }

        // Late in the stream, avoid opening bins that will be mostly wasted.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;

        // If next item is huge, an empty fresh bin is valuable for it.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Mild preference for reusing bins with larger residuals (big-first style).
        score -= 0.05 * bin_residual as f64;

        // Slight preference when this bin's residual is close to the mean
        // (keeps bin sizes homogeneous, easier future packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: normalized residual polynomial
    let norm_post = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * norm_post * norm_post * (1.0 + progress);

    // Tight-fit reward, stronger late in stream
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to next item
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap > 0.0 {
            score += 0.15 * gap * (1.0 + progress);
        } else {
            score -= 0.1 * gap.abs();
        }
    }

    // Last-chance fitting bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly unless current bin would be wasted
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    // Interaction with mean residual
    score += 0.05 * (mean_residual - post_residual as f64).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Penalize leftovers that are not "nice" sizes (dead space)
    score += class * 0.7;

    // Reward near-perfect fits strongly
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 30.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Harmonic bucket of the fit ratio
    let fit = item_size as f64 / cap;
    if fit > 0.9 {
        score -= 25.0;
    } else if fit > 0.7 {
        score -= 12.0;
    } else if fit < 0.3 {
        score += 8.0; // small item into big bin: wasteful
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            // harmonic mismatch penalty if leftover after both is awkward
            let both = pr - next_item_size;
            score += (both % 10) as f64 * 0.5;
        } else {
            // next item cannot follow in this bin; penalize slightly more
            // if this bin was the last chance
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin if existing fit is bad
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        } else {
            // open new bin if current best fit would leave large dead space
            if post_residual > bin_capacity / 2 {
                score -= 40.0;
            }
            // early in stream, opening bins is cheaper
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Prefer spreading across bins when many are open with high mean residual
    if open_bins_count > 1 {
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual below the minimum item size (1..100 interface => use 10 as heuristic floor)
    // is pure dead space; the smaller it is, the worse.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward it;
    // otherwise penalize leaving a residual that blocks the known next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer closing out existing bins
    // (tight placements) over spreading items; with few bins, opening new ones is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: penalize bins far below mean residual (they hoard space);
    // slight reward for bins close to the mean (balanced packing).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev.abs();

    // New-bin candidate: make empty bin moderately attractive only when residuals
    // across open bins are small (i.e., existing bins are nearly full).
    if bin_residual == bin_capacity {
        if mean_residual < item_size as f64 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with quadratic emphasis.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward when the next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0; // perfect chain: item + next item fills bin
        } else {
            score -= 18.0 * (1.0 - (gap as f64) / (bin_capacity as f64));
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving dead space proportionally.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 5.0; // small dead space is acceptable
        } else {
            score += 0.35 * dead;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (denser bins).
    score += 0.25 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; only allow
    // it when no open bin fits well (post_residual large relative to item).
    if bin_residual == bin_capacity {
        let stream_pos = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin grows with number of open bins.
        score += 55.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, discourage new bins even more (less time to fill them).
        score += 20.0 * stream_pos;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.4;
        }
    }

    // Mild penalty for very small leftover slivers that likely become dead space.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // Exact chain fit bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Penalize bins far from the mean residual (prefer balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: mild penalty so it's chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
        // But if the item is huge relative to mean residual, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 30.0 * poly;
    // Reward tight fits more strongly later in the stream
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).powi(3);
    score -= 20.0 * tightness * (0.5 + progress);
    // Penalize bins that leave residual unusable for the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).powi(2));
        } else {
            score += 12.0 * (nx - pr) / cap;
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * norm_pr;
    // Mean residual alignment term
    score += 5.0 * (norm_pr - mean_residual / cap).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by divisibility
    let pr = post_residual;
    let small_dead = pr > 0 && pr < 10; // unusable sliver
    if small_dead {
        score += 60.0; // penalize tiny dead space
    }

    // Modulo-class coupling: residuals divisible by common item sizes (10/20/25/50) are reusable
    if pr % 10 == 0 { score -= 8.0; }
    if pr % 20 == 0 { score -= 6.0; }
    if pr % 25 == 0 { score -= 5.0; }
    if pr % 50 == 0 { score -= 4.0; }

    // Integer division thresholds on post_residual relative to next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward proportional to snugness
            let snug = (pr - next_item_size) as f64;
            score -= 15.0 - snug * 0.1;
            if pr == next_item_size { score -= 30.0; }
        } else {
            // lookahead cannot use this residual; penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Fraction-of-capacity classes for residual
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 25.0 * (0.1 - frac); // near-full is good, but slivers bad (already penalized)
    } else if frac > 0.5 {
        score += 5.0; // wasteful large leftover
    }

    // New-bin candidate: only open a new bin when existing fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = bin_capacity as f64 * 0.75;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        } else if item_size >= 60 {
            // big item: opening fresh bin is often fine
            score -= 10.0;
        } else if fitting_bins_count == 1 {
            score += 30.0; // keep using the last-chance bin
        }
        // early stream: more willing to open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    }

    // Tie-break toward compacting bins below mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect or near-perfect fills get strong preference.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space penalty: small unusable gaps (below typical minimum item size 1..100,
    // gaps that no plausible next item can fill) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Next-item lookahead: if the next item fits the post residual exactly, reward;
    // if post residual cannot hold the next item, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.1 * (post_residual - next_item_size) as f64;
        }
    }

    // Open-bin pressure: discourage scattering items across many bins early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling fuller bins), leaving larger residual bins flexible.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate bias: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: large post_residual is waste, quadratic-ish pressure.
    score += (post_residual as f64) * (post_residual as f64) / (2.0 * bin_capacity as f64);

    // Perfect fit reward: near-zero post_residual is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chain: bin will be perfectly consumed
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // smaller gap after placing next item is better
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow here: post residual becomes dead space
            let dead = post_residual as f64;
            score += dead * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (concentrate packing), penalize using the loosest bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate handling: an empty bin should only win when the current
    // fit is bad (large post_residual). Add a fixed opening cost plus a mild
    // cost per already-open bin to encourage consolidation early on.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If next item fits well in the fresh bin, soften the opening cost.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: post_residual near zero is excellent.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // Last-chance bin: placing here avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier, penalize loose fits more.
        score += 8.0 * fit_ratio * (fitting_bins_count as f64).min(6.0);
    }

    // Lookahead: penalize if the next item could have used this residual better.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            // Next item still fits here; mild bonus proportional to leftover efficiency.
            score -= 6.0 * (1.0 - ((pr - nx) / bin_capacity as f64));
        } else {
            // Next item would be blocked by the residual left behind.
            score += 5.0 * (nx - pr) / bin_capacity as f64;
        }
    }

    // Global state coupling: if open bins are generally full (low mean residual),
    // prefer consolidating into this bin; if residuals are plentiful, be selective.
    let mr = mean_residual.max(0.0);
    score += 0.15 * (mr - post_residual as f64);

    // Time horizon: early in the stream, allow more slack (long game); late in the
    // stream, tighten up and pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress * fit_ratio;

    // Many open bins: discourage spreading items across too many bins unless tight.
    if open_bins_count > 8 {
        score += 0.5 * ((open_bins_count as f64) - 8.0).min(20.0) * fit_ratio;
    }

    // New-bin candidate: only attractive when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let urgency = (item_size as f64 / bin_capacity as f64) * (1.0 - progress * 0.5);
        score += 35.0 - 40.0 * urgency;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: minimize leftover space, with a convex penalty on small residuals
    // (tiny dead space is worthless), scaled by stream progress.
    let mut score = pr * (0.6 + 0.8 * progress)
        + (cap - pr) * (pr / cap).powi(2) * 4.0;

    // Non-linear coupling: item size vs. residual consumption shape.
    // Big items into big holes are good; small items into big holes waste.
    let fill_ratio = it / cap;
    score -= (fill_ratio * (1.0 - fill_ratio)) * cap * 0.5;

    // Lookahead: reward bins whose post_residual can host the next item,
    // penalize post_residual that is just barely unusable for it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (1.0 - (pr - nxt) / cap) * 6.0;
        } else {
            score += (nxt - pr) / nxt * 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer tighter bins relative to the open-bin population.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild preference to reuse bins as the stream matures (consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline, penalized when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + pr * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "nice" modular
    // classes (multiples of 10) pair well with typical item sizes -> reward them.
    let post_mod10 = post_residual % 10;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if post_mod10 == 0 {
        score -= 20.0;   // round leftover is reusable
    } else if post_mod10 >= 5 {
        score += 3.0 * (post_mod10 - 4) as f64; // awkward half-class leftovers
    } else {
        score += 1.5 * post_mod10 as f64;       // small dead-space penalty
    }

    // Integer-division thresholds on post_residual: leftover classes
    // [1..10), [10..20), [20..40), [40..100)
    let post_class = match post_residual {
        0 => 0,
        1..=9 => 1,
        10..=19 => 2,
        20..=39 => 3,
        _ => 4,
    };
    score -= post_class as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // harmonic residue match: next item leaves a multiple-of-10 remainder
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 25.0;
            }
            score -= 5.0;
        } else {
            // next item won't fit here: penalize proportional to waste risk
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): make it attractive only when open bins are
    // fragmented (high mean residual) or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Opening cost grows as stream progresses (less room to consolidate later)
        score = 45.0 + 60.0 * progress - 30.0 * fragmentation;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin also serves the bigger next item
        }
        if post_residual == 0 {
            score = -500.0; // item fills a bin exactly -> trivially open
        }
    }

    // Tie-breaker: prefer fuller bins (smaller residual) and fewer open bins.
    score += (bin_residual as f64) * 0.05;
    score -= open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful again (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fill is maximally rewarded.
        score -= 100.0;
    }

    // Encourage tight fits: reward small post_residual relative to item size.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones (penalize the new-bin candidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.9 * (0.5 + progress);

    // New-bin candidate detection: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Only attractive if nothing fits well, or the item is huge.
        let big_item = (item_size as f64) > 0.7 * (bin_capacity as f64);
        let poor_alternatives = fitting_bins_count <= 1;
        if !(big_item || poor_alternatives) {
            score += 45.0 + mean_residual * 0.3;
        } else {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement for preserving a usable gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Slight preference for bins tighter than the average residual
    // (best-fit flavor against the current bin population).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that end with minimal waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small post-residual is exponentially better (dead space penalty).
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Leftover can fit next item: mildly reward, scaled by tightness.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to wasted lookahead.
            let wasted = next_item_size as f64 - post_residual as f64;
            score += wasted * 0.3;
        }
    }

    // Relative to mean residual: bins tighter than average get preference.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect
    // two-item packing (item + next item exactly filling capacity).
    if bin_residual == bin_capacity {
        score += 300.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 800.0;
            }
        }
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Lookahead: penalize leaving a residual that the next item can't use,
    // reward residuals that pair well with the upcoming item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: opening a bin should be penalized, but less when the item
    // is large (little would be wasted) or when no bin fits well.
    if bin_residual == bin_capacity {
        let mut open_penalty = 30.0;
        // Large items waste little in a fresh bin.
        open_penalty -= 0.25 * item_size as f64;
        // If many bins fit, opening a new one is usually wasteful.
        if fitting_bins_count > 0 {
            open_penalty += 12.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // Early in the stream, allow more bins; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        open_penalty += 20.0 * progress;
        // If open bins have lots of slack, avoid new bins.
        open_penalty += 0.15 * mean_residual;
        // Avoid opening a bin whose leftover would strand the next item.
        if next_item_size > 0 && (bin_capacity - item_size) < next_item_size {
            open_penalty += 6.0;
        }
        score += open_penalty;
    }

    // Mild preference for bins already below mean residual (consolidating slack).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Slight preference for using more-open bins when many are open.
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - pr / cap;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses.
    let tightness = (fill_ratio - 1.0).powi(2); // near 0 for full bins
    score -= 12.0 * (1.0 - tightness) * (0.4 + 0.6 * progress);

    // Cubic dead-space penalty: residuals that are hard to reuse hurt more late.
    let dead = (pr / cap).powi(3);
    score += 25.0 * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: smooth exponential reward when this bin is the only fit.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let chain = (next_item_size as f64 / cap) * (1.0 - pr / cap);
        score -= 6.0 * chain;
    }

    // Mean-residual divergence: mildly penalize bins far from fleet mean (smooth quadratic).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: make empty bins attractive only for large items or late stream.
    if bin_residual == bin_capacity {
        score += 4.0 - 3.0 * (item_size as f64 / cap) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // classes (multiples of common item sizes / halves) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual by harmonic classes of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    let class_bonus = if post_residual == 0 {
        -30.0 // perfect fit, always reward heavily
    } else if (post_residual as f64) % 10.0 == 0.0 {
        -12.0 // leftover on the decimal grid: many items fit later
    } else if (pr - half).abs() < 1e-9 {
        -10.0 // exact half leftover
    } else if (pr - quarter).abs() < 1e-9 {
        -8.0 // exact quarter leftover
    } else if post_residual < 10 {
        15.0 // dead space: too small for any item (items >= 1 though; small penalty)
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold on post_residual vs next_item_size:
    // reward bins whose leftover can host the lookahead item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let ratio = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * (1.0 - ratio); // tight lookahead fit is great
        } else {
            // leftover can't host next item; penalize proportionally to waste
            score += 6.0 * (1.0 - (post_residual as f64 / cap).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading residuals when many bins are open: prefer filling
    // the tightest bins (post_residual already encodes this, add coupling).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * (0.5 + 0.5 * progress);

    // New-bin candidate: neutral-ish baseline, but open a fresh bin only when
    // all existing residuals are poor (harmonic class: residuals in dead zone).
    if bin_residual == bin_capacity {
        let poor = mean_residual < 20.0;
        score = if poor { 20.0 } else { post_residual as f64 + 8.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Prefer bins whose residual was already small (tight packing trend).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Open-bins pressure: with many open bins, favor reusing existing bins
    // (penalize opening new ones via the empty-bin candidate's low residual cost).
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mean residual coupling: avoid placing into bins far from the mean when stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit: heavily reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
