            } else {
                score += (post_residual - next_item_size as u32) as f64 * 0.8;
            }
        }
    }

    // Penalize bins far below mean residual (fragmented small leftovers)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: default neutral, penalize slightly so we prefer filling
    // open bins unless the fit is bad; exact-fit logic above already handles it.
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if no open bin fits well (item large relative to mean residual),
        // opening a fresh bin is fine
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Late in the stream: consolidate, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tight * tight;
    }

    // Small post-residual that can still host a typical future item is less dead.
    if post_residual >= 10 && post_residual <= 50 {
        score -= 6.0;
    } else if post_residual > 50 {
        score += 4.0; // large leftover wastes potential
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
