    }

    // New-bin candidate handling: penalize opening a bin unless it enables a great fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 80 {
            score -= 30.0; // big items deserve fresh bins
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Prefer bins with below-average residual (keep many-roomy bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Mild preference for using more-opened bins when many are open.
    if open_bins_count > 8 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score *= 1.0 - 0.35 * progress + 0.25 * prog2 - 0.10 * prog3;

    // Penalize unusable dead space: residuals smaller than any plausible item
    let min_item = 1.0f64;
    let dead = ((min_item - pr).max(0.0)) * 2.0;
    score += dead;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * (1.0 + progress) * 8.0;

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
