    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * (pr - next_item_size as f64).abs() / cap;
    }

    // Mild penalty for spreading across too many bins relative to mean residual
    score += 0.02 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: prefer keeping it closed unless open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 12.0 - 20.0 * fragmentation * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
