        // Harmonic fraction classes: post_residual as fraction of capacity.
        let frac = post_residual as f64 / cap;
        // Reward post residuals that are "harmonic" multiples: 25, 33, 50, 66, 75
        let harmonics = [25u32, 20, 33, 50, 66, 75];
        if harmonics.contains(&post_residual) {
            score -= 25.0;
        }
        // Quarter classes: post_residual divisible by 25 keeps future modularity.
        if post_residual % 25 == 0 {
            score -= 12.0;
        } else if post_residual % 10 == 0 {
            score -= 6.0;
        }
        // Penalize odd residuals in the mid range (hard to fill).
        if post_residual > 15 && post_residual < 45 && post_residual % 2 == 1 {
            score += 8.0;
        }
        // Coupling with next item: if next item fits exactly into post_residual,
        // strongly reward this bin (chained exact fill).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0;
            } else if next_item_size < post_residual {
                let next_post = post_residual - next_item_size;
                if next_post < 10 {
                    score += 30.0 - 3.0 * next_post as f64; // would create tiny dead space
                } else {
                    score -= 10.0;
                }
            } else {
                // next item won't fit here; mildly reward keeping residual large.
                score += 5.0;
            }
        }
        // Large residual left behind is fine only if few bins open; else prefer tight fits.
        if frac > 0.5 && open_bins_count > 3 {
            score += 15.0 * (frac - 0.5);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New empty bin candidate: only attractive when current fit is very poor
    // or no bins fit well. Penalize moderately so real fits usually win.
    if bin_residual == bin_capacity {
        score += 55.0 - 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, a fresh bin is more attractive.
        if (item_size as f64) > 0.6 * cap {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host a paired sequence
        }
    }

    // Slight preference for tighter bins overall (best-fit baseline reinforcement).
    score += (bin_residual as f64 - post_residual as f64).max(0.0) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit reward.
        score -= 30.0;
    }

    // Favor bins whose residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Open-bins pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.5;
    }

    // Progress-aware tightening: dead space matters more late in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual already does this).

    // 2-step lookahead: if the NEXT item fits exactly into the post_residual,
    // this placement is perfect — strongly reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still be placed here; mild reward proportional to fit quality.
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize wasted residual.
        score += post_residual as f64 * 0.10;
    }

    // Penalize leaving large unusable residual relative to mean residual.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.20;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let early = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins normally, but less when bins are fragmented
        // or late in the stream with many bins open.
        score += 60.0 - fragmentation * 40.0 - pressure * 3.0 + early * 10.0;
        // Exact-fit bonus for the fresh bin if item is large.
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for filling bins that are already mostly full.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins where the item fills a large fraction of the residual space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill_ratio * fill_ratio;

    // Penalize small post-residuals that are hard to reuse (dead space trap),
    // unless the residual is fully consumed (perfect fit is great).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }
    if post_residual == 0 {
        score -= 8.0;
    }

    // Lookahead: reward leaving a residual that can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 3.0;
        if slack == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving stranded space.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large and few bins are open, or late in the stream when mean
    // residual across open bins is small relative to the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        let mut nb = waste * 0.6;
        // Cheap to open early / few bins; expensive when many bins exist.
        nb -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Late stream with low mean residual: opening is more forgivable.
        if progress > 0.5 && mean_residual < item_size as f64 {
            nb -= 3.0;
        }
        // Perfect fit into fresh bin is wasteful unless item is huge.
        if item_size > 80 {
            nb -= 5.0;
        }
        score += nb;
    }

    // Slight global pressure: when open bins have large mean residual,
    // prefer bins close to that mean (keeps residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, mildly non-linearly
    let mut score = pr as f64 * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, tighten strongly
    let progress_coupling = (0.6 + 1.8 * t * t) * x * x;
    score += 40.0 * progress_coupling;

    // Reward filling bins nearly exactly, smoothly
    let fill = 1.0 - x;
    score -= 30.0 * fill * fill * fill * (0.5 + t);

    // Penalize leaving residuals that no typical item can use (dead space),
    // smooth via logistic-like term around small residuals
    let dead = (cap * 0.2 - pr).max(0.0) / cap;
    score += 25.0 * dead * dead * (1.0 + t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - t * 0.5);
    }

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 10.0 * ((nx - pr) / cap);
        }
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * x;

    // Mean-residual coupling: prefer bins near the mean residual for balance
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: penalize opening a new bin, more so later in stream
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * t;
        // but allow opening when no good fit exists (large item, few fitting bins)
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" residue classes (multiples of common item granularity) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Reward post-residuals divisible by 10 (harmonic with capacity 100).
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 20 == 0 {
            score -= 4.0;
        }
        if pr % 50 == 0 {
            score -= 3.0;
        }
        // Penalize awkward small dead space (1..9) heavily.
        if pr < 10 {
            score += 12.0;
        }
        // Integer-division thresholds: leftover big enough for a mid-size item.
        let quot = pr / 25; // 0..4
        score -= quot as f64 * 3.5;
    } else {
        // Perfect fit: strongest reward.
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 5.0;
        if pr % next_item_size.max(1) == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would waste a lot.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.6;
        if crowded || fitting_bins_count == 0 {
            score -= 10.0 + 5.0 * (1.0 - progress);
        } else {
            score += 8.0 + mean_residual * 0.05;
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.02;
    // Slight penalty for spreading across many bins late in the stream.
    score += open_bins_count as f64 * 0.01 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are "dead". Penalize small nonzero post_residuals hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else if post_residual <= 20 {
        // Semi-dead zone: many items are 10..80, residual <= 20 only fits tiny items.
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits generally: fraction of bin used by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // ones rather than opening more.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 12.0 + 6.0 * pressure;
        // But if no open bin leaves a good post_residual, new bin is attractive:
        // compare against mean residual of open bins.
        score += 0.15 * mean_residual;
    } else {
        score -= 4.0 * pressure.min(4.0);
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward;
    // if next item cannot fit post_residual but could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 50.0);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Late in the stream, be more conservative: avoid leaving awkward gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin will be exactly filled next step
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it fits
            let slack = post - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // extra reward if the following state leaves a small reusable gap
            if slack <= 10.0 {
                score -= 10.0;
            }
        } else {
            // next item does NOT fit into this bin's remainder: penalize
            let overshoot = nxt - post;
            score += 15.0 + 0.5 * overshoot;
        }
    } else {
        // last item: strongly prefer minimal final residual
        score += 5.0;
    }

    // Relative-to-mean coupling: bins tighter than average are preferred targets.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Penalize leaving large dead space relative to capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    if waste > 0.5 {
        score += 20.0 * (waste - 0.5);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        // but if next item is bigger than the residual, the last-chance value is reduced
        if next_item_size > post_residual {
            score += 12.0;
        }
    }

    // New-bin candidate handling: an empty bin has no urgency; make it slightly
    // less attractive than a decent fit, but attractive when open bins are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 8.0;
        // cheaper to open new bins late in the stream (less future to amortize)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // if many bins are open and fragmented, prefer consolidating into a new bin
        if open_bins_count > 3 {
            score -= 2.0 * (open_bins_count as f64 - 3.0).min(6.0);
        }
        // if next item is large, a fresh bin preserves room for it
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Mild pressure to close bins early in the stream (keep bin count low).
    score += 0.15 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * post_residual as f64;
        } else if post_residual > 0 {
            score += 6.0; // residual too small for lookahead item
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be frugal with bins; late, prioritize closure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - fill_ratio);

    // Global state: many open bins with high mean residual -> prefer reusing roomy bins.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 0.05 * mean_residual;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin offers a decent fit (i.e., this item is a poor fit everywhere else).
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        let mut nb = waste;
        // Attractive early, or when the item is huge (near-capacity) and residuals are small.
        if item_size >= 70 || (mean_residual < item_size as f64 && fitting_bins_count <= 1) {
            nb -= 35.0;
        }
        if progress > 0.8 {
            nb += 10.0 * progress; // late stream: keep closing bins, don't open new ones
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let cap = bin_capacity as f64;

    // Base: tight fit reward (quadratic in post_residual)
    let mut score = pr * pr / cap;

    // Smooth coupling: tightness preference strengthens as stream progresses
    score += pr * (0.5 + progress) * 0.3;

    // Reward filling a bin well relative to its prior residual (normalized fill ratio, non-linear)
    let fill = it / br.max(1.0);
    score -= fill * fill * 12.0;

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        if gap > 0.0 {
            score += gap * gap * 25.0 * (1.0 + progress);
        } else {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize mildly early, less later; compare against mean residual
    if bin_residual == bin_capacity {
        score = 20.0 + 10.0 * (1.0 - progress) + mean_residual * 0.05;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 15.0;
        }
    }

    // Slight penalty proportional to open bins to encourage consolidation
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // residue classes (multiples of common item sizes) are worth keeping.
    let pr = post_residual;
    if pr > 0 {
        // Perfect harmonic residuals: divisible by 10, 20, 25, 50 -> friendly to future items.
        let harmonic_bonus = if pr % 50 == 0 { 12.0 }
            else if pr % 25 == 0 { 8.0 }
            else if pr % 20 == 0 { 6.0 }
            else if pr % 10 == 0 { 4.0 }
            else { 0.0 };
        score -= harmonic_bonus;
    } else {
        // Perfect closure: huge reward.
        score -= 40.0;
    }

    // Penalize dead space: post_residual that can't fit even the smallest plausible item.
    if pr < 10 && pr > 0 {
        score += 15.0 + (10 - pr) as f64;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 5.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // Next item won't fit here; mildly penalize wasting a good bin.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with progress (waste less early? no:
        // late in stream, closing out bins matters more).
        let mut new_bin_score = 35.0 + 0.15 * open_bins_count as f64;
        // If item is large (> half capacity), a fresh bin is often fine.
        if item_size as f64 > cap * 0.5 {
            new_bin_score -= 10.0;
        }
        // Late in stream, prefer filling existing bins.
        new_bin_score += 20.0 * progress;
        score = score.max(new_bin_score.min(score)) ; // placeholder no-op
        score = new_bin_score;
        // Ensure a genuinely good existing fit (small post_residual) beats new bin.
        if post_residual < 20 && fitting_bins_count >= 1 {
            score += 30.0;
        }
    }

    // Mild tie-break toward bins below mean residual (consolidate space).
    score += 0.1 * (mean_residual - bin_residual as f64).abs().signum() * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are effectively wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 6.0 * (10 - post_residual as i32) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Bonus when this placement leaves room for the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 8 {
            score -= 10.0 - slack as f64;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual can't hold the next item: mild penalty scaled by gap
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: prefer packing into existing bins when many are open,
    // penalize spreading across bins when few are open.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream
    // and when existing bins have usable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 20.0 * progress;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: next item fits exactly into post_residual (2-step lookahead match)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // partial lookahead match: reward proportionally to how well it fits
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // next item won't fit here: penalize large dead space, worse when post_residual is big
            score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
        }
    } else {
        // last item: prefer tightest fit overall
        score += 0.1 * post_residual as f64;
    }

    // Penalize wasting space relative to current mean residual (dead-space penalty)
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large or no good fits exist
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // large items open fresh bins cheaply; small items should reuse open bins
        score += 400.0 * (1.0 - tightness);
        if fitting_bins_count > 0 {
            score += 100.0; // discourage opening when open bins can fit
        }
        // late in stream, opening new bins is less costly (fewer future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 200.0 * progress;
    }

    // Mild preference for filling nearly-full bins
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared waste penalty grows superlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Exact or near-exact fill is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose residual can pair with the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if nr <= pr {
            // Next item fits into the leftover: excellent chaining.
            let leftover_after_next = pr - nr;
            score -= 15.0 + 20.0 * (1.0 - leftover_after_next / bin_capacity as f64);
        } else if nr <= bin_residual as f64 {
            // Next item would have fit before this placement; mild penalty.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in the stream, be conservative (prefer new bins
    // for large items to keep flexibility); late, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Global state: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // New-bin candidate: penalize slightly so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is huge and would leave a big hole elsewhere,
        // opening fresh is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Reward leaving residuals that match common small item sizes.
    let pr = post_residual;
    if pr > 0 && (pr <= 20 || (30..=50).contains(&pr)) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize wasted space, weighted non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear penalty on tiny unusable residuals (dead space)
    let dead = (norm_pr * 20.0 - 3.0).max(0.0).min(2.0);
    score += 15.0 * dead * dead * norm_pr;

    // Polynomial coupling of post_residual with mean residual: reward leaving
    // space close to the average demand of upcoming items
    let next_f = next_item_size as f64;
    let coupling = (norm_pr * cap - next_f) / cap;
    score += 4.0 * coupling * coupling * (1.0 + progress);

    // If lookahead item fits exactly in the post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - chain_fit / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize when lookahead cannot use leftover space
        score += 2.0 * (next_f / cap) * (1.0 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // New-bin candidate: penalize mildly early, less late; encourage opening
    // fresh bins when current bins have large residuals
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.1 - 0.3 * progress)
            + 5.0 * (mean_residual / cap).max(0.0);
    }

    // Slight preference for filling bins that are already well used
    score -= 2.0 * (1.0 - norm_pr) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals near multiples of common
    // item sizes (10,20,25,40,50) are more reusable; odd residuals are dead space.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // capacity fraction of the leftover

    // Penalize tiny-but-nonzero leftovers (dead space classes)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Reward residuals that land on harmonic classes (multiples of 10/20/25/50)
    if post_residual % 50 == 0 && post_residual > 0 { score -= 12.0; }
    else if post_residual % 25 == 0 && post_residual > 0 { score -= 8.0; }
    else if post_residual % 10 == 0 && post_residual > 0 { score -= 5.0; }
    else if post_residual % 5 == 0 { score -= 1.0; }
    else { score += 3.0; } // inharmonic leftover

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.1 * (next_item_size as f64);
        } else {
            // leftover too small for next item: penalize more if far off
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty for picking a bad one, favor tightest
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: opening a bin is expensive; only attractive when
    // the item is large relative to capacity or all open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 2.0 };
        let base = 0.55 * cap_f; // default cost of a fresh bin
        let discount = (pressure - 1.0).max(0.0) * 20.0
            + if fitting_bins_count == 0 { 30.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= item_size { 5.0 } else { 0.0 };
        score = base - discount + frac * 10.0;
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about spreading (consolidate into open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
        // prefer bins below mean residual (more filled bins first)
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (>=1) can
    // use are wasted; small gaps (1..=9) are "dead" since items are >=1 but
    // typically much larger. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as f64) * 4.0;
    }
    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (small post_residual as
    // fraction of capacity).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is truly awful).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bins pressure: many open bins with slack -> prefer consolidating
    // into existing bins rather than fragmenting capacity further.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; filling low-slack bins keeps the fleet tidy.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.15;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 12.0;
        } else {
            // next item cannot use the gap: mild penalty proportional to gap
            score += (post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate logic: an empty bin has residual == capacity. Only
    // attractive when the item is large and no good existing fit exists,
    // or the stream is early and preserving small gaps matters later.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin; cheap when item is big.
        score = 30.0 - 20.0 * fill_fraction;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin leaves room for lookahead item
        }
        // Late in the stream, avoid spawning bins with tiny leftover potential.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && fill_fraction < 0.5 {
            score += 25.0 * (0.8 - progress).abs() * 10.0;
        }
    }

    // Mild preference for filling bins that are already mostly full.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to wasted capacity
            let gap = (next_item_size - post_residual) as f64;
            score += 80.0 * (gap / bin_capacity as f64);
        }
    }

    // Prefer bins tighter than average (best-fit style)
    score -= 50.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly unless current residuals are all large
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * open_bins_count as f64;
        // but if no good fit exists (all residuals much larger than item), allow new bin
        if mean_residual > (item_size as f64) * 1.8 {
            score -= 60.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 100.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / bin_capacity as f64) * 15.0;
    }
    // If next item would be blocked by a large post-residual gap, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Scarcity of fitting bins: reward any fitting bin when choices are few.
    if fitting_bins_count > 1 {
        score += 3.0; // slight penalty so tightest bin among many wins via residual terms
    }

    // Global residual coupling: penalize bins far from mean residual (prefer homogeneous packing),
    // except reward small residuals.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming);
    // late in stream, conserve bins (penalize new-bin candidate).
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: cost grows over time and with number of open bins.
        score += 20.0 + t * 45.0 + (open_bins_count as f64) * 1.5;
        // But if item is large and no open bin fits well, new bin is fine.
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 15.0;
        }
    } else {
        // Filling existing bins becomes more attractive over time.
        score -= t * 10.0;
    }

    // Prefer filling bins that are already substantially used.
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used * 15.0;

    // Penalize leaving medium dead space (hard to fill later).
    if post_residual >= 10 && post_residual <= 30 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: best-fit preference for minimal leftover space.
    let mut score = post;

    // Non-linear penalty on dead space: residuals that are small but unusable
    // (below the minimum plausible item size) are the worst outcome.
    let min_item = 1.0f64;
    let dead = (min_item - post).max(0.0);
    score += 12.0 * (dead * dead) / cap;

    // Smooth reward for near-perfect packing: strongly favor very small residuals.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= 8.0 * tightness * tightness * tightness;

    // Polynomial coupling with stream progress: early on, tolerate slack to keep
    // bins flexible; late in the stream, aggressively squeeze leftovers.
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 6.0 * progress_coupling * tightness;
    score += 4.0 * (1.0 - progress_coupling) * (post / cap);

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // if next item is large and this bin wastes space, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_fit = 1.0 - ((post - nxt) / cap);
            score -= 5.0 * slack_fit * slack_fit;
        } else {
            let gap = (nxt - post) / cap;
            score += 3.0 * gap * gap * progress_coupling;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across too many open bins relative to stream length.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Slight preference toward bins already below-average residual (consolidation).
    score += 0.3 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item
    // sizes are more reusable, so reward (subtract) for "harmonic" leftovers.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmony += 3.0;
            }
        }
        // Small residuals in low harmonic classes are near-dead space.
        if pr < 10 {
            score += 25.0; // dead space penalty
        } else if pr <= 20 {
            score += 8.0;
        }
        score -= harmony;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this leftover: mild penalty proportional
        // to wasted harmonic fraction.
        let wasted = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * wasted;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitter.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 15.0 * progress;
        // But if mean residual across open bins is tiny, opening is fine.
        if mean_residual < 10.0 {
            score -= 25.0;
        }
    }

    // Prefer tighter bins: reward closeness of fit via integer division class.
    let fit_class = (item_size * 4) / bin_capacity; // 0..3 quarter classes
    score -= (4 - fit_class) as f64 * 2.0;

    // Mean-residual alignment: bins near the mean residual are "typical";
    // deviating bins get slight penalty for fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste, but residuals that cannot fit the NEXT item are worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Penalize tiny unusable gaps harder as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 5 {
        score += 10.0 + 15.0 * progress;
    }

    // Reward tight fits strongly (near-zero post residual).
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 3 {
        score -= 8.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; slightly cheaper early on.
        score += 25.0 + 8.0 * bin_pressure - 10.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= 4.0 * bin_pressure;
    }

    // Prefer bins whose residual is close to what we consume (good fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill_ratio;

    // Mild preference to keep mean residual balanced (avoid hoarding one big bin).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills this bin's post residual (2-step lookahead match).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect chain: item then next item exactly consume the bin.
        if post_residual == next_item_size {
            score -= 200.0;
        }
    }

    // Penalize residuals that are too small to ever be useful (dead space), especially small residuals.
    let r = post_residual as f64;
    if r < 10.0 {
        score += 120.0 * (10.0 - r);
    } else if r < 25.0 {
        score += 40.0 * (25.0 - r) / 15.0;
    }

    // Favor tight fits relative to mean residual: prefer bins with residual close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness);

    // Relative to mean residual: prefer bins whose post residual aligns with the average slack.
    score -= 20.0 * ((r - mean_residual).abs() / bin_capacity as f64).recip().min(1.0);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: mild penalty so we prefer reusing bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.1 * open_bins_count as f64;
        // If lookahead chains perfectly in a fresh bin, allow opening it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 120.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (better long-run structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Slight preference among many candidates for tighter fits already handled above.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here: penalize leaving a large stranded residual.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Penalize bins whose residual is far below the mean residual (already squeezed bins)
    // unless the fit is tight — favor spreading load across bins evenly.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.5;
    } else {
        score -= (-diff) * 0.25;
    }

    // Early in the stream: encourage consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * (1.0 - progress) * 2.0;
    }

    // New-bin candidate: only attractive when item is large and fits poorly everywhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // Penalize opening a new bin, but less when the item is big.
        score += 35.0 - 20.0 * fill_ratio;
        // If no open bins exist at all, opening is free.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - progress) + prn * progress * (1.0 - prn) * (1.0 - prn);
    score += 12.0 * poly;

    // Prefer tight fits more strongly later in the stream
    let tight = 1.0 - prn;
    score -= tight * tight * (1.0 + 2.0 * progress) * 6.0;

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - (nx / pr).min(1.0));
        } else {
            score += 3.0 + 5.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin's space
    if fitting_bins_count == 1 {
        score -= 2.5 + 4.0 * tight;
    }

    // Mild pressure from number of open bins and mean residual
    score += (open_bins_count as f64).ln().max(0.0) * 0.4;
    score -= (mean_residual - pr) * 0.05;

    // New-bin candidate: make empty bin attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score += 1.0 - 3.0 * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that stay "reusable"
    // (multiples of common item granularity 10), penalize awkward leftovers.
    let pr = post_residual as u32;
    if pr > 0 {
        let cls = pr % 10;
        if cls == 0 {
            score -= 6.0; // perfectly reusable residual
        } else if cls <= 2 {
            score += 4.0; // near-dead sliver
        } else if cls >= 8 {
            score += 2.0; // awkward, almost a full unit
        }
        // Integer-division thresholds: residuals below the smallest item are dead.
        if pr < 10 {
            score += 25.0; // unusable dead space
        }
    } else {
        score -= 12.0; // perfect closure
    }

    // Tight-fit reward: relative waste fraction (harmonic in capacity).
    let waste_frac = post_residual as f64 / cap;
    score -= 10.0 * (1.0 - waste_frac) * (1.0 - waste_frac);

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0); // mild penalty spread over alternatives
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to mean residual (i.e., open bins are too full to be useful).
    if bin_residual == bin_capacity {
        let base = 18.0;
        let scarcity = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).min(4.0)
        } else {
            4.0
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base - 6.0 * scarcity - 5.0 * progress;
        // Few open bins -> opening is cheap; many open bins -> discourage.
        score += 0.4 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly
    // (harmonic modulo match), reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 8.0 - 0.3 * (leftover as f64 / 10.0);
        } else {
            // next item won't fit here anyway; slight penalty for wasting space
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer filling bins that are already partially used when residuals are large.
    if bin_residual != bin_capacity {
        score -= 2.0 * (mean_residual - post_residual as f64).max(0.0) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible future item are wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness bonus: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But if no open bin fits well (large post_residual elsewhere), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: bins far below mean residual are less attractive targets.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild early-stream preference to fill bins rather than spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 600.0;
    }
    // Next item fits into the post residual: mildly good chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 80.0 + 40.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
    }
    // Next item will NOT fit here: penalize leaving dead space relative to mean residual.
    if next_item_size > 0 && next_item_size > post_residual {
        let waste = post_residual as f64;
        score += 60.0 + waste * (1.0 + waste / mean_residual.max(1.0));
    }

    // Small post residuals are hard to fill later: quadratic penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 3.0;

    // Early in the stream, be more willing to open new bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean residual; cheaper late when bins are many.
        score = mean_residual + 20.0 - 30.0 * progress;
        if item_size > 50 {
            score += 10.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual) {
            score += 2000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize post_residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 0.6 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large dead space if the leftover is unlikely to fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.05 * post_residual as f64;
        } else {
            score += 4.0;
        }
        // chain fit: leftover fits next item exactly
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fit competition
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: penalize opening a new bin generally,
    // but relax the penalty when existing bins have large mean residual
    // that is fragmented (many bins, high mean residual -> poor consolidation).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let mut new_bin_penalty = 35.0;
        // If mean residual is small, existing bins are nearly full; opening
        // a new bin is less costly relative to scattering items.
        new_bin_penalty -= 20.0 * (1.0 - fragmentation);
        // Late in the stream, avoid opening new bins even more
        new_bin_penalty += 10.0 * progress;
        // Many open bins already: discourage more sprawl
        new_bin_penalty += 1.5 * (open_bins_count as f64).sqrt();
        score += new_bin_penalty.max(0.0);
    } else {
        // Reward filling existing bins, more so early on
        score -= 6.0 * (1.0 - progress);
    }

    // Coupling: if this bin's residual is far below the mean residual,
    // it's a "small" bin worth closing out with a decent fit.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += 0.05 * diff;
    } else {
        score -= 0.03 * (-diff);
    }

    // Mild penalty for placing huge items into nearly-full bins leaving nothing
    if item_size >= 70 && post_residual <= 30 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1])
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: mildly discourage near-empty leftovers (keep bins flexible).
    // Late in the stream: strongly reward tight fits (minimize dead space).
    let pr = post_residual as f64 / bin_capacity as f64;
    let coupling = progress * (1.0 - pr) * (1.0 - pr) - (1.0 - progress) * pr * pr;
    score -= 12.0 * coupling;

    // Quadratic penalty on large post-residual, amplified by progress.
    score += 0.6 * pr * pr * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can host the next item exactly,
    // penalize post-residuals that waste space relative to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            let gap = (nxt - post_residual as f64) / bin_capacity as f64;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless post_residual is huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - pr);
    }

    // Penalize the brand-new empty bin candidate smoothly, more so when
    // open bins exist and the stream is early (keep bin count down).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 18.0 * (1.0 - progress) * openness + 10.0 * openness * (1.0 - pr);
    }

    // Mild mean-residual regularization: prefer bins below mean residual
    // (concentrate usage into tighter bins).
    let mean_pr = mean_residual / bin_capacity as f64;
    score += 4.0 * (pr - mean_pr) * (1.0 - progress);

    // Small non-linear tie-breaker on fill fraction.
    let fill = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 3.0 * fill * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: bins whose leftover falls
    // into "harmonic" classes (multiples of small divisors of capacity) are
    // more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: post_residual == 0 -> perfect fit, reward heavily.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Harmonic class via integer division thresholds on post_residual.
        // Small leftovers (<10) are nearly dead space -> penalize.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual % 10 == 0 {
            // Round harmonic class: highly reusable -> reward.
            score -= 25.0;
        } else if post_residual % 25 == 0 {
            score -= 20.0;
        } else if post_residual % 5 == 0 {
            score -= 8.0;
        } else {
            // Non-harmonic leftover: mild penalty scaled by how far from the
            // nearest multiple of 5 it lies.
            let dist = (post_residual % 5).min(5 - post_residual % 5) as f64;
            score += 3.0 * dist;
        }
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post-residual, this placement chains perfectly -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits, evaluate the resulting second-order leftover.
            let second_left = post_residual - next_item_size;
            if second_left % 10 == 0 || second_left == 0 {
                score -= 45.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item does not fit in this bin afterwards: if the next item
            // is large relative to capacity, prefer keeping this bin's
            // residual small anyway; slight penalty for big leftovers.
            if post_residual < next_item_size && next_item_size > cap * 0.5 {
                score += 12.0;
            }
        }
    } else {
        // Last item: any residual is pure waste; prefer exact fill.
        score += pr * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral anchor score. Prefer it only when all open
    // bins would leave highly fragmented (non-harmonic) residuals.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, opening bins is cheap; later, reuse matters.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into bins with below-average residual.
    if bin_residual != bin_capacity {
        let dev = mean_residual - pr;
        if dev > 0.0 {
            score -= dev * 0.3;
        } else {
            score += (-dev) * 0.15;
        }
    }

    // Fraction-of-capacity harmony: reward placements leaving residual near
    // simple capacity fractions (1/4, 1/2, 3/4) since many item sizes cluster there.
    let fracs = [cap * 0.25, cap * 0.5, cap * 0.75];
    for f in fracs.iter() {
        let d = (pr - f).abs();
        if d < 3.0 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (< 12) are almost unusable -> heavy penalty
    if post_residual < 12 {
        score -= 40.0 + (12 - post_residual) as f64 * 3.0;
    } else if post_residual < 25 {
        score -= 8.0;
    }

    // Reward near-perfect packing
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the resulting residual, favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this gap: penalize proportional to wasted potential
        score += 5.0 + (post_residual as f64).min(60.0) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer already-open bins when many are open,
    // but allow new bins early in the stream or when current bin is a poor fit
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when open bins exist and are reasonably filled
        score += (open_bins_count as f64) * 6.0 + progress * 20.0 - fill_ratio * 0.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin leaves full residual for lookahead only if nothing fits well
            if fitting_bins_count > 0 {
                score += 10.0;
            }
        }
    } else {
        // existing bin: mild reward scaled by how full it already is
        score -= fill_ratio * 10.0;
        score -= (open_bins_count as f64) * 0.5;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a "tight" bin,
    // keep filling it; if far above mean, it's roomy, deprioritize slightly
    let res = post_residual as f64;
    score += (res - mean_residual) * 0.15;

    // Global pressure to close bins as stream progresses
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact match of next item into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let slack_after_next = post - next;
            // Reward tight packing of the lookahead item.
            score -= 18.0 * (1.0 - slack_after_next / bin_capacity as f64);
            // Extra bonus for near-perfect two-item fill.
            if slack_after_next <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Post residual too small for next item: penalize unusable dead space.
            let dead = post;
            score += 0.5 * dead;
            // If the dead space is tiny, it's basically full anyway — mild reward.
            if dead <= 3.0 {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins tighter than average get priority.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Reward filling bins deeply (small post_residual relative to capacity).
    let fill_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_frac * fill_frac;

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // But if next item is huge and nothing fits it later, new bin may be OK.
        if next_item_size > 60 && post_residual == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual strongly favored.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness * tightness;

    // Penalize exact-fit waste asymmetry: prefer post_residual that is either
    // near zero or large enough to host a typical future item.
    let usable_gap = if post_residual >= next_item_size && next_item_size > 0 {
        -6.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64
    } else {
        3.0 * post_residual as f64 / bin_capacity as f64
    };
    score += usable_gap;

    // Lookahead: if the next item fits in the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here afterwards; mild penalty for blocking chain packing.
        score += 2.0 * (next_item_size - post_residual.min(next_item_size)) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is wasteful when many
    // open bins exist with slack; encourage closing out near-full bins instead.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        // Penalize new bins early / when aggregate slack is large.
        score += 25.0 * (1.0 - progress) + 10.0 * pressure.min(3.0);
        // But if nothing fits well (post_residual of best fit would be tiny debris),
        // the base comparison may still favor a new bin; soften slightly.
        score -= 5.0 * (1.0 - tightness);
    }

    // Prefer filling bins whose residual deviates below mean (drain small bins first).
    if bin_residual < bin_capacity {
        let dev = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score -= 4.0 * dev;
    }

    // Mild preference for fewer open bins overall (consolidation pressure).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr
        + 12.0 * norm_pr * norm_pr * (1.0 + progress)
        - 6.0 * norm_pr * progress * (1.0 - progress);

    // Reward tight fits: penalize large post_residual more as stream progresses.
    score += 20.0 * (norm_pr * (1.0 - progress)).powi(3);

    // Lookahead: reward if next item fits into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 * (next_item_size as f64 / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap) * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: prefer it only when post residual is very large and stream is early.
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress) * (1.0 - norm_pr);
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 2.0 * ((pr - mean_residual) / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: mod-10 classes on capacity 100.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Penalize residuals in "dead" classes (1..9, 11..19 small slivers)
    let class = pr % 10;
    if pr > 0 && pr < 10 {
        score += 60.0; // unusable sliver
    } else if pr >= 10 && pr < 20 {
        score += 8.0;
    }

    // Reward residuals that are exact divisors / multiples of common item sizes
    if pr > 0 {
        if pr % 20 == 0 { score -= 12.0; }
        else if pr % 25 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 2.0; }
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 100.0;
    }

    // Integer-division threshold: how many more items of next size fit after placement
    if next_item_size > 0 && pr > 0 {
        let fits_next = pr / (next_item_size.max(1) as i64);
        if fits_next >= 1 {
            score -= 10.0 * fits_next as f64;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0;
        }
        // Harmonic coupling: residual divisible by next item size is great
        if next_item_size as i64 > 0 && pr % (next_item_size as i64) == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline tuned against typical open-bin scores
    if bin_residual == bin_capacity {
        score = (bin_capacity - post_residual) as f64 + 15.0;
        // early stream: opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac;

    // Penalize spreading across many bins when mean residual is large
    if open_bins_count > 0 {
        let ratio = mean_residual / bin_capacity as f64;
        if ratio > 0.5 && bin_residual != bin_capacity {
            score += 4.0 * (ratio - 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are nearly useless
    // for items >= 10, so punish them super-linearly.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual >= 10 {
        // Usable residual: mild reward scaled by how close it is to a
        // "half-bin" style reusable chunk.
        score -= 2.0;
        if post_residual >= 50 {
            score -= 3.0;
        }
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post-fit residual is dead).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual >= 1 && post_residual <= 9 {
            score += 18.0; // but not if it creates dead space
        }
    }

    // New-bin candidate: empty bin. Prefer it only when no good fit exists
    // among open bins (i.e., this placement would leave dead space or the
    // item is large relative to residuals).
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its residual is large (usable), so
        // start slightly penalized vs. a tight existing fit.
        score += 10.0;
        // Open-bin pressure: many open bins -> discourage opening more.
        score += 2.5 * open_bins_count as f64;
        // If the item nearly fills a fresh bin, opening is attractive.
        if fill > 0.7 {
            score -= 25.0;
        }
        // Lookahead: if the next item would combine with this one's
        // residual, a new bin is fine.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Existing bin: mild open-bin pressure reward (consolidation).
        score -= 0.5 * open_bins_count as f64;
        // Lookahead synergy: residual after placement fits next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // residual too small for lookahead -> dead space risk
        }
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (less future to amortize) -> favor existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mean residual coupling: if open bins are on average roomy, prefer
    // filling them rather than creating another roomy bin.
    if bin_residual != bin_capacity && mean_residual > item_size as f64 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact match where post_residual equals half the next item
    // (item + next item would perfectly fill the bin).
    if next_item_size > 0 {
        let target = next_item_size as f64 * 0.5;
        let gap = (post_residual as f64 - target).abs();
        score -= 18.0 * (1.0 / (1.0 + gap * gap * 0.05));

        // Reward if next item fits exactly in the post residual.
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // Next item can't follow here: penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: pure tightness matters.
        score -= 10.0;
    }

    // Tight fit reward relative to residual before placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize creating tiny unusable slivers (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: bins already lean are precious.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless item is huge
    // relative to residual options (opening fresh bin for big items is fine).
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 20.0;
        }
        // Prefer fresh bin late in stream when many bins are open and fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 4 && mean_residual < 25.0 {
            score -= 8.0 * progress;
        }
    }

    // Mild preference for filling fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize tiny useless leftovers, but forgive exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // If next item almost fits (within a small gap), mild penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // this placement would leave a very poor residual in an existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        let mut open_penalty = 55.0 + 45.0 * waste;
        // Late in the stream, opening bins is less costly (fewer future items to fill them).
        open_penalty *= 1.0 - 0.35 * progress;
        // Many open bins with slack: prefer consolidating into them.
        if mean_residual > item_size as f64 {
            open_penalty += 10.0;
        }
        score += open_penalty;
    }

    // Mild preference for filling bins with larger residuals among equals,
    // keeping mean residual low avoids accumulating many half-empty bins.
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);
    }

    // Fragmentation guard: avoid leaving residuals that only fit tiny items.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: tight fit preferred, with smooth non-linear shaping
    let mut score = pr + 12.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Penalize residuals that are large but too small for typical items (dead space)
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score += 8.0 * dead * (1.0 - progress);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = (next_item_size as f64 / pr.max(1.0)) - 1.0;
        score -= 10.0 * (1.0 + snug * snug);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty scaled by how close it is
        let gap = (next_item_size as f64 - pr) / cap;
        score += 6.0 * gap * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a bin, more so mid-stream
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Last chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mean residual coupling: placing into a bin below-mean residual is attractive
    score -= 3.0 * ((mean_residual - pr) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fractional fill of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;

    // Reward high fill non-linearly (best-fit core).
    score -= 24.0 * fill * fill;

    // Harmonic class of post_residual: dead space that no future item
    // (sizes 1..=100) can realistically use is costly. Classify by
    // integer division thresholds.
    let pr = post_residual as u32;
    let dead = if pr == 0 {
        0.0
    } else if pr <= 5 {
        0.0 // near-perfect fit, tiny waste
    } else if pr <= 15 {
        1.0
    } else if pr <= 30 {
        2.0
    } else if pr <= 50 {
        4.0
    } else {
        6.0
    };
    score += 3.0 * dead;

    // Perfect closure bonus: bin exactly full.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits in the post-residual,
    // penalize if post-residual is awkwardly just below next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= pr {
            score -= 6.0; // chain placement possible
            // extra reward if it nearly fills the bin afterward
            let pr2 = pr - next_item_size as u32;
            if pr2 <= 10 {
                score -= 5.0;
            }
        } else if pr > 0 && (next_item_size as u32) - pr <= 5 {
            score += 4.0; // teasing gap: dead space for the known next item
        }
        // harmonic threshold on next item size
        let nclass = if next_item_size <= 25 { 0 } else if next_item_size <= 50 { 1 } else { 2 };
        score -= nclass as f64 * 1.5 * fill;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // the item is large (would leave big unusable residual elsewhere)
    // or few bins are open.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        let pressure = mean_residual / cap;
        score = 40.0
            - 25.0 * large_item
            - 10.0 * (1.0 - pressure)
            - 2.0 * open_bins_count as f64;
        // early in stream, new bins are cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // if item exactly fills a fresh bin, great
        if post_residual == 0 {
            score -= 35.0;
        }
        return score;
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size of 1..=100 streams, treat < 15)
    // are heavily penalized; a perfect fit (0) is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Large leftover space is somewhat valuable; mild reward.
        score -= 4.0;
    }

    // Reward tight fits relative to bin residual (small waste ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or
        // mean residual is still large (plenty of room elsewhere).
        score += 30.0 + 3.0 * pressure + 20.0 * progress;
        // But allow opening a new bin if the next item won't fit anywhere
        // after this placement and no bin is a "last chance" fit.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count == 1 {
            score -= 25.0;
        }
    } else {
        // Existing bin: slight reward for using bins, stronger when it is
        // the only fitting bin (last chance) to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        } else {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Coupling with mean residual: bins with residual far below the mean
    // are "almost full" — prefer filling them to close them out.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 3.0 * dev / (bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin becomes exactly full next step
        } else if next_item_size < post_residual {
            let slack_after_next = post_residual - next_item_size;
            // small slack after next item is good; large slack is dead space
            score -= 20.0 / (1.0 + slack_after_next as f64);
            score += slack_after_next as f64 * 0.25;
            // next item could pair with the residual left behind
            if slack_after_next >= 10 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this bin's residual; residual is stranded for one step
            score += 6.0;
            // stranded residual is worse late in the stream (fewer chances to use it)
            score += progress * 10.0;
        }
    } else {
        // last item: any residual is permanent waste
        score += 40.0;
    }

    // Tight fits now are good: reward small post_residual relative to item size.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 25 {
        score -= 5.0;
    }

    // Compare against mean residual: prefer bins whose residual is close to item size
    // (best-fit style), penalize bins far above/below the mean.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large and open bins would leave big dead space.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin, offset by how well it will pack the item
        score = 45.0 + post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can also host the next item
        }
        if item_size >= 50 {
            score -= 10.0; // large items pack cleanly into fresh bins
        }
        // late in the stream, avoid opening new bins for small leftovers
        if item_size < 30 && progress > 0.7 {
            score += 30.0;
        }
    }

    // Mild preference to fill already-open bins as they accumulate.
    score += 0.5 * open_bins_count as f64;

    score
}
